# Override builtins.print to prevent "ValueError: I/O operation on closed file"
# when running in gui-only mode or as packaged PyInstaller executable without a console.
_orig_print = builtins.print
def safe_print(*args, **kwargs):
    try:
        if sys.stdout and not getattr(sys.stdout, 'closed', False):
            _orig_print(*args, **kwargs)
    except Exception:
        pass
builtins.print = safe_print
