    'LSID', 'LSOSID', 'OSID', 'S', '__Secure-OSID', 'SIDCC',
    'OGPC', 'OGP', 'ACCOUNT_CHOOSER',
    # Tracking / continuity (cần cho session score)
    'NID', '1P_JAR', '3P_JAR', 'AEC', '__Secure-ENID', 'CONSENT', 'SOCS',
