def extract_product_name_from_path(path: str) -> str:
    try:
        p = Path(path)
        for parent in p.parents:
            if "_" in parent.name:
                parts = parent.name.split("_", 1)
                if len(parts) > 1 and parts[0] and len(parts[0]) >= 8:
                    if parts[1].strip():
                        return parts[1].strip()
    except Exception:
        pass
    return Path(path).stem


def resolve_moved_product_path(path_str: str) -> str:
    if not path_str:
        return ""
    p = Path(path_str)
    if p.exists():
        return str(p)
    try:
        parts = p.parts
        pid = None
        for part in parts:
            if "_" in part:
                prefix = part.split("_")[0]
                if len(prefix) >= 8:
                    pid = prefix
                    break
        if pid:
            prod_json = DOWNLOADS_DIR / "products.json"
            if prod_json.exists():
                products = json.loads(prod_json.read_text(encoding="utf-8"))
                prod = next((pr for pr in products if pr.get("product_id") == pid), None)
                if prod:
                    folder_name = prod.get("folder", "Chưa phân loại")
                    safe_title = clean_filename(prod.get("title", "product"))
                    subpath_parts = []
                    found_product_dir = False
                    for part in parts:
                        if found_product_dir:
                            subpath_parts.append(part)
                        elif part.startswith(pid):
                            found_product_dir = True
                    subpath = "/".join(subpath_parts) if subpath_parts else "images/1.jpg"
                    
                    if folder_name and folder_name != "Chưa phân loại":
                        new_path = DOWNLOADS_DIR / folder_name / f"{pid}_{safe_title}" / subpath
                    else:
                        new_path = DOWNLOADS_DIR / f"{pid}_{safe_title}" / subpath
                        
                    if new_path.exists():
                        return str(new_path)
    except Exception:
        pass
    return ""

