def is_veo_model(model_name: str) -> bool:
    """Kiểm tra model có phải là Veo 3/Google AI Sandbox (không phải Grok)."""
    if not model_name:
        return False
    m = model_name.lower()
    return any(kw.lower() in m for kw in VEO_MODEL_KEYWORDS) and "grok" not in m


