if _old_role_skill_dir.exists():
    import shutil
    for f in _old_role_skill_dir.glob("*.MD"):
        dest = ROLE_SKILLS_DIR / f.name
        try:
            shutil.copy2(f, dest)
        except Exception:
            pass
