def get_role_skill_path(filename: str):
    if not filename:
        return None
    p = APP_DIR / "Role Skill" / filename
    if p.exists():
        return p
    p = ROLE_SKILLS_DIR / filename
    if p.exists():
        return p
    return APP_DIR / "Role Skill" / filename


def _get_safe_project_name(project_id: str) -> str:
    if not project_id:
        return "default"
    try:
        import re, json
        target_file = PROJECTS_FILE
        if not target_file.exists():
            target_file = DATA_DIR / "projects.json"
        if target_file.exists():
            data = json.loads(target_file.read_text("utf-8"))
            for p in data:
                if p.get("id") == project_id:
                    name = p.get("name", "").strip()
                    if name:
                        safe = re.sub(r'[\\/:*?"<>|]', '_', name)
                        return f"project_{safe[:50].strip(' .')}"
    except Exception:
        pass
    return f"project_{project_id.strip(' .')}"


# ── Migration: di chuyển project JSON files vào data/projects/ ──
def _migrate_project_json_files():
    """Tự động di chuyển project JSON từ root vào data/projects/project_xxx/."""
    import shutil
    # Migrate story_projects JSON
    for f in APP_DIR.glob("project_*_story_projects.json"):
        parts = f.stem.split("_")
        # project_{id}_story_projects -> id is parts[1]
        if len(parts) >= 3:
            proj_id = parts[1]
            dest_dir = PROJECTS_DATA_DIR / f"project_{proj_id}"
            dest_dir.mkdir(exist_ok=True)
            dest = dest_dir / "story_projects.json"
            if not dest.exists():
                shutil.copy2(f, dest)
    # Migrate animal_project JSON
    for f in APP_DIR.glob("animal_project_*.json"):
        proj_id = f.stem.replace("animal_project_", "")
        dest_dir = PROJECTS_DATA_DIR / f"project_{proj_id}"
        dest_dir.mkdir(exist_ok=True)
        dest = dest_dir / "animal_project.json"
        if not dest.exists():
            shutil.copy2(f, dest)
    # Migrate projects.json index to data/
    old_projects = APP_DIR / "projects.json"
    new_projects = DATA_DIR / "projects.json"
    if old_projects.exists() and not new_projects.exists():
        shutil.copy2(old_projects, new_projects)

_migrate_project_json_files()

