@dataclass
class Project:
    """Đại diện cho một dự án tạo video."""
    id:          str  = field(default_factory=lambda: uuid.uuid4().hex[:12])
    name:        str  = "Untitled Project"
    mode:        str  = "studio"      # "studio" | "storyboard" | "animal" | "roleskill"
    created_at:  str  = ""
    job_count:   int  = 0
    done_count:  int  = 0
    failed_count:int  = 0
    pending_count:int = 0
    status:      str  = "idle"        # "idle" | "generating" | "completed" | "failed"
    role_skill_file: str = ""

    def __post_init__(self):
        if not self.created_at:
            self.created_at = datetime.now().strftime("%d/%m/%Y %H:%M")

    @property
    def history_file(self) -> Path:
        return APP_DIR / f"project_{self.id}_history.json"

    def to_dict(self) -> dict:
        return {
            "id": self.id, "name": self.name, "mode": self.mode,
            "created_at": self.created_at, "job_count": self.job_count,
            "done_count": self.done_count, "failed_count": self.failed_count,
            "pending_count": self.pending_count, "status": self.status,
            "role_skill_file": self.role_skill_file,
        }

    @staticmethod
    def from_dict(d: dict) -> "Project":
        return Project(
            id=d.get("id", uuid.uuid4().hex[:12]),
            name=d.get("name", "Untitled"),
            mode=d.get("mode", "studio"),
            created_at=d.get("created_at", ""),
            job_count=d.get("job_count", 0),
            done_count=d.get("done_count", 0),
            failed_count=d.get("failed_count", 0),
            pending_count=d.get("pending_count", 0),
            status=d.get("status", "idle"),
            role_skill_file=d.get("role_skill_file", ""),
        )



