@dataclass
class StoryProject:
    """Một dự án Storyboard Pipeline — 1 sản phẩm = 1 project."""
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:12])
    name: str = ""             # Tên hiển thị / tên thư mục output
    project_id: str = ""  # ID của project cha từ dashboard
    product_image_path: str = ""
    product_info: str = ""
    product_visual_desc: str = ""
    video_title: str = ""
    script_json: dict = field(default_factory=dict)
    scenes: list = field(default_factory=list)  # List[StoryScene]
    final_video_path: str = ""
    status: str = "queued"  # queued | scripting | generating | assembling | done | failed
    error_msg: str = ""
    created_at: str = ""
    # Settings
    num_scenes: int = 4
    seconds_per_scene: int = 10
    panels_per_storyboard: int = 8
    aspect: str = "16:9"
    aspect_label: str = "Ngang (16:9)"
    img_model: str = "gpt-image-2"
    vid_model: str = "grok-imagine-video-1.5-preview"
    llm_model: str = "gpt-4o"
    img_size: str = "1536x1024"
    img_quality: str = "standard"
    video_resolution: str = "720p"
    audio_val: str = "sound_effects_only"
    system_prompt_override: str = ""
    max_retries: int = 3
    render_only: str = "both"  # both | image | video
    clone_count: int = 1
    voice_paths: list = field(default_factory=list)  # Danh sách voice cho lồng tiếng
    reference_image_paths: list = field(default_factory=list)
    selected_context: str = ""
    mode: str = "storyboard"
    role_skill_file: str = ""
    use_proxy: bool = True
    # Cache output_dir để tránh path thay đổi giữa các lần gọi
    _cached_output_dir: str = field(default="", init=False, repr=False)

    def __post_init__(self):
        if not self.created_at:
            self.created_at = datetime.now().strftime("%d/%m/%Y %H:%M:%S")

    @property
    def output_dir(self) -> Path:
        # Return cached path nếu đã tạo trước — đảm bảo luôn cùng path
        if self._cached_output_dir:
            d = Path(self._cached_output_dir)
            d.mkdir(parents=True, exist_ok=True)
            return d
        import re
        base_dir = ROLESKILL_OUTPUT_DIR if getattr(self, "mode", "storyboard") == "roleskill" else STORYBOARD_OUTPUT_DIR
        # Ưu tiên self.name, fallback sang extract từ product_info hoặc image path
        _name = self.name.strip() if self.name.strip() else ""
        if not _name and self.product_info:
            _name = self.product_info.strip().split('\n')[0].strip()[:120]
        _safe_name = re.sub(r'[\\/:*?"<>|]', '_', _name)[:120].strip(" .") if _name else ""
        _folder = _safe_name if _safe_name else f"story_{self.id}"
        if self.project_id:
            d = base_dir / _get_safe_project_name(self.project_id) / _folder
        else:
            d = base_dir / _folder
        d.mkdir(parents=True, exist_ok=True)
        # Cache lại để đảm bảo luôn cùng path
        object.__setattr__(self, '_cached_output_dir', str(d))
        return d

    def scene_dir(self, scene_num: int) -> Path:
        d = self.output_dir / f"scene_{scene_num:02d}"
        d.mkdir(parents=True, exist_ok=True)
        return d

    @property
    def product_name(self) -> str:
        """Tên hiển thị: ưu tiên self.name, fallback về trích xuất từ path."""
        if hasattr(self, 'name') and self.name and self.name.strip():
            return self.name.strip()
        if self.product_image_path:
            name_from_path = extract_product_name_from_path(self.product_image_path)
            if name_from_path and not name_from_path.startswith("collage_"):
                self.name = name_from_path
                return name_from_path
            return Path(self.product_image_path).stem
        return f"project_{self.id[:6]}"

    @property
    def progress_pct(self) -> int:
        if not self.scenes:
            return 0
        done = sum(1 for s in self.scenes if s.status in ("done", "failed"))
        return int(done / len(self.scenes) * 100)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "name": self.name,
            "project_id": self.project_id,
            "product_image_path": self.product_image_path,
            "product_info": self.product_info,
            "product_visual_desc": self.product_visual_desc,
            "video_title": self.video_title,
            "script_json": self.script_json,
            "scenes": [s.to_dict() if isinstance(s, StoryScene) else s for s in self.scenes],
            "final_video_path": self.final_video_path,
            "status": self.status,
            "error_msg": self.error_msg,
            "created_at": self.created_at,
            "num_scenes": self.num_scenes,
            "seconds_per_scene": self.seconds_per_scene,
            "panels_per_storyboard": self.panels_per_storyboard,
            "aspect": self.aspect,
            "aspect_label": self.aspect_label,
            "img_model": self.img_model,
            "vid_model": self.vid_model,
            "llm_model": self.llm_model,
            "img_size": self.img_size,
            "img_quality": self.img_quality,
            "video_resolution": self.video_resolution,
            "audio_val": self.audio_val,
            "system_prompt_override": self.system_prompt_override,
            "max_retries": self.max_retries,
            "render_only": self.render_only,
            "clone_count": self.clone_count,
            "voice_paths": getattr(self, "voice_paths", []),
            "reference_image_paths": self.reference_image_paths,
            "selected_context": self.selected_context,
            "mode": getattr(self, "mode", "storyboard"),
            "role_skill_file": getattr(self, "role_skill_file", ""),
            "use_proxy": getattr(self, "use_proxy", False),
            "_cached_output_dir": self._cached_output_dir,
        }

    @staticmethod
    def from_dict(d: dict) -> "StoryProject":
        sp = StoryProject(
            id=d.get("id", uuid.uuid4().hex[:12]),
            name=d.get("name", ""),
            project_id=d.get("project_id", ""),
            product_image_path=d.get("product_image_path", ""),
            product_info=d.get("product_info", ""),
            product_visual_desc=d.get("product_visual_desc", ""),
            video_title=d.get("video_title", ""),
            script_json=d.get("script_json", {}),
            final_video_path=d.get("final_video_path", ""),
            status=d.get("status", "queued"),
            error_msg=d.get("error_msg", ""),
            created_at=d.get("created_at", ""),
            num_scenes=d.get("num_scenes", 4),
            seconds_per_scene=d.get("seconds_per_scene", 10),
            panels_per_storyboard=d.get("panels_per_storyboard", 8),
            aspect=d.get("aspect", "16:9"),
            aspect_label=d.get("aspect_label", "Ngang (16:9)"),
            img_model=clean_model_name(d.get("img_model", "gpt-image-2")),
            vid_model=clean_model_name(d.get("vid_model", "grok-imagine-video-1.5-preview")),
            llm_model=clean_model_name(d.get("llm_model", "gpt-4o")),
            img_size=d.get("img_size", "1536x1024"),
            img_quality=d.get("img_quality", "standard"),
            video_resolution=d.get("video_resolution", "720p"),
            audio_val=d.get("audio_val", "sound_effects_only"),
            system_prompt_override=d.get("system_prompt_override", ""),
            max_retries=d.get("max_retries", 3),
            render_only=d.get("render_only", "both"),
            clone_count=d.get("clone_count", 1),
            reference_image_paths=d.get("reference_image_paths", []),
            selected_context=d.get("selected_context", ""),
            mode=d.get("mode", "storyboard"),
            role_skill_file=d.get("role_skill_file", ""),
            use_proxy=d.get("use_proxy", False),
        )
        sp.voice_paths = d.get("voice_paths", [])
        sp.scenes = [StoryScene.from_dict(s) for s in d.get("scenes", [])]
        # Restore cached output dir để path không bị thay đổi sau khi load lại
        cached = d.get("_cached_output_dir", "")
        if cached:
            object.__setattr__(sp, '_cached_output_dir', cached)
        return sp


