class JobWorker(QThread):
    progress_sig = pyqtSignal(str, float)
    status_sig = pyqtSignal(str, str, str)
    log_sig = pyqtSignal(str)

    def __init__(self, job: VideoJob, client: GrokClient):
        super().__init__()
        self.job = job
        self.client = client
        self.veo_bearer = ""
        self.veo_project_id = ""
        self.captcha_bridge = None

    def run(self):
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        
        def log_cb(m): self.log_sig.emit(m)
        def prog_cb(v): self.progress_sig.emit(self.job.id, v)

        try:
            loop.run_until_complete(run_job(
                self.job, self.client, log=log_cb, progress=prog_cb,
                veo_bearer=self.veo_bearer, veo_project_id=self.veo_project_id,
                captcha_bridge=self.captcha_bridge
            ))
            self.status_sig.emit(self.job.id, self.job.status, self.job.local_path or self.job.error or "")
        except Exception as e:
            self.status_sig.emit(self.job.id, "failed", str(e))
        finally:
            loop.close()


class ThumbnailWorker(QThread):
    done_sig = pyqtSignal(str)

    def __init__(self, job_id: str, video_path: str):
        super().__init__()
        self.job_id = job_id
        self.video_path = video_path

    def run(self):
        try:
            vpath = Path(self.video_path)
            tpath = THUMB_DIR / f"{self.job_id}.jpg"
            if not vpath.exists() or tpath.exists():
                return
            import subprocess
            import sys
            cmd = [
                sys.executable, "-c",
                "import cv2, sys; cap=cv2.VideoCapture(sys.argv[1]); success, frame=cap.read(); cv2.imwrite(sys.argv[2], frame) if success else sys.exit(1)",
                str(vpath), str(tpath)
            ]
            res = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, creationflags=_CNOW)
            if res.returncode == 0:
                self.done_sig.emit(self.job_id)
        except Exception:
            pass


class ImageGenWorker(QThread):
    status_sig = pyqtSignal(str, str, str) # job_id, status, local_path or error
    log_sig = pyqtSignal(str)
    
    def __init__(self, client: GrokClient, prompt: str, model: str, size: str, 
                 quality: str, output_format: str, output_compression: int, 
                 background: str, moderation: str, output_name: str, out_folder: Path):
        super().__init__()
        self.client = client
        self.prompt = prompt
        self.model = model
        self.size = size
        self.quality = quality
        self.output_format = output_format
        self.output_compression = output_compression
        self.background = background
        self.moderation = moderation
        self.output_name = output_name
        self.out_folder = out_folder
        self.job_id = f"img_{uuid.uuid4().hex[:6]}"
        self.veo_bearer = ""
        self.veo_project_id = ""
        self.google_account_name = ""
        self.google_profile_name = ""
        self.captcha_bridge = None
        self.use_proxy = True

    def run(self):
        is_veo = is_veo_model(self.model)
        if is_veo:
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            try:
                self.log_sig.emit(f"🚀 Bắt đầu tạo ảnh Veo 3 với model [{self.model}]...")
                ar = "1:1"
                try:
                    w, h = map(int, self.size.split("x"))
                    if w == h:
                        ar = "1:1"
                    elif w < h:
                        ar = "9:16" if h >= 1500 else "3:4"
                    else:
                        ar = "16:9" if w >= 1500 else "4:3"
                except Exception:
                    pass

                job = VideoJob(
                    id=self.job_id,
                    model=self.model,
                    prompt=self.prompt,
                    aspect_ratio=ar,
                    output_name=self.output_name,
                    local_path=str(self.out_folder),
                    use_proxy=self.use_proxy,
                    account_name=self.google_account_name,
                    google_profile_name=self.google_profile_name,
                )
                success = loop.run_until_complete(run_veo_flow(
                    job, self.veo_bearer, self.veo_project_id, self.captcha_bridge,
                    log=lambda m: self.log_sig.emit(m), progress=None
                ))
                if success and job.local_path and Path(job.local_path).exists():
                    self.status_sig.emit(self.job_id, "done", job.local_path)
                else:
                    self.status_sig.emit(self.job_id, "failed", job.error or "Tạo ảnh thất bại")
            except Exception as e:
                self.log_sig.emit(f"❌ Lỗi tạo ảnh Veo 3: {e}")
                self.status_sig.emit(self.job_id, "failed", str(e))
            finally:
                loop.close()
            return

        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        try:
            self.log_sig.emit(f"🚀 Bắt đầu tạo ảnh với model [{self.model}]...")
            img_type, img_val = loop.run_until_complete(
                self.client.generate_image(
                    self.prompt, self.model, self.size,
                    self.quality, self.output_format, self.output_compression,
                    self.background, self.moderation,
                    use_proxy=self.use_proxy
                )
            )
            self.log_sig.emit("📥 Đang lưu ảnh thành phẩm...")
            
            self.out_folder.mkdir(parents=True, exist_ok=True)
            ext = self.output_format.lower()
            fname = (self.output_name or f"image_{self.job_id}").replace(" ", "_")
            out_file = self.out_folder / f"{fname}.{ext}"
            
            if img_type == "base64":
                img_bytes = base64.b64decode(img_val)
                with open(out_file, "wb") as f:
                    f.write(img_bytes)
            else:
                loop.run_until_complete(self.client.download(img_val, out_file, use_proxy=self.use_proxy))
                
            self.log_sig.emit(f"✅ Tạo ảnh hoàn tất -> {out_file.name}")
            self.status_sig.emit(self.job_id, "done", str(out_file))
        except Exception as e:
            self.log_sig.emit(f"❌ Lỗi tạo ảnh: {e}")
            self.status_sig.emit(self.job_id, "failed", str(e))
        finally:
            loop.close()

