class SBProductSceneRow(QWidget):
    """Một dòng hiển thị kết quả phân cảnh bên trong SBProductCard."""
    def __init__(self, scene_idx: int, data: dict, parent=None):
        super().__init__(parent)
        self.scene_idx = scene_idx
        self.data = data
        self.card = parent
        self.view_mode = "grid"
        self.setObjectName(f"scene_row_{scene_idx}")
        
        # Tooltip hiển thị prompt chi tiết
        tooltip_txt = (
            f"<b>Phân cảnh {scene_idx + 1}</b><br>"
            f"🎨 <i>Prompt ảnh:</i> {data['img_prompt']}<br><br>"
            f"🎥 <i>Prompt video:</i> {data['vid_prompt']}"
        )
        self.setToolTip(tooltip_txt)

        # Cảnh # label + title + purpose
        scene_title = data.get("title", "")
        scene_purpose = data.get("purpose", "")
        title_text = f"🎬 #{scene_idx + 1}"
        if scene_title:
            title_text += f" {scene_title}"
        if scene_purpose:
            purpose_colors = {"hook": "#ef4444", "detail": "#8b5cf6", "action": "#f59e0b", 
                            "feature": "#3b82f6", "lifestyle": "#10b981", "CTA": "#ec4899"}
            pc = purpose_colors.get(scene_purpose, "#64748b")
            title_text += f' <span style="color:{pc};font-size:8px;">({scene_purpose})</span>'
        self.lbl_title = QLabel(title_text)
        self.lbl_title.setTextFormat(Qt.TextFormat.RichText)
        self.lbl_title.setStyleSheet("font-weight: bold; font-size: 10px; color: #475569;")

        # Storyboard Thumbnail (Click to zoom)
        self.lbl_thumb = QLabel()
        self.lbl_thumb.setStyleSheet("background: #e2e8f0; border: 1px solid #cbd5e1; border-radius: 4px; color: #94a3b8; font-size: 8px;")
        self.lbl_thumb.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.lbl_thumb.setText("⏳")
        self.lbl_thumb.mouseDoubleClickEvent = self._on_double_click_storyboard

        # Video Output Thumbnail (Click to play)
        self.lbl_video_thumb = QLabel()
        self.lbl_video_thumb.setStyleSheet("background: #e2e8f0; border: 1px solid #cbd5e1; border-radius: 4px; color: #94a3b8; font-size: 8px;")
        self.lbl_video_thumb.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.lbl_video_thumb.setText("🎬")
        self.lbl_video_thumb.mouseDoubleClickEvent = self._on_double_click_video_thumbnail

        # Status text
        self.lbl_status = QLabel("Chờ")
        self.lbl_status.setStyleSheet("color: #64748b; font-size: 8px; font-weight: bold;")

        # Text edits for List view mode
        self.edit_img_prompt = QTextEdit(self)
        self.edit_img_prompt.setPlaceholderText("Prompt tạo ảnh storyboard...")
        self.edit_img_prompt.setText(data.get("img_prompt", ""))
        self.edit_img_prompt.setStyleSheet("QTextEdit { background: #ffffff; border: 1px solid #cbd5e1; border-radius: 4px; padding: 2px; font-size: 9px; color: #1e293b; }")
        self.edit_img_prompt.textChanged.connect(self._on_img_prompt_changed)
        self.edit_img_prompt.setVisible(False)

        self.edit_vid_prompt = QTextEdit(self)
        self.edit_vid_prompt.setPlaceholderText("Prompt chuyển động video...")
        self.edit_vid_prompt.setText(data.get("vid_prompt", ""))
        self.edit_vid_prompt.setStyleSheet("QTextEdit { background: #ffffff; border: 1px solid #cbd5e1; border-radius: 4px; padding: 2px; font-size: 9px; color: #1e293b; }")
        self.edit_vid_prompt.textChanged.connect(self._on_vid_prompt_changed)
        self.edit_vid_prompt.setVisible(False)

        # Action Buttons
        self.btn_play = QPushButton("▶")
        self.btn_play.setToolTip("Phát video phân cảnh này")
        self.btn_play.setFixedSize(26, 26)
        self.btn_play.setEnabled(False)
        self.btn_play.setStyleSheet(self._btn_style("#0284c7", "#0369a1"))
        self.btn_play.clicked.connect(self._play_video)

        self.btn_dl = QPushButton("⬇")
