            btn_zoom_vid.setStyleSheet("QPushButton { background: transparent; border: none; font-size: 10px; } QPushButton:hover { background: #e2e8f0; border-radius: 3px; }")
            btn_zoom_vid.clicked.connect(self._zoom_vid_prompt)
