            lbl.setStyleSheet("font-weight: bold; font-size: 9px; color: #94a3b8; background: transparent;")
            if stretch:
                hdr_lay.addWidget(lbl, stretch=1)
            else:
                if text == "✅":
                    lbl.setFixedWidth(30)
                elif text == "Cảnh":
                    lbl.setFixedWidth(60)
                elif text in ("Cắt đầu (s)", "Cắt cuối (s)"):
                    lbl.setFixedWidth(80)
                else: # Xem trước
                    lbl.setFixedWidth(50)
