            raw_opts = list(getattr(scene, "video_options", []))
            if not raw_opts and scene.video_path:
                raw_opts = [scene.video_path]

            # Dedup by resolved path (video_path thường trùng option[0])
            seen_paths = set()
            valid_opts = []
            for o in raw_opts:
                if not o or not Path(o).exists():
                    continue
                rp = str(Path(o).resolve())
                if rp in seen_paths:
                    continue
                seen_paths.add(rp)
                valid_opts.append(o)

            # Fallback nếu toàn bộ options không tồn tại
            if not valid_opts and scene.video_path and Path(scene.video_path).exists():
                rp = str(Path(scene.video_path).resolve())
                if rp not in seen_paths:
                    valid_opts = [scene.video_path]

            if not valid_opts:
                continue

            for c_idx, opt_path in enumerate(valid_opts):
                row = self._create_scene_row(scene, opt_path, c_idx + 1)
                self.scene_rows.append(row)
                self.scene_lay.addWidget(row["widget"])


