    def _refresh_bg_music_combo(self):
        """Backward-compat stub — không dùng nữa trong dialog mới."""
        pass

    def _add_bg_music_auto(self):
        file_paths, _ = QFileDialog.getOpenFileNames(
            self, "Chọn file nhạc nền", "", "Audio Files (*.mp3 *.wav *.m4a *.aac *.ogg)"
        )
        bg_dir = APP_DIR / "Nhạc nền"
        bg_dir.mkdir(parents=True, exist_ok=True)
        for file_path in file_paths:
            p = Path(file_path)
            dest = bg_dir / p.name
            try: shutil.copy2(file_path, dest)
            except Exception: dest = p
            if str(dest) not in self._playlist_paths:
                self._playlist_paths.append(str(dest))
                self.list_bg_music.addItem(f"🎵 {dest.name}")

    def _select_voiceover(self):
        file_path, _ = QFileDialog.getOpenFileName(
            self, "Chọn file lồng tiếng", "", "Audio Files (*.mp3 *.wav *.m4a *.aac *.ogg)"
        )
        if file_path:
            self.selected_voiceover_path = file_path
            self.lbl_voiceover.setText(Path(file_path).name)
            self.radio_voice_custom.setChecked(True)
            self.btn_voice_pick.setEnabled(True)

    def _save(self):
        btn_id = self._voice_btn_group.checkedId()
        if btn_id == 0:   # random from SP voices
            voice_mode = "random"
            vpath = "random" if self._product_voices else None
        elif btn_id == 1: # custom file
            voice_mode = "custom"
            vpath = self.selected_voiceover_path
        else:             # none
            voice_mode = "none"
            vpath = None

        self.result_settings = {
            "transition": self.combo_transition.currentText(),
            "num_outputs": int(self.combo_num_outputs.currentText()),
            "no_duplicate": self.chk_no_duplicate.isChecked(),
            "delete_source": self.chk_delete_source.isChecked(),
            "reverse_scenes": self.chk_reverse_scenes.isChecked(),
            "bg_music_playlist": list(self._playlist_paths),
            "bg_music_random": self.chk_bg_random.isChecked(),
            "bg_music_path": self._playlist_paths[0] if self._playlist_paths else None,
            "voice_mode": voice_mode,
            "voiceover_path": vpath,
            "voice_speed_adjust": self.chk_voice_speed.isChecked(),
            "bg_music_vol": float(self.spin_bg_vol.value()) / 100.0,
            "voiceover_vol": float(self.spin_voice_vol.value()) / 100.0,
            "orig_video_vol": float(self.spin_orig_vol.value()) / 100.0,
        }
        self.accept()


