    def login_worker_find_browser_path(self) -> tuple:
        chrome_paths = [
            Path(os.environ.get("ProgramFiles", "C:\\Program Files")) / "Google\\Chrome\\Application\\chrome.exe",
            Path(os.environ.get("ProgramFiles(x86)", "C:\\Program Files (x86)")) / "Google\\Chrome\\Application\\chrome.exe",
            Path(os.environ.get("LocalAppData", "C:\\Users\\ADMIN\\AppData\\Local")) / "Google\\Chrome\\Application\\chrome.exe",
        ]
        for p in chrome_paths:
            if p.exists():
                return "chrome", str(p)
        return None, None

    def reject(self):
        if hasattr(self, "login_worker") and self.login_worker and self.login_worker.isRunning():
            try:
                self.login_worker.stop()
                self.login_worker.wait()
            except Exception:
                pass
        super().reject()

    def import_from_veo3_generator_pro(self):
        """Nhập danh sách tài khoản Google Flow từ cơ sở dữ liệu VEO3_Generator_Pro."""
        appdata = os.environ.get("APPDATA", "")
        db_path = os.path.join(appdata, "VEO3_Generator_Pro", "data", "veoflow.db")
        if not os.path.exists(db_path):
            QMessageBox.warning(self, "Thất bại", f"Không tìm thấy dữ liệu của VEO3 Generator Pro tại:\n{db_path}")
            return
        
        try:
            import sqlite3
            conn = sqlite3.connect(db_path)
            c = conn.cursor()
            c.execute("SELECT email, access_token, project_id, enabled FROM accounts")
            rows = c.fetchall()
            conn.close()
            
            added_count = 0
            for email, token, proj_id, enabled in rows:
                if token and proj_id:
                    acc_name = f"Google_{email}"
                    exists = False
                    for a in self.acc_mgr.accounts:
                        if a.name == acc_name:
                            a.api_key = token
                            a.auth_revision = time.time_ns()
                            a.auth_state = 'ready'
                            a.proxy_url = proj_id
                            a.active = bool(enabled)
                            exists = True
                            break
                    if not exists:
                        self.acc_mgr.accounts.append(Account(
                            name=acc_name,
                            proxy_url=proj_id,
                            api_key=token,
                            active=bool(enabled)
                        ))
                    added_count += 1
            
            self.acc_mgr.save()
            self.reload_accounts()
            QMessageBox.information(self, "Thành công", f"Đã nhập thành công {added_count} tài khoản Google Flow từ VEO3 Generator Pro!")
        except Exception as e:
            QMessageBox.critical(self, "Lỗi", f"Không thể đọc cơ sở dữ liệu: {e}")

    def reload_accounts(self):
        self.acc_mgr.load()
        self.draw_accounts_list()
        self.on_change_callback()

    def sync_accounts(self):
        added, removed = self.acc_mgr.sync_from_cliproxy()
        self.reload_accounts()
        QMessageBox.information(
            self, 
            "Đồng Bộ Thành Công", 
            f"Đã đồng bộ xong danh sách tài khoản từ CLIproxy!\n\n"
            f"➕ Thêm mới: {added} tài khoản\n"
            f"🗑️ Đã xóa (hết hạn/đã xóa trên admin): {removed} tài khoản"
        )

    def draw_accounts_list(self):
        # Clear scroll area
        for i in reversed(range(self.scroll_lay.count())):
            self.scroll_lay.itemAt(i).widget().setParent(None)

        if not self.acc_mgr.accounts:
            lbl = QLabel("Chưa có tài khoản nào.", styleSheet="color: #94a3b8; font-style: italic; text-align: center;")
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.scroll_lay.addWidget(lbl)
            return

        for idx, acc in enumerate(self.acc_mgr.accounts):
            row = QFrame()
            row.setObjectName("account_row")
            row.setStyleSheet("QFrame#account_row { background-color: #f1f5f9; border-radius: 6px; padding: 4px; }")
            r_lay = QHBoxLayout(row)
            r_lay.setContentsMargins(8, 4, 8, 4)

            name_l = QLabel(f"👥  {acc.name}", styleSheet="font-weight: bold;")
            r_lay.addWidget(name_l, stretch=1)

            # Checkbox status
            cb = QCheckBox("Bật" if acc.active else "Tắt")
            cb.setChecked(acc.active)
            def make_toggle(i=idx, c=cb):
                def handler():
                    self.acc_mgr.toggle(i)
                    c.setText("Bật" if self.acc_mgr.accounts[i].active else "Tắt")
                    self.on_change_callback()
                return handler
            cb.stateChanged.connect(make_toggle(idx, cb))
            r_lay.addWidget(cb)

            # Delete button
            del_b = QPushButton("🗑️")
            del_b.setStyleSheet("background-color: #ef4444; color: white; padding: 4px 8px; border-radius: 4px;")
            def make_delete(i=idx):
                def handler():
                    if QMessageBox.question(self, "Xác nhận", f"Xóa tài khoản '{self.acc_mgr.accounts[i].name}'?") == QMessageBox.StandardButton.Yes:
                        removed_account = self.acc_mgr.accounts[i]
                        acc_name = removed_account.name
                        self.acc_mgr.remove(i)
                        self.reload_accounts()
                        
                        # Clean browser profiles/cookies cache
                        try:
                            import shutil
                            profile_name = _google_profile_name_for_account(removed_account)
                            if not profile_name:
                                return
                            
                            shared_dir = _resolve_flow_shared_dir(profile_name)
                            p_dir = shared_dir / "profiles" / profile_name
                            if p_dir.exists():
                                shutil.rmtree(p_dir, ignore_errors=True)
                                
                            c_file = shared_dir / "cookies" / f"{profile_name}.json"
                            if c_file.exists():
                                c_file.unlink(missing_ok=True)
                                
                            bp_dir = Path(__file__).parent / "browser_profiles" / profile_name
                            if bp_dir.exists():
                                shutil.rmtree(bp_dir, ignore_errors=True)
                                
                            self._sb_log(f"🧹 Đã dọn dẹp thư mục trình duyệt và cookies của: {profile_name}")
                        except Exception as e:
                            print(f"Error cleaning profile: {e}")
                return handler
            del_b.clicked.connect(make_delete(idx))
            r_lay.addWidget(del_b)

            self.scroll_lay.addWidget(row)
        self.scroll_lay.addStretch()

    def add_manual_acc(self):
        name = self.ne.text().strip()
        url = self.ue.text().strip() or DEFAULT_PROXY_URL
        key = self.ke.text().strip() or "grok-video-key-001"
        if not name:
            return QMessageBox.warning(self, "Cảnh báo", "Vui lòng nhập tên tài khoản!")
        self.acc_mgr.add(name, url, key)
        self.ne.clear()
        self.ue.clear()
        self.ke.clear()
        self.reload_accounts()

    def kill_port_56121(self) -> bool:
        try:
            res = subprocess.run(["netstat", "-ano"], capture_output=True, encoding="utf-8", creationflags=subprocess.CREATE_NO_WINDOW)
            for line in res.stdout.splitlines():
                if ":56121" in line and "LISTENING" in line:
                    parts = line.strip().split()
                    if len(parts) >= 5:
                        pid = parts[-1]
                        subprocess.run(["taskkill", "/F", "/PID", pid], capture_output=True, creationflags=subprocess.CREATE_NO_WINDOW)
                        return True
        except Exception:
            pass
        return False

    def start_oauth_login(self):
        items = ["xAI Grok (SuperGrok)", "OpenAI Codex (ChatGPT Plus)", "Google Flow / Veo 3"]
        item, ok = QInputDialog.getItem(self, "Đăng Nhập Tài Khoản", "Chọn loại tài khoản đăng nhập:", items, 0, False)
        if not ok or not item:
            return
            
        login_type = item

        if "Google Flow" in login_type:
            prof_name, ok2 = QInputDialog.getText(self, "Đăng Nhập Google", "Nhập tên cấu hình trình duyệt (Viết liền không dấu):")
            if not ok2 or not prof_name.strip():
                return
            prof_name = prof_name.strip()
            
            # Reuse the existing shared profile/cookies.  Login is also the
            # recovery path for an expired token, so deleting the profile here
            # would unnecessarily sign the account out on every refresh.
            resolved_profile = _resolve_google_profile_name(prof_name) or prof_name
            if resolved_profile != prof_name:
                self._sb_log(f"♻️ Dùng lại profile Google đã lưu: {resolved_profile}")
            prof_name = resolved_profile
            
            self.login_status.setText("🔍 Đang khởi chạy trình duyệt Google...")
            self.login_status.setStyleSheet("color: #7c3aed; font-weight: bold;")
            
            self.google_login_worker = GoogleLoginWorker(profile_name=prof_name)
            self.google_login_worker.status_sig.connect(self.on_login_status)
            
            def on_google_success(email, token, proj_id):
                saved_profile = (
                    getattr(self.google_login_worker, "profile_name", "")
                    or _resolve_google_profile_name(email)
                    or prof_name
                )
                acc_name = f"Google_{email}"
                exists = False
                for a in self.acc_mgr.accounts:
                    if a.name == acc_name:
                        a.api_key = token
                        a.auth_revision = time.time_ns()
                        a.auth_state = 'ready'
                        a.proxy_url = proj_id
                        a.profile_name = saved_profile
                        a.active = True
                        exists = True
                        break
                if not exists:
                    self.acc_mgr.accounts.append(Account(
                        name=acc_name,
                        proxy_url=proj_id,
                        api_key=token,
                        profile_name=saved_profile,
                        active=True
                    ))
                self.acc_mgr.save()
                
                # Persist the registry next to the profile actually used for
                # login.  Do not create an unrelated legacy registry root.
                _upsert_flow_profile_registry(
                    email, saved_profile, proj_id, mark_login=True
                )
                
                self.reload_accounts()
                self.login_status.setText(f"✅ Đăng nhập thành công Google: {email}!")
                self.login_status.setStyleSheet("color: #16a34a; font-weight: bold;")
                
            def on_google_error(err_msg):
                self.login_status.setText(f"❌ Lỗi: {err_msg}")
                self.login_status.setStyleSheet("color: #ef4444; font-weight: bold;")
                
            self.google_login_worker.success_sig.connect(on_google_success)
            self.google_login_worker.error_sig.connect(on_google_error)
            self.google_login_worker.start()
            return

        if "Grok" in login_type:
            # Luồng đăng nhập hàng loạt cho Grok
            dlg = GrokMultiLoginInputDialog(self)
            if dlg.exec() != QDialog.DialogCode.Accepted:
                return
            accounts = dlg.get_accounts()
            if not accounts:
                QMessageBox.warning(self, "Cảnh báo", "Không tìm thấy danh sách tài khoản hợp lệ (email|password)!")
                return
                
            # Tìm trình duyệt Chrome trên máy
            b_type, b_path = self.login_worker_find_browser_path()
            if not b_path:
                QMessageBox.critical(self, "Lỗi", "Không tìm thấy trình duyệt Google Chrome cài đặt trên hệ thống!")
                return
                
            self.login_status.setText("🔍 Đang khởi động tiến trình đăng nhập hàng loạt Grok...")
            self.login_status.setStyleSheet("color: #7c3aed; font-weight: bold;")
            
            self.login_worker = GrokMultiLoginWorker(accounts, b_path)
            self.login_worker.status_sig.connect(self.on_login_status)
            self.login_worker.account_success_sig.connect(self.on_login_success)
            
            def on_grok_batch_finished(success_count, total_count):
                self.login_status.setText(f"✅ Hoàn thành: đăng nhập thành công {success_count}/{total_count} tài khoản!")
                self.login_status.setStyleSheet("color: #16a34a; font-weight: bold;")
                self.reload_accounts()
                
            self.login_worker.finished_sig.connect(on_grok_batch_finished)
            self.login_worker.start()
            return

        if not CLIPROXY_EXE.exists():
            return QMessageBox.critical(self, "Lỗi", f"Không tìm thấy file CLIProxy tại:\n{CLIPROXY_EXE}")

        self.login_status.setText("🔍 Đang chuẩn bị cổng kết nối...")
        
        self.login_worker = LoginWorker(login_type=login_type)
        self.login_worker.status_sig.connect(self.on_login_status)
        self.login_worker.success_sig.connect(self.on_login_success)
        self.login_worker.start()

    def on_login_status(self, text, color):
        self.login_status.setText(text)
        self.login_status.setStyleSheet(f"color: {color}; font-weight: bold;")

    def on_login_success(self, info):
        if "|" in info:
            login_type, email = info.split("|", 1)
        else:
            login_type = "xAI Grok"
            email = info
            
        acc_prefix = "Codex" if "Codex" in login_type else "Grok"
        acc_name = f"{acc_prefix} - {email}"
        existing = [a.name for a in self.acc_mgr.accounts]
        if acc_name not in existing:
            self.acc_mgr.add(acc_name, DEFAULT_PROXY_URL, "grok-video-key-001")
        self.reload_accounts()


