class ImagePreviewDialog(QDialog):
    def __init__(self, parent, job: VideoJob, on_image_modified_cb):
        super().__init__(parent)
        self.setWindowTitle(f"🖼️ Xem Ảnh & Prompt — #{job.id}")
        self.resize(750, 600)
        self.job = job
        self.on_image_modified_cb = on_image_modified_cb
        self.current_index = 0
        
        # Build image list
        self.images = []
        is_completed_image = (job.status == "done" and "image" in job.model and job.local_path)
        if is_completed_image:
            self.images.append(job.local_path)
        else:
            if job.image_url:
                self.images.append(job.image_url)
            for u in job.reference_image_urls:
                if u not in self.images:
                    self.images.append(u)
                
        # Main layout
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)
        
        # Image Display box
        self.img_label = QLabel(self)
        self.img_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.img_label.setStyleSheet("background-color: #1e293b; border-radius: 8px; border: 1px solid #cbd5e1;")
        layout.addWidget(self.img_label, stretch=1)
        
        # Navigation row (Arrows and Counter)
        nav_widget = QWidget()
        nav_lay = QHBoxLayout(nav_widget)
        nav_lay.setContentsMargins(0, 0, 0, 0)
        
        self.prev_btn = QPushButton("◀ Trước")
        self.prev_btn.setObjectName("normal_btn")
        self.prev_btn.clicked.connect(self.prev_image)
        nav_lay.addWidget(self.prev_btn)
        
        self.counter_label = QLabel("0 / 0")
        self.counter_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.counter_label.setStyleSheet("font-weight: bold; font-size: 13px;")
        nav_lay.addWidget(self.counter_label)
        
        self.next_btn = QPushButton("Sau ▶")
        self.next_btn.setObjectName("normal_btn")
        self.next_btn.clicked.connect(self.next_image)
        nav_lay.addWidget(self.next_btn)
        
        if is_completed_image:
            nav_widget.setVisible(False)
        layout.addWidget(nav_widget)
        
        # Image Control buttons row
        control_widget = QWidget()
        control_lay = QHBoxLayout(control_widget)
        control_lay.setContentsMargins(0, 0, 0, 0)
        
        self.change_btn = QPushButton("📷 Thay ảnh này")
        self.change_btn.setObjectName("normal_btn")
        self.change_btn.clicked.connect(self.change_current_image)
        control_lay.addWidget(self.change_btn)
        
        self.add_btn = QPushButton("➕ Thêm ảnh mới")
        self.add_btn.setObjectName("normal_btn")
        self.add_btn.clicked.connect(self.add_new_image)
        control_lay.addWidget(self.add_btn)
        
        self.delete_btn = QPushButton("🗑️ Xóa ảnh này")
        self.delete_btn.setObjectName("normal_btn")
        self.delete_btn.setStyleSheet("QPushButton:hover { background-color: #ef4444; color: white; }")
        self.delete_btn.clicked.connect(self.delete_current_image)
        control_lay.addWidget(self.delete_btn)
        
        if is_completed_image:
            control_widget.setVisible(False)
        layout.addWidget(control_widget)
        
        # Prompt box
        prompt_box = QFrame()
        prompt_box.setFrameShape(QFrame.Shape.StyledPanel)
        prompt_box.setStyleSheet("background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px;")
        p_lay = QVBoxLayout(prompt_box)
        p_lay.setContentsMargins(8, 8, 8, 8)
        p_lay.setSpacing(6)
        
        lbl_p_row = QWidget()
        lpr_lay = QHBoxLayout(lbl_p_row)
        lpr_lay.setContentsMargins(0, 0, 0, 0)
        
        title_p = QLabel("✍️ Prompt (Có thể chỉnh sửa):" if job.status != "done" else "✍️ Prompt:")
        title_p.setStyleSheet("font-weight: bold; color: #7c3aed; font-size: 11px;")
        lpr_lay.addWidget(title_p)
        
        save_p_btn = QPushButton("💾 Lưu Prompt")
        save_p_btn.setObjectName("normal_btn")
        save_p_btn.setStyleSheet("padding: 2px 6px; font-size: 10px; font-weight: bold;")
        save_p_btn.clicked.connect(self.save_prompt_changes)
        
        if job.status == "done":
            save_p_btn.setVisible(False)
            
        lpr_lay.addWidget(save_p_btn, alignment=Qt.AlignmentFlag.AlignRight)
        p_lay.addWidget(lbl_p_row)
        
        self.prompt_edit = QTextEdit()
        self.prompt_edit.setText(job.prompt)
        self.prompt_edit.setPlaceholderText("Nhập prompt mô tả...")
        self.prompt_edit.setStyleSheet("font-size: 12px; color: #1e293b; background-color: #ffffff; border: 1px solid #cbd5e1; border-radius: 4px;")
        self.prompt_edit.setFixedHeight(70)
        
        if job.status == "done":
            self.prompt_edit.setReadOnly(True)
            
        p_lay.addWidget(self.prompt_edit)
        
        layout.addWidget(prompt_box)
        
        self.show_current_image()

    def show_current_image(self):
        if not self.images:
            self.img_label.setText("Chưa có ảnh nào được gán.")
            self.counter_label.setText("0 / 0")
            self.prev_btn.setEnabled(False)
            self.next_btn.setEnabled(False)
            self.change_btn.setEnabled(False)
            self.delete_btn.setEnabled(False)
            return
            
        self.prev_btn.setEnabled(len(self.images) > 1)
        self.next_btn.setEnabled(len(self.images) > 1)
        self.change_btn.setEnabled(True)
        self.delete_btn.setEnabled(True)
        
        img_path = self.images[self.current_index]
        self.counter_label.setText(f"{self.current_index + 1} / {len(self.images)}")
        
        if Path(img_path).exists():
            pix = QPixmap(img_path)
            scaled_pix = pix.scaled(700, 400, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
            self.img_label.setPixmap(scaled_pix)
        else:
            self.img_label.setText(f"Lỗi: Không tìm thấy ảnh tại\n{img_path}")

    def prev_image(self):
        if self.images:
            self.current_index = (self.current_index - 1) % len(self.images)
            self.show_current_image()

    def next_image(self):
        if self.images:
            self.current_index = (self.current_index + 1) % len(self.images)
            self.show_current_image()

    def change_current_image(self):
        p, _ = QFileDialog.getOpenFileName(self, "Chọn ảnh mới", "", "Images (*.jpg *.jpeg *.png *.webp)")
        if p:
            self.images[self.current_index] = p
            self.sync_images_to_job()
            self.show_current_image()
            self.on_image_modified_cb()

    def add_new_image(self):
        p, _ = QFileDialog.getOpenFileName(self, "Thêm ảnh mới", "", "Images (*.jpg *.jpeg *.png *.webp)")
        if p:
            self.images.append(p)
            self.current_index = len(self.images) - 1
            self.sync_images_to_job()
            self.show_current_image()
            self.on_image_modified_cb()

    def save_prompt_changes(self):
        new_prompt = self.prompt_edit.toPlainText().strip()
        if new_prompt:
            self.job.prompt = new_prompt
            self.on_image_modified_cb()
            QMessageBox.information(self, "Thành công", "Đã lưu thay đổi prompt!")

    def delete_current_image(self):
        if not self.images:
            return
            
        self.images.pop(self.current_index)
        if self.current_index >= len(self.images):
            self.current_index = max(0, len(self.images) - 1)
            
        self.sync_images_to_job()
        self.show_current_image()
        self.on_image_modified_cb()
        
        if not self.images:
            self.close()

    def sync_images_to_job(self):
        if not self.images:
            self.job.image_url = None
            self.job.reference_image_urls = []
        else:
            if len(self.images) > 1 or self.job.mode == "reference-to-video":
                self.job.mode = "reference-to-video"
                self.job.image_url = None
                self.job.reference_image_urls = self.images.copy()
            else:
                if self.job.mode == "text-to-video":
                    self.job.mode = "image-to-video"
                self.job.image_url = self.images[0]
                self.job.reference_image_urls = []


