    def _on_folder_changed(self):
        self._filter_products()

    def _toggle_favorite(self, prod):
        prod["favorite"] = not prod.get("favorite", False)
        selected_pid = None
        selected_row = self.table.currentRow()
        if selected_row >= 0:
            selected_pid = self.table.item(selected_row, 0).text()
            
        prod_json = APP_DIR / "TiktokShop" / "crawled_products" / "products.json"
        try:
            prod_json.write_text(json.dumps(self.products, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            print(f"Lỗi lưu trạng thái yêu thích: {e}")
            
        self.load_crawled_products()
        
        if selected_pid:
            for r in range(self.table.rowCount()):
                if self.table.item(r, 0).text() == selected_pid:
                    self.table.setCurrentCell(r, 0)
                    break

    def load_crawled_products(self):
        self.products = []
        prod_json = APP_DIR / "TiktokShop" / "crawled_products" / "products.json"
        if prod_json.exists():
            try:
                self.products = json.loads(prod_json.read_text(encoding="utf-8"))
            except Exception:
                self.products = []
                
        curr_folder_item = self.folder_list.currentItem()
        curr_folder_text = curr_folder_item.text() if curr_folder_item else "📁 Tất cả thư mục"
        
        from PyQt6.QtWidgets import QListWidgetItem
        self.folder_list.clear()
        self.folder_list.addItem("📁 Tất cả thư mục")
        self.folder_list.addItem("📁 Chưa phân loại")
        self.folder_list.addItem("❤️ Yêu thích")
        self.folder_list.addItem("🕒 Gần đây")
        
        custom_folders = set()
        for p in self.products:
            f = p.get("folder", "Chưa phân loại")
            if f and f != "Chưa phân loại":
                custom_folders.add(f)
                
        for f in sorted(list(custom_folders)):
            self.folder_list.addItem(f"📁 {f}")
            
        found_item = None
        for i in range(self.folder_list.count()):
            item = self.folder_list.item(i)
            if item.text() == curr_folder_text:
                found_item = item
                break
        if found_item:
            self.folder_list.setCurrentItem(found_item)
        else:
            self.folder_list.setCurrentRow(0)
            
        self._filter_products()

    def _populate_table(self):
        self.load_crawled_products()

    def _filter_products(self, query=None):
        txt = self.edit_search.text().strip().lower()
        self.table.setRowCount(0)
        
        curr_folder_item = self.folder_list.currentItem()
        selected_folder = curr_folder_item.text() if curr_folder_item else "📁 Tất cả thư mục"
        
        folder_filtered = []
        if selected_folder == "📁 Tất cả thư mục":
            folder_filtered = list(self.products)
        elif selected_folder == "📁 Chưa phân loại":
            folder_filtered = [p for p in self.products if p.get("folder", "Chưa phân loại") == "Chưa phân loại"]
        elif selected_folder == "❤️ Yêu thích":
            folder_filtered = [p for p in self.products if p.get("favorite", False)]
        elif selected_folder == "🕒 Gần đây":
            recent_prods = [p for p in self.products if p.get("last_used", 0) > 0]
            recent_prods.sort(key=lambda x: x.get("last_used", 0), reverse=True)
            folder_filtered = recent_prods[:20]
        else:
            f_name = selected_folder.replace("📁 ", "").strip()
            folder_filtered = [p for p in self.products if p.get("folder", "Chưa phân loại") == f_name]
            
        filtered = []
        for p in folder_filtered:
            pid = p.get("product_id", "")
            title = p.get("title", "")
            if not txt or txt in pid.lower() or txt in title.lower():
                filtered.append(p)
                
        self.table.setRowCount(len(filtered))
        for r, p in enumerate(filtered):
            self.table.setItem(r, 0, QTableWidgetItem(p.get("product_id", "")))
            self.table.setItem(r, 1, QTableWidgetItem(p.get("title", "")))
            self.table.setItem(r, 2, QTableWidgetItem(p.get("price", "")))
            
            is_fav = p.get("favorite", False)
            fav_btn = QPushButton("❤️" if is_fav else "🖤")
            fav_btn.setStyleSheet("background: transparent; border: none; font-size: 14px; cursor: pointer;")
            fav_btn.setToolTip("Click để yêu thích / bỏ yêu thích")
            fav_btn.clicked.connect(lambda _, _p=p: self._toggle_favorite(_p))
            self.table.setCellWidget(r, 3, fav_btn)
            
            voices = p.get("voices", [])
            voice_status = f"Có ({len(voices)} tệp)" if voices else "Chưa có"
            voice_item = QTableWidgetItem(voice_status)
            if voices:
                voice_item.setForeground(QColor("#38bdf8"))
            else:
                voice_item.setForeground(QColor("#94a3b8"))
            self.table.setItem(r, 4, voice_item)

    def _show_context_menu(self, position):
        row = self.table.rowAt(position.y())
        if row < 0:
            return
            
        pid = self.table.item(row, 0).text()
        prod = next((p for p in self.products if p.get("product_id") == pid), None)
        if not prod:
            return

        menu = QMenu(self.table)
        open_folder_act = menu.addAction("📁 Mở folder chứa dữ liệu sản phẩm")
        
        action = menu.exec(self.table.mapToGlobal(position))
        if action == open_folder_act:
            local_imgs = prod.get("local_images", [])
            if local_imgs:
                p = Path(local_imgs[0])
                if not p.exists():
                    p = APP_DIR / "TiktokShop" / "crawled_products" / p.parts[-2] / p.parts[-1]
                
                folder = p.parent
                if folder.exists():
                    import os
                    os.startfile(folder)
                else:
                    QMessageBox.warning(self, "Lỗi", "Không tìm thấy thư mục sản phẩm!")
            else:
                QMessageBox.warning(self, "Lỗi", "Sản phẩm này chưa có ảnh/dữ liệu lưu cục bộ!")

    def _on_product_selected(self):
        row = self.table.currentRow()
        if row < 0:
            self.edit_manual_video_url.setEnabled(False)
            self.btn_download_manual_video.setEnabled(False)
            self.edit_manual_video_url.clear()
            return
            
        pid = self.table.item(row, 0).text()
        prod = next((p for p in self.products if p.get("product_id") == pid), None)
        if not prod:
            self.edit_manual_video_url.setEnabled(False)
            self.btn_download_manual_video.setEnabled(False)
            self.edit_manual_video_url.clear()
            return
            
        self.edit_manual_video_url.setEnabled(True)
        self.btn_download_manual_video.setEnabled(True)
        
        self.lbl_title.setText(prod.get("title", ""))
        seller = prod.get("seller", "")
        price = prod.get("price", "")
        status = prod.get("status", "")
        url = prod.get("url", "")
        images_count = prod.get("images_count", 0)
        description = prod.get("description", "")
        info_text = []
        if seller:
            info_text.append(f"🏪 Shop: {seller}")
        if price:
            info_text.append(f"💰 Gia: {price}")
        if status:
            info_text.append(f"✅ Trang thai: {status}")
        if images_count:
            info_text.append(f"🖼 Hinh anh: {images_count} anh")
        if url:
            info_text.append(f"🔗 Link: {url}")
        if description:
            info_text.append("")
            info_text.append("📝 Mo ta san pham:")
            info_text.append(description[:800])
        self.txt_desc.setPlainText("\n".join(info_text))
        
        voices_list = prod.get("voices", [])
        self.lbl_voice_info.setText(f"🗣️ Lồng tiếng: {len(voices_list)} file voice")
        
        for i in reversed(range(self.img_lay.count())):
            item = self.img_lay.itemAt(i)
            if item and item.widget():
                item.widget().deleteLater()
                
        self.current_product_images = []
        local_imgs = prod.get("local_images", [])
        
        for img in local_imgs:
            p = Path(img)
            if not p.exists():
                p = APP_DIR / "TiktokShop" / "crawled_products" / p.parts[-2] / p.parts[-1]
            if p.exists():
                self.current_product_images.append(str(p))
                
        self.selected_image_path = None
        self.lbl_selected_img.setText("Chưa chọn ảnh sản phẩm")
        self.btn_confirm.setEnabled(False)
        
        if self.current_product_images:
            self.btn_collage.setEnabled(True)
            for idx, img_path in enumerate(self.current_product_images):
                lbl = ClickableImageLabel(img_path)
                lbl.clicked.connect(self._select_image)
                self.img_lay.addWidget(lbl)
        else:
            self.btn_collage.setEnabled(False)
            self.btn_crop.setEnabled(False)

    def _select_image(self, path):
        self.selected_image_path = path
        self.lbl_selected_img.setText(f"✅ Đã chọn: {Path(path).name}")
        self.btn_crop.setEnabled(True)
        self.btn_confirm.setEnabled(True)
        
        for i in range(self.img_lay.count()):
            w = self.img_lay.itemAt(i).widget()
            if isinstance(w, ClickableImageLabel):
                w.set_selected(w.img_path == path)

    def _get_current_product_images_dir(self):
        row = self.table.currentRow()
        if row < 0:
            return None
        pid = self.table.item(row, 0).text()
        prod = next((p for p in self.products if p.get("product_id") == pid), None)
        if not prod or not prod.get("local_images"):
            return None
            
        first_img = Path(prod["local_images"][0])
        if not first_img.exists():
            first_img = APP_DIR / "TiktokShop" / "crawled_products" / first_img.parts[-2] / first_img.parts[-1]
            
        if first_img.exists():
            return first_img.parent
        return None

    def save_new_image_to_product(self, product_id, new_image_path):
        prod_json = APP_DIR / "TiktokShop" / "crawled_products" / "products.json"
        if not prod_json.exists():
            return
        try:
            products = json.loads(prod_json.read_text(encoding="utf-8"))
            for prod in products:
                if prod.get("product_id") == product_id:
                    local_imgs = prod.get("local_images", [])
                    try:
                        rel_path = str(Path(new_image_path).relative_to(APP_DIR / "TiktokShop" / "crawled_products"))
                    except Exception:
                        rel_path = new_image_path
                    if rel_path not in local_imgs:
                        local_imgs.append(rel_path)
                        prod["local_images"] = local_imgs
                        prod["images_count"] = len(local_imgs)
            prod_json.write_text(json.dumps(products, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception as e:
            print(f"Error saving to products.json: {e}")

    def _crop_selected(self):
        if not self.selected_image_path or not Path(self.selected_image_path).exists():
            return
        out_dir = self._get_current_product_images_dir()
        dialog = CropperDialog(self.selected_image_path, out_dir, self)
        if dialog.exec() == QDialog.DialogCode.Accepted and dialog.cropped_path:
            row = self.table.currentRow()
            if row >= 0:
                pid = self.table.item(row, 0).text()
                self.save_new_image_to_product(pid, dialog.cropped_path)
            self._select_image(dialog.cropped_path)

    def _collage_selected(self):
        if not self.current_product_images:
            return
        out_dir = self._get_current_product_images_dir()
        dialog = CollageDialog(self.current_product_images, out_dir, self)
        if dialog.exec() == QDialog.DialogCode.Accepted and dialog.collage_path:
            row = self.table.currentRow()
            if row >= 0:
                pid = self.table.item(row, 0).text()
                self.save_new_image_to_product(pid, dialog.collage_path)
            self.current_product_images.append(dialog.collage_path)
            
            lbl = ClickableImageLabel(dialog.collage_path)
            lbl.clicked.connect(self._select_image)
            self.img_lay.addWidget(lbl)
            self._select_image(dialog.collage_path)

    def _confirm_selection(self):
        row = self.table.currentRow()
        if row < 0 or not self.selected_image_path:
            return
            
        pid = self.table.item(row, 0).text()
        prod = next((p for p in self.products if p.get("product_id") == pid), None)
        if prod:
            prod["last_used"] = time.time()
            prod_json = APP_DIR / "TiktokShop" / "crawled_products" / "products.json"
            try:
                prod_json.write_text(json.dumps(self.products, ensure_ascii=False, indent=2), encoding="utf-8")
            except:
                pass
            self.selected_title = prod.get("title", "")
            self.selected_description = prod.get("description", "")
            self.selected_voices = prod.get("voices", [])
            self.accept()

    def _write_crawl_log(self, text):
        self.logs_box.append(text)
        self.logs_box.ensureCursorVisible()

    def _import_crawl_file(self):
        file_path, _ = QFileDialog.getOpenFileName(
            self, "Chọn file chứa Links", "",
            "Supported Files (*.txt *.csv *.xlsx *.xls);;Text Files (*.txt);;CSV Files (*.csv);;All Files (*)"
        )
        if file_path:
            self.lbl_file.setText(os.path.basename(file_path))
            try:
                import openpyxl
                urls = []
                ext = os.path.splitext(file_path)[1].lower()
                if ext in ['.xlsx', '.xls']:
                    self._write_crawl_log(f"📁 Đang đọc Excel: {file_path}...")
                    wb = openpyxl.load_workbook(file_path, data_only=True, read_only=True)
                    sheet = wb.active
                    
                    header_row = next(sheet.iter_rows(min_row=1, max_row=1, values_only=True), None)
                    link_col_idx = -1
                    video_col_idx = -1
                    if header_row:
                        for idx, val in enumerate(header_row):
                            if val:
                                val_lower = str(val).lower()
                                if any(k in val_lower for k in ['liên kết sản phẩm', 'link', 'url', 'product']):
                                    link_col_idx = idx
                                if any(k in val_lower for k in ['video liên quan', 'video', 'clip']):
                                    video_col_idx = idx
                    
                    start_row = 2 if (link_col_idx >= 0 or video_col_idx >= 0) else 1
                    link_idx = link_col_idx if link_col_idx >= 0 else 12
                    video_idx = video_col_idx if video_col_idx >= 0 else 4
                    
                    for row in sheet.iter_rows(min_row=start_row, values_only=True):
                        prod_url = ""
                        video_urls = []
                        if row:
                            if link_idx < len(row) and row[link_idx]:
                                prod_url = str(row[link_idx]).strip()
                            if video_idx < len(row) and row[video_idx]:
                                v_raw = str(row[video_idx]).strip()
                                for item in re.split(r'[;\n\s,]+', v_raw):
                                    if item.strip().startswith("http"):
                                        video_urls.append(item.strip())
                                        
                        if prod_url.startswith("http"):
                            if video_urls:
                                urls.append(f"{prod_url} | {'; '.join(video_urls)}")
                            else:
                                urls.append(prod_url)
                elif ext == '.csv':
                    self._write_crawl_log(f"📁 Đang đọc CSV: {file_path}...")
                    import csv
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        reader = csv.reader(f)
                        for row in reader:
                            if row:
                                for col in row:
                                    val = col.strip()
                                    if val.startswith("http"):
                                        urls.append(val)
                                        break
                else:
                    self._write_crawl_log(f"📁 Đang đọc File Text: {file_path}...")
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        for line in f:
                            val = line.strip()
                            if val.startswith("http"):
                                urls.append(val)
                                
                if urls:
                    self.edit_urls.setPlainText("\n".join(urls))
                    self._write_crawl_log(f"✅ Đã tải thành công {len(urls)} links từ file.")
                else:
                    self._write_crawl_log("⚠️ Không tìm thấy link hợp lệ nào trong file.")
            except Exception as e:
                self._write_crawl_log(f"❌ Lỗi đọc file: {e}")

    def _start_crawl(self):
        urls_text = self.edit_urls.toPlainText().strip()
        if not urls_text:
            QMessageBox.warning(self, "Lỗi", "Vui lòng nhập danh sách links cần cào!")
            return
            
        urls = [u.strip() for u in urls_text.split("\n") if u.strip()]
        if not urls:
            return
            
        # Kiểm tra trạng thái Chrome Spy trước khi cào
        if not is_port_in_use(CDP_PORT) or not is_chrome_cdp_active(CDP_PORT):
            QMessageBox.critical(self, "Chưa bật Chrome Spy", "Vui lòng click nút 'Mở Chrome Spy' ở tab TiktokShop để chạy Chrome trước khi cào!")
            return
            
        self.btn_start_crawl.setEnabled(False)
        self.btn_stop_crawl.setEnabled(True)
        self.progress_bar.setMaximum(len(urls))
        self.progress_bar.setValue(0)
        self.logs_box.clear()
        
        # Cập nhật TikWM Key vào config của App
        tikwm_key = self.edit_tikwm_key.text().strip()
        if hasattr(self.app, "tikwm_api_key") and tikwm_key != self.app.tikwm_api_key:
            self.app.tikwm_api_key = tikwm_key
            self.app.save_veo_config()
            
        self.crawl_worker = CrawlWorker(urls, thread_count=self.spin_threads.value())
        self.crawl_worker.tikwm_api_key = tikwm_key
        self.crawl_worker.log_signal.connect(self._write_crawl_log)
        self.crawl_worker.progress_signal.connect(self._on_crawl_progress)
        self.crawl_worker.product_done_signal.connect(self._on_crawl_product_done)
        self.crawl_worker.finished_signal.connect(self._on_crawl_finished)
        self.crawl_worker.start()
        
    def _stop_crawl(self):
        if self.crawl_worker:
            self.crawl_worker.stop()
            self._write_crawl_log("🛑 Đang gửi yêu cầu dừng cào. Đang đợi luồng đóng...")
            self.btn_stop_crawl.setEnabled(False)
            
    def _on_crawl_progress(self, completed, total):
        self.progress_bar.setValue(completed)
        self.lbl_stats.setText(f"Đã cào: {completed}/{total}")
        
    def _on_crawl_product_done(self, product_data):
        self.load_crawled_products()
        self._populate_table()
        
        if product_data and product_data.get("status") != "Failed":
            pid = product_data.get("product_id")
            for row in range(self.table.rowCount()):
                if self.table.item(row, 0).text() == pid:
                    self.table.selectRow(row)
                    break
                    
    def _on_crawl_finished(self, success, failed):
        self.btn_start_crawl.setEnabled(True)
        self.btn_stop_crawl.setEnabled(False)
        self.lbl_stats.setText(f"Hoàn thành: Thành công {success} | Thất bại {failed}")
        
        self.tabs.setCurrentIndex(0)
        QMessageBox.information(self, "Hoàn tất", f"Đã cào xong {success} sản phẩm thành công!")

    def _download_manual_video_voice(self):
        row = self.table.currentRow()
        if row < 0:
            QMessageBox.warning(self, "Chưa chọn sản phẩm", "Vui lòng chọn sản phẩm trong danh sách trước!")
            return

        video_url = self.edit_manual_video_url.text().strip()
        if not video_url:
            QMessageBox.warning(self, "Trống", "Vui lòng nhập/dán liên kết video TikTok cần tải!")
            return

        pid = self.table.item(row, 0).text()
        prod = next((p for p in self.products if p.get("product_id") == pid), None)
        if not prod:
            return

        safe_title = clean_filename(prod.get("title", "product"))
        f_name = prod.get("folder", "Chưa phân loại")
        if f_name and f_name != "Chưa phân loại":
            prod_dir = DOWNLOADS_DIR / f_name / f"{pid}_{safe_title}"
        else:
            prod_dir = DOWNLOADS_DIR / f"{pid}_{safe_title}"
        prod_dir.mkdir(parents=True, exist_ok=True)
        voice_dir = prod_dir / "voices"
        voice_dir.mkdir(parents=True, exist_ok=True)

        self.btn_download_manual_video.setEnabled(False)
        self.btn_download_manual_video.setText("Đang tải...")
        self.edit_manual_video_url.setEnabled(False)

        # Read API key from App config
        tikwm_key = ""
        if hasattr(self.app, "veo_config") and isinstance(self.app.veo_config, dict):
            tikwm_key = self.app.veo_config.get("tikwm_api_key", "")

        # Spawn asynchronous worker thread
        self.voice_downloader = VoiceDownloadWorker(video_url, voice_dir, tikwm_key)
        self.voice_downloader.finished_signal.connect(lambda success, result: self._on_manual_download_finished(success, result, prod))
        self.voice_downloader.start()

    def _on_manual_download_finished(self, success, result, prod):
        self.btn_download_manual_video.setEnabled(True)
        self.btn_download_manual_video.setText("📥 Tải Voice")
        self.edit_manual_video_url.setEnabled(True)

        if success:
            mp3_path = result
            # Add to voices list of product
            voices = prod.get("voices", [])
            if mp3_path not in voices:
                voices.append(mp3_path)
                prod["voices"] = voices

                # Write to products.json
                prod_json = APP_DIR / "TiktokShop" / "crawled_products" / "products.json"
                try:
                    prod_json.write_text(json.dumps(self.products, indent=2, ensure_ascii=False), encoding="utf-8")
                except Exception as e:
                    print("Error saving products.json after manual voice download:", e)

            QMessageBox.information(self, "Thành công", f"Đã tải và trích xuất thành công voiceover: {Path(mp3_path).name}")

            # Reload and update UI
            self.load_crawled_products()
            self._populate_table()
            self.edit_manual_video_url.clear()
            self._on_product_selected()
        else:
            QMessageBox.critical(self, "Lỗi", f"Tải/Trích xuất voiceover thất bại:\n{result}")

