    def setup_autokhoploi_panel(self):
        """Setup panel cho Auto Khớp Lời (index 14).
        Kế thừa từ auto_lipsync_widget.build_auto_lipsync_panel()
        dùng batch_pipeline_engine đầy đủ.
        """
        self._akl_panel_widget = None
        try:
            from AutoKhopLoi.auto_lipsync_widget import build_auto_lipsync_panel

            # Tạo project proxy object phù hợp với auto_lipsync_widget
            proj = self._akl_make_project_proxy()
            # Wrap accounts: auto_lipsync_widget cần .email → map .name
            accounts = self._akl_wrap_accounts()

            panel = build_auto_lipsync_panel(proj, accounts, self, log_fn=self._akl_log)
            self._akl_panel_widget = panel
            self._akl_proxy_proj = proj
        except Exception as e:
            import traceback
            traceback.print_exc()
            panel = QWidget()
            lay = QVBoxLayout(panel)
            err_lbl = QLabel(
                f"⚠ Không thể load Auto Khớp Lời panel:\n{e}\n\n"
                f"Kiểm tra:\n"
                f"1. File AutoKhopLoi/auto_lipsync_widget.py tồn tại\n"
                f"2. batch_pipeline_engine.py có trong Auto_Veo_3_Pro/\n"
                f"3. Cài đặt: pip install playwright edge-tts"
            )
            err_lbl.setWordWrap(True)
            err_lbl.setStyleSheet("color: #dc2626; font-size: 12px; padding: 20px; font-family: Consolas;")
            lay.addWidget(err_lbl)
            print(f"[WARN] setup_autokhoploi_panel failed: {e}")
        self.stacked_widget.addWidget(panel)

