    # ── Proxy UI Callbacks ──

    def _proxy_log(self, msg):
        self.proxy_log_sig.emit(msg)

    def _safe_proxy_log(self, msg):
        ts = time.strftime("%H:%M:%S")
        if hasattr(self, "proxy_log_text"):
            self.proxy_log_text.append(f"[{ts}] {msg}")
            sb = self.proxy_log_text.verticalScrollBar()
            sb.setValue(sb.maximum())
        
        # Bridge important proxy logs to main active pipeline logs (if active)
        lower_msg = msg.lower()
        is_important = any(x in lower_msg for x in [
            "proxy", "xoay", "ip", "kết nối"
        ])
        if is_important:
            if getattr(self, "_sb_running", False):
                self._sb_log(f"⚡ {msg}")
            if getattr(self, "_rs_running", False):
                self._rs_log(f"⚡ {msg}")

    def _safe_proxy_ui_refresh(self):
        self._proxy_refresh_table()
        self._proxy_update_status()

    def _ensure_proxies_active(self):
        """Đảm bảo các proxy đang bật đã được xoay IP và sẵn sàng hoạt động."""
        if not self.proxy_mgr:
            return
            
        # 1. Nếu không có proxy nào được enable nhưng có proxy trong danh sách, tự động enable tất cả
        enabled = self.proxy_mgr.get_enabled_proxies()
        if not enabled and self.proxy_mgr.proxies:
            self.proxy_mgr.log("⚡ Không có proxy nào được chọn bật. Tự động bật tất cả proxy trong danh sách...")
            for p in self.proxy_mgr.proxies:
                p.enabled = True
            self.proxy_mgr.save()
            self.proxy_ui_refresh_sig.emit()
            enabled = self.proxy_mgr.get_enabled_proxies()
            
        if not enabled:
            self.proxy_mgr.log("⚠️ Cảnh báo: Không có proxy nào trong danh sách cấu hình. Vui lòng cấu hình proxy trong tab Proxy!")
            return
            
        # 2. Tự động bật Auto Xoay nếu chưa chạy
        if not self.proxy_mgr.is_auto_rotating:
            self.proxy_mgr.log("⚡ Tự động kích hoạt tính năng Auto Xoay Proxy...")
            self.proxy_mgr.start_auto_rotate()
            if hasattr(self, "proxy_auto_btn"):
                self.proxy_auto_btn.setText("⏹ Tắt Auto Xoay")
            self.proxy_ui_refresh_sig.emit()

        # 3. Xoay IP đồng bộ cho bất kỳ proxy xoay nào chưa có IP hoạt động (current_proxy_http rỗng)
        inactive_rotating = [p for p in enabled if p.type == "rotating" and not p.current_proxy_http]
        if inactive_rotating:
            self.proxy_mgr.log("⚡ Phát hiện proxy xoay chưa được kích hoạt. Tiến hành xoay IP tự động...")
            for p in inactive_rotating:
                self.proxy_mgr.log(f"🔄 Đang kết nối và xoay IP cho proxy: {p.name}...")
                success = self.proxy_mgr.rotate_proxy(p)
                if success:
                    self.proxy_mgr.log(f"✅ Xoay IP thành công cho proxy [{p.name}]! IP hoạt động mới: {p.current_exit_ip}")
                    self.proxy_ui_refresh_sig.emit()
                else:
                    self.proxy_mgr.log(f"❌ Xoay IP thất bại cho proxy [{p.name}]: {p.last_error or 'Lỗi kết nối'}")

    def _on_sb_use_proxy_changed(self, state):
        # state 2 is Checked
        is_checked = (state == 2) or (hasattr(Qt, "CheckState") and state == Qt.CheckState.Checked)
        if is_checked:
            import threading
            threading.Thread(target=self._ensure_proxies_active, daemon=True).start()

    def _load_settings_to_ui(self, sp):
        if not sp:
            return
        
        # Block signals to avoid triggering callbacks while populating
        if hasattr(self, "sb_llm_model"):
            self.sb_llm_model.blockSignals(True)
            if sp.llm_model:
                self.sb_llm_model.setCurrentText(sp.llm_model)
            self.sb_llm_model.blockSignals(False)
            
        if hasattr(self, "sb_img_model"):
            self.sb_img_model.blockSignals(True)
            if sp.img_model:
                self.sb_img_model.setCurrentText(sp.img_model)
            self.sb_img_model.blockSignals(False)
            
        if hasattr(self, "sb_vid_model"):
            self.sb_vid_model.blockSignals(True)
            if sp.vid_model:
                self.sb_vid_model.setCurrentText(sp.vid_model)
            self.sb_vid_model.blockSignals(False)
            
        if hasattr(self, "sb_use_proxy_chk"):
            self.sb_use_proxy_chk.blockSignals(True)
            self.sb_use_proxy_chk.setChecked(getattr(sp, "use_proxy", False))
            self.sb_use_proxy_chk.blockSignals(False)
            
        if hasattr(self, "sb_scene_count") and sp.num_scenes:
            self.sb_scene_count.blockSignals(True)
            self.sb_scene_count.setCurrentText(str(sp.num_scenes))
            self.sb_scene_count.blockSignals(False)
            
        if hasattr(self, "sb_aspect_combo") and sp.aspect:
            self.sb_aspect_combo.blockSignals(True)
            aspect_label = next((k for k, v in self._SB_ASPECT_MAP.items() if v == sp.aspect), None)
            if aspect_label:
                self.sb_aspect_combo.setCurrentText(aspect_label)
            self.sb_aspect_combo.blockSignals(False)
            
        if hasattr(self, "sb_audio_combo") and sp.audio_val:
            self.sb_audio_combo.blockSignals(True)
            audio_label = next((k for k, v in self._SB_AUDIO_MAP.items() if v == sp.audio_val), None)
            if audio_label:
                self.sb_audio_combo.setCurrentText(audio_label)
            self.sb_audio_combo.blockSignals(False)
            
        if hasattr(self, "sb_duration_combo") and sp.seconds_per_scene:
            self.sb_duration_combo.blockSignals(True)
            self.sb_duration_combo.setCurrentText(f"{sp.seconds_per_scene} giây")
            self.sb_duration_combo.blockSignals(False)
            
        if hasattr(self, "sb_img_size_combo") and sp.img_size:
            self.sb_img_size_combo.blockSignals(True)
            size_label = next((k for k, v in self._SB_SIZE_MAP.items() if v == sp.img_size), None)
            if size_label:
                self.sb_img_size_combo.setCurrentText(size_label)
            self.sb_img_size_combo.blockSignals(False)
            
        if hasattr(self, "sb_img_quality_combo") and sp.img_quality:
            self.sb_img_quality_combo.blockSignals(True)
            quality_label = next((k for k, v in self._SB_QUALITY_MAP.items() if v == sp.img_quality), None)
            if quality_label:
                self.sb_img_quality_combo.setCurrentText(quality_label)
            self.sb_img_quality_combo.blockSignals(False)
            
        if hasattr(self, "sb_video_resolution") and sp.video_resolution:
            self.sb_video_resolution.blockSignals(True)
            self.sb_video_resolution.setCurrentText(sp.video_resolution)
            self.sb_video_resolution.blockSignals(False)
            
        if hasattr(self, "sb_retry_spin") and getattr(sp, "max_retries", None) is not None:
            self.sb_retry_spin.blockSignals(True)
            self.sb_retry_spin.setCurrentText(f"{sp.max_retries} lần")
            self.sb_retry_spin.blockSignals(False)
            
        if hasattr(self, "sb_clone_count") and getattr(sp, "clone_count", None) is not None:
            self.sb_clone_count.blockSignals(True)
            self.sb_clone_count.setCurrentText(str(sp.clone_count))
            self.sb_clone_count.blockSignals(False)
            
        if hasattr(self, "sb_panels_combo") and sp.panels_per_storyboard:
            self.sb_panels_combo.blockSignals(True)
            self.sb_panels_combo.setCurrentText(f"{sp.panels_per_storyboard} ảnh")
            self.sb_panels_combo.blockSignals(False)

    def _proxy_add_rotating(self):
        if not self.proxy_mgr:
            return
        key = self.proxy_rot_key.text().strip()
        if not key:
            QMessageBox.warning(self, "Thiếu key", "Vui lòng nhập API Key xoay!")
            return
        name = self.proxy_rot_name.text().strip() or f"Key {len(self.proxy_mgr.proxies)+1}"
        nhamang = self.proxy_rot_nhamang.currentText()
        tinhthanh = self.proxy_rot_tinhthanh.currentText().split(" - ")[0].strip()
        interval = int(self.proxy_rot_interval.currentText().split()[0])
        pc = self.proxy_mgr.add_rotating(name, key, nhamang, tinhthanh, interval)
        self.proxy_mgr.rotate_proxy(pc)
        self.proxy_rot_key.clear()
        self.proxy_rot_name.clear()
        self._proxy_refresh_table()
        self._proxy_update_status()

    def _proxy_add_static(self):
        if not self.proxy_mgr:
            return
        host = self.proxy_st_host.text().strip()
        port_str = self.proxy_st_port.text().strip()
        if not host or not port_str:
            QMessageBox.warning(self, "Thiếu thông tin", "Nhập Host và Port!")
            return
        try:
            port = int(port_str)
        except ValueError:
            QMessageBox.warning(self, "Port lỗi", "Port phải là số!")
            return
        name = self.proxy_st_name.text().strip() or f"Static {len(self.proxy_mgr.proxies)+1}"
        user = self.proxy_st_user.text().strip()
        pwd = self.proxy_st_pass.text().strip()
        proto = self.proxy_st_proto.currentText()
        self.proxy_mgr.add_static(name, host, port, user, pwd, proto)
        self.proxy_st_host.clear()
        self.proxy_st_port.clear()
        self.proxy_st_user.clear()
        self.proxy_st_pass.clear()
        self.proxy_st_name.clear()
        self._proxy_refresh_table()
        self._proxy_update_status()

    def _proxy_delete_selected(self):
        if not self.proxy_mgr:
            return
        selected = self.proxy_table.selectedItems()
        if not selected:
            return
        rows = set(item.row() for item in selected)
        ids_to_remove = []
        for row in sorted(rows, reverse=True):
            if row < len(self.proxy_mgr.proxies):
                ids_to_remove.append(self.proxy_mgr.proxies[row].id)
        for pid in ids_to_remove:
            self.proxy_mgr.remove(pid)
        self._proxy_refresh_table()
        self._proxy_update_status()

    def _proxy_refresh_table(self):
        if not self.proxy_mgr or not hasattr(self, "proxy_table"):
            return
        from PyQt6.QtWidgets import QTableWidgetItem
        self.proxy_table.setRowCount(0)
        for p in self.proxy_mgr.proxies:
            row = self.proxy_table.rowCount()
            self.proxy_table.insertRow(row)
            chk = QTableWidgetItem("✅" if p.enabled else "❌")
            chk.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
            self.proxy_table.setItem(row, 0, chk)
            self.proxy_table.setItem(row, 1, QTableWidgetItem(p.name))
            self.proxy_table.setItem(row, 2, QTableWidgetItem("🔄 Xoay" if p.type == "rotating" else "📌 Tĩnh"))
            if p.type == "rotating" and p.current_proxy_http:
                parts = p.current_proxy_http.split(":")
                proxy_display = f"{parts[0]}:{parts[1]}" if len(parts) >= 2 else p.current_proxy_http
            elif p.type == "static":
                proxy_display = f"{p.host}:{p.port}" if p.host else "—"
            else:
                proxy_display = "Chưa xoay"
            self.proxy_table.setItem(row, 3, QTableWidgetItem(proxy_display))
            self.proxy_table.setItem(row, 4, QTableWidgetItem(p.current_exit_ip or "—"))
            self.proxy_table.setItem(row, 5, QTableWidgetItem(f"{p.current_isp} / {p.current_location}" if p.current_isp else "—"))
            self.proxy_table.setItem(row, 6, QTableWidgetItem(p.expires_at or "—"))
            if p.last_error:
                status = f"❌ {p.last_error[:30]}"
            elif p.current_proxy_http or (p.type == "static" and p.host):
                status = "🟢 Sẵn sàng"
            else:
                status = "⏳ Chờ xoay"
            self.proxy_table.setItem(row, 7, QTableWidgetItem(status))

    def _proxy_toggle_auto(self):
        if not self.proxy_mgr:
            return
        if self.proxy_mgr.is_auto_rotating:
            self.proxy_mgr.stop_auto_rotate()
            self.proxy_auto_btn.setText("▶ Bật Auto Xoay")
        else:
            if not self.proxy_mgr.get_enabled_proxies():
                QMessageBox.warning(self, "Trống", "Chưa có proxy! Thêm key xoay trước.")
                return
            self.proxy_mgr.start_auto_rotate()
            self.proxy_auto_btn.setText("⏹ Tắt Auto Xoay")
        self._proxy_update_status()

    def _proxy_rotate_now(self):
        if not self.proxy_mgr:
            return
        if not self.proxy_mgr.get_enabled_proxies():
            QMessageBox.warning(self, "Trống", "Chưa có proxy!")
            return
        self.proxy_mgr.rotate_all()
        self._proxy_refresh_table()
        self._proxy_update_status()

    def _proxy_test(self):
        if not self.proxy_mgr:
            return
        self._proxy_log("🔍 Đang test proxy...")
        def _do():
            result = self.proxy_mgr.test_proxy()
            if result["ok"]:
                self._proxy_log(f"✅ Proxy OK! IP: {result['ip']}")
            else:
                self._proxy_log(f"❌ Lỗi: {result['error']}")
        threading.Thread(target=_do, daemon=True).start()

    def _proxy_update_status(self):
        if not self.proxy_mgr or not hasattr(self, "proxy_status_lbl"):
            return
        enabled = self.proxy_mgr.get_enabled_proxies()
        ready = [p for p in enabled if p.get_httpx_proxy_url()]
        if not enabled:
            self.proxy_status_lbl.setText("🔴 Chưa có proxy")
            self.proxy_status_lbl.setStyleSheet("font-size: 12px; font-weight: bold; color: #dc2626; padding: 6px;")
            self.proxy_ip_lbl.setText("🌍 IP: —")
        elif not ready:
            self.proxy_status_lbl.setText("🟡 Proxy chưa xoay")
            self.proxy_status_lbl.setStyleSheet("font-size: 12px; font-weight: bold; color: #d97706; padding: 6px;")
            self.proxy_ip_lbl.setText("🌍 IP: —")
        else:
            auto_txt = " (Auto)" if self.proxy_mgr.is_auto_rotating else ""
            self.proxy_status_lbl.setText(f"🟢 {len(ready)} proxy sẵn sàng{auto_txt}")
            self.proxy_status_lbl.setStyleSheet("font-size: 12px; font-weight: bold; color: #16a34a; padding: 6px;")
            ips = [p.current_exit_ip for p in ready if p.current_exit_ip]
            self.proxy_ip_lbl.setText(f"🌍 IP: {', '.join(ips[:3])}" if ips else "🌍 IP: —")

    def _akl_make_project_proxy(self):
        """Tạo project proxy object có đúng attributes cho auto_lipsync_widget."""
        class _AKLProxy:
            """Proxy project object tương thích với auto_lipsync_widget."""
            pass

        proj = _AKLProxy()
        # Basic info
        proj.name = "Auto Khớp Lời"
