        # Tạo download/data directories
        akl_base = AUTOKHOPLOI_OUTPUT_DIR / _get_safe_project_name(proj.id)
        akl_base.mkdir(parents=True, exist_ok=True)
        dl_dir = akl_base / "batch_video"
        dl_dir.mkdir(parents=True, exist_ok=True)

