        proj.dl_dir = str(akl_base)

        # Batch config defaults (sẽ được auto_lipsync_widget override qua UI)
        proj.batch_mode = "Video + Ingredients"
        proj.batch_model = "Omni Flash"
        proj.batch_aspect = "Doc"
        proj.batch_count = "x4"
        proj.batch_duration = "8s"
        proj.batch_grok_quality = "720p"
        proj.batch_workers_per_account = 10
        proj.batch_max_retries = 5
        proj.batch_poll_timeout = 150
        proj.batch_stable_wait = 30
        proj.batch_tab_delay = 7
        proj.batch_headless = True
        proj.batch_use_proxy = False
        proj.batch_clone_count = 0
        proj.batch_clone_mode = "Project khac"
        proj.batch_prompts = []
        proj.batch_account_emails = []
        proj.batch_prompt_images = []

        # Auto Video defaults
        proj.av_enabled = False
        proj.av_join_mode = "Khớp voice"
        proj.av_audio = ""
        proj.av_json_path = ""
        proj.av_music = ""
        proj.av_resolution = "Dọc FHD"
        proj.av_whisper_model = "small"
        proj.av_language = "vi"
        proj.av_device = "cpu"
        proj.av_keep_video_audio = True
        proj.av_video_volume = 0.3
        proj.av_music_volume = 0.2
        proj.av_voice_volume = 1.0
        proj.av_loop_music = True
        proj.av_transition = "khong"
        proj.av_transition_duration = 0.5
        proj.av_speed = 1.15
        proj.av_num_variations = 1
        proj.av_strict = False
        proj.av_delete_originals = False
        proj.av_ken_burns = "random"
