    def refresh_dashboard(self):
        """Rebuild the project cards grid."""
        # Clear existing cards
        while self.dashboard_grid.count():
            item = self.dashboard_grid.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        projects = self.proj_mgr.projects
        if not projects:
            empty_lbl = QLabel(
                "Chưa có dự án nào.\nBấm '+ Tạo Dự Án Mới' để bắt đầu."
            )
            empty_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            empty_lbl.setStyleSheet(
                "font-size: 14px; color: #94a3b8; padding: 60px;"
            )
            self.dashboard_grid.addWidget(empty_lbl, 0, 0, 1, 3)
            return

        cols = 3
        for idx, proj in enumerate(projects):
            card = self._build_project_card(proj)
            self.dashboard_grid.addWidget(card, idx // cols, idx % cols)

        # Fill remaining cells in last row with spacers
        remaining = cols - (len(projects) % cols)
        if remaining < cols:
            row = (len(projects) - 1) // cols
            for c in range(cols - remaining, cols):
                spacer = QWidget()
                self.dashboard_grid.addWidget(spacer, row, c)

        self.dashboard_grid.setRowStretch(self.dashboard_grid.rowCount(), 1)

    def _build_project_card(self, proj: "Project") -> QFrame:
        """Build a single project card widget."""
        card = QFrame()
        card.setFixedHeight(200)
        card.setObjectName("card")
        card.setStyleSheet(
            "QFrame#card { background: #ffffff; border: 1px solid #e2e8f0; "
            "border-radius: 12px; }"
            "QFrame#card:hover { border-color: #a78bfa; }"
        )
        lay = QVBoxLayout(card)
        lay.setContentsMargins(16, 14, 16, 12)
        lay.setSpacing(8)

        # ── Row 1: Name + mode badge + delete ───────────────────
        r1 = QWidget()
        r1_lay = QHBoxLayout(r1)
        r1_lay.setContentsMargins(0, 0, 0, 0)

        name_lbl = QLabel(proj.name)
        name_lbl.setStyleSheet("font-size: 13px; font-weight: bold; color: #1e293b;")
