        mode_colors = {"studio": "#7c3aed", "storyboard": "#0891b2", "animal": "#059669", "roleskill": "#d97706", "autokhoploi": "#0ea5e9"}
        mode_labels = {"studio": "🎬 Studio", "storyboard": "🎞 Storyboard", "animal": "🐾 Animal Story", "roleskill": "🎭 Role Skill", "autokhoploi": "🎙 Auto Khớp Lời"}
        mode_lbl = QLabel(mode_labels.get(proj.mode, proj.mode))
        mode_lbl.setStyleSheet(
            f"font-size: 9px; font-weight: bold; color: white; "
            f"background: {mode_colors.get(proj.mode,'#475569')}; "
            f"border-radius: 4px; padding: 2px 6px;"
        )
        r1_lay.addWidget(mode_lbl)

        dup_btn = QPushButton("👯")
