        dup_btn.setStyleSheet(
            "QPushButton { border: none; border-radius: 4px; color: #7c3aed; "
            "background: transparent; font-size: 13px; }"
            "QPushButton:hover { background: #ede9fe; }"
        )
        dup_btn.setToolTip("Sao chép dự án")
        dup_btn.clicked.connect(lambda _, pid=proj.id: self._duplicate_project(pid))
        r1_lay.addWidget(dup_btn)

        del_btn = QPushButton("🗑")
