    def _action_btn_style(self, color: str) -> str:
        return (
            f"QPushButton {{ background: {color}; color: white; font-weight: bold; "
            f"font-size: 11px; border: none; border-radius: 5px; height: 32px; padding: 0 12px; }}"
            f"QPushButton:hover {{ background: opacity 0.8; }}"
            f"QPushButton:disabled {{ background: #c4b5fd; }}"
        )

    # ── View changed handler ───────────────────────────────────
    def _sb_on_view_changed(self, text: str):
        """View mode locked to list — no-op."""
        pass

    def _sb_rearrange_grid(self):
        """Layout tất cả cards dạng List (từ trên xuống dưới)."""
        # Clear grid
        while self.sb_grid_layout.count():
            self.sb_grid_layout.takeAt(0)
        
        for i, card in enumerate(self._sb_cards):
            card.idx = i
            card.set_view_mode("list")
            self.sb_grid_layout.addWidget(card, i, 0, 1, 1)
        
        if not self._sb_cards:
            self.sb_empty_lbl.setVisible(True)

    def _sb_on_start_clicked(self):
        if not self._sb_cards:
            QMessageBox.warning(self, "Trống", "Chưa có sản phẩm nào. Hãy nhấn '📁 Thêm ảnh SP'!")
            return
        if not self.acc_mgr.active:
            QMessageBox.warning(self, "Thiếu tài khoản", "Cần ít nhất 1 tài khoản hoạt động!")
            return

        if self._sb_running:
            if self._sb_paused:
                self._sb_paused = False
                self.sb_pause_btn.setText("⏸ Tạm dừng")
                self.sb_start_btn.setEnabled(False)
                self._sb_log("▶ Tiếp tục xử lý hàng chờ...")
                # Resume all active cards that were paused
                for card in self._sb_active_cards:
                    self._sb_process_card(card)
                # Also try to start more products if thread count limit allows
                self._sb_start_next_products()
            return

        # Cập nhật cài đặt mới nhất từ UI cho toàn bộ các StoryProject trong dự án và lưu lại
        settings = self._sb_build_batch_settings()
        if settings.get("use_proxy"):
            self._ensure_proxies_active()
        for sp in self.proj_mgr.story_projects:
            sp.llm_model = settings.get("llm_model", sp.llm_model)
            sp.img_model = settings.get("img_model", sp.img_model)
            sp.vid_model = settings.get("vid_model", sp.vid_model)
            sp.img_size = settings.get("img_size", sp.img_size)
            sp.img_quality = settings.get("img_quality", sp.img_quality)
            sp.video_resolution = settings.get("video_resolution", sp.video_resolution)
            sp.clone_count = settings.get("clone_count", sp.clone_count)
            sp.num_scenes = settings.get("scene_count", sp.num_scenes)
            sp.aspect = settings.get("aspect", sp.aspect)
            sp.aspect_label = settings.get("aspect_label", sp.aspect_label)
            sp.seconds_per_scene = settings.get("duration", sp.seconds_per_scene)
            sp.audio_val = settings.get("audio_val", sp.audio_val)
            sp.panels_per_storyboard = settings.get("panels_per_storyboard", sp.panels_per_storyboard)
            sp.use_proxy = settings.get("use_proxy", sp.use_proxy)
            if settings.get("system_prompt"):
                sp.system_prompt_override = settings.get("system_prompt")
        self.proj_mgr.save_story_projects()

        # Nhân bản sản phẩm nếu có cấu hình Clone sản phẩm > 0
        prod_clone_count = self.sb_prod_clone_count.value() if hasattr(self, 'sb_prod_clone_count') else 0
        if prod_clone_count > 0:
            import re
            original_cards = []
            for card in self._sb_cards:
                sp = getattr(card, '_story_project', None)
                if sp and not re.search(r'_clone_\d+$', sp.name):
                    original_cards.append((card, sp))
            
            if original_cards:
                self._sb_log(f"👥 Phát hiện cấu hình Clone sản phẩm: {prod_clone_count}. Tiến hành nhân bản...")
                cloned_any = False
                for card, sp in original_cards:
                    for c_idx in range(1, prod_clone_count + 1):
                        clone_name = f"{sp.name}_clone_{c_idx:02d}"
                        # Tránh nhân bản trùng nếu đã tồn tại bản clone tên này
                        exists = any(getattr(c, '_story_project', None) and getattr(c, '_story_project').name == clone_name for c in self._sb_cards)
                        if exists:
                            continue
                        
                        # Tạo project clone mới
                        new_sp = StoryProject(
                            product_image_path=sp.product_image_path,
                            name=clone_name,
                            project_id=sp.project_id,
                            product_info=sp.product_info,
                            product_visual_desc=sp.product_visual_desc,
                            num_scenes=sp.num_scenes,
                            seconds_per_scene=sp.seconds_per_scene,
                            panels_per_storyboard=sp.panels_per_storyboard,
                            aspect=sp.aspect,
                            aspect_label=sp.aspect_label,
                            img_model=sp.img_model,
                            vid_model=sp.vid_model,
                            llm_model=sp.llm_model,
                            img_size=sp.img_size,
                            img_quality=sp.img_quality,
                            video_resolution=sp.video_resolution,
                            audio_val=sp.audio_val,
                            system_prompt_override=sp.system_prompt_override,
                            clone_count=sp.clone_count,
                            reference_image_paths=list(sp.reference_image_paths),
                            selected_context=sp.selected_context,
                            mode=sp.mode,
                            role_skill_file=getattr(sp, "role_skill_file", "")
                        )
                        new_sp.voice_paths = list(getattr(sp, 'voice_paths', []))
                        
                        # Tạo card UI mới
                        idx = len(self._sb_cards)
                        new_card = SBProductCard(idx, new_sp.product_image_path, self, name=new_sp.name)
                        new_card.set_view_mode(self.sb_gallery_view)
                        new_card.edit_name.setText(new_sp.name)
                        new_card.edit_req.setPlainText(new_sp.product_info)
                        new_card.ref_paths = list(new_sp.reference_image_paths)
                        new_card._update_ref_thumbnails()
                        
                        if new_sp.selected_context:
                            found_idx = -1
                            for i in range(new_card.context_combo.count()):
                                if i < len(new_card.contexts) and new_card.contexts[i]["description"] == new_sp.selected_context:
                                    found_idx = i
                                    break
                            if found_idx >= 0:
                                new_card.context_combo.blockSignals(True)
                                new_card.context_combo.setCurrentIndex(found_idx)
                                new_card.context_combo.blockSignals(False)
                            new_card.context_preview.setPlainText(new_sp.selected_context)
                            
                        new_card._story_project = new_sp
                        
                        orig_idx = self._sb_cards.index(card)
                        insert_pos = orig_idx + c_idx
                        self.proj_mgr.story_projects.insert(insert_pos, new_sp)
                        self._sb_cards.insert(insert_pos, new_card)
                        cloned_any = True
                        self._sb_log(f"👥 Đã tạo bản clone sản phẩm: {new_sp.name}")
                
                if cloned_any:
                    self.proj_mgr.save_story_projects()
                    self._sb_rearrange_grid()

        # Cập nhật cấu hình hiện tại từ thanh công cụ cho các sản phẩm
        settings = self._sb_build_batch_settings()
        for card in self._sb_cards:
            sp = getattr(card, '_story_project', None)
            if sp:
                sp.llm_model = settings["llm_model"]
                sp.img_model = settings["img_model"]
                sp.vid_model = settings["vid_model"]
                sp.img_size = settings["img_size"]
                sp.img_quality = settings["img_quality"]
                sp.video_resolution = settings["video_resolution"]
                sp.audio_val = settings["audio_val"]
                sp.aspect = settings["aspect"]
                sp.aspect_label = settings["aspect_label"]
                sp.panels_per_storyboard = settings["panels_per_storyboard"]
                sp.seconds_per_scene = settings["duration"]
                sp.clone_count = settings["clone_count"]
                sp.use_proxy = settings["use_proxy"]
                
                # Chỉ thay đổi số scene nếu kịch bản chưa được tạo thành công
                if not sp.scenes or sp.status in ("queued", "scripting"):
                    sp.num_scenes = settings["scene_count"]
                    
        self.proj_mgr.save_story_projects()

        self._sb_running = True
        self._sb_paused = False

        # ━━ Reset scenes bị stuck do app bị đóng giữa chừng ━━
        stale_reset = 0
        for card in self._sb_cards:
            sp = getattr(card, '_story_project', None)
            if not sp:
                continue
            for scene in sp.scenes:
                if scene.status == "img_gen":
                    # Kiểm tra xem ảnh đã tạo xong chưa
                    _has_img = scene.storyboard_image_path and Path(scene.storyboard_image_path).exists()
                    if _has_img:
                        scene.status = "img_done"  # Ảnh có rồi, chỉ cần video
                    else:
                        scene.status = "pending"   # Cần tạo lại ảnh
                    stale_reset += 1
                elif scene.status == "vid_gen":
                    # Worker đã chết, ảnh đã xong → reset về img_done để tạo lại video
                    scene.status = "img_done"
                    stale_reset += 1
                elif scene.status == "pending" and scene.storyboard_image_path and Path(scene.storyboard_image_path).exists():
                    # Thảnh thái 'pending' nhưng ảnh đã có trên disk → sửa lại
                    _has_vid = scene.video_path and Path(scene.video_path).exists()
                    scene.status = "done" if _has_vid else "img_done"
                    stale_reset += 1
            if sp.status == "scripting":
                sp.status = "queued"
                stale_reset += 1
            elif sp.status in ("generating", "assembling"):
                if not sp.scenes:
                    # Bị ngắt giữa chuyện trước khi kịp sinh kịch bản → quay về queued
                    sp.status = "queued"
                    stale_reset += 1
                # else: có scenes rồi, giữ nguyên để tiếp tục
        if stale_reset:
            self._sb_log(f"🔄 Đã reset {stale_reset} phân cảnh bị stuck (app tắt giữa chừng).")
            self.proj_mgr.save_story_projects()

        # Only queue cards that have pending work
        needs_work = []
        for _c in self._sb_cards:
            _sp = getattr(_c, '_story_project', None)
            if not _sp:
                needs_work.append(_c)
                continue
            if _sp.status in ('done',) and _sp.scenes:
                if all(s.status == 'done' for s in _sp.scenes):
                    continue
            needs_work.append(_c)

        if not needs_work:
            self._sb_log('✅ Tất cả sản phẩm đã hoàn thành! Không có gì cần chạy thêm.')
            return

        self._sb_pending_queue = needs_work
        self._sb_active_cards = []
        
        # 3 separate thread pools counters
        self._sb_active_chat_count = 0
        self._sb_active_img_count = 0
        self._sb_active_vid_count = 0
        
        # 3 separate delay tracking timestamps
        self._sb_last_chat_dispatch_time = 0.0
        self._sb_last_img_dispatch_time = 0.0
        self._sb_last_vid_dispatch_time = 0.0
        self._sb_last_start_time = 0.0
        
        self.sb_start_btn.setEnabled(False)
        self.sb_pause_btn.setEnabled(True)
        self.sb_pause_btn.setText("⏸ Tạm dừng")
        self.sb_clear_btn.setEnabled(False)
        self.sb_total_progress.setValue(0)
        self.sb_total_progress.setMaximum(len(self._sb_pending_queue))
        self.sb_status_lbl.setText("⚙ Đang chạy...")
        self._sb_log("═══ Bắt đầu Pipeline hàng loạt sản phẩm ═══")
        # Reset card visual status để _sb_start_next_products không dừng sớm
        for _rc in needs_work:
            _rc.set_status("waiting", "Đang chờ...")
        self._sb_start_next_products()

    def _sb_on_pause_clicked(self):
        if not self._sb_running:
            return
        if not self._sb_paused:
            self._sb_paused = True
            self.sb_pause_btn.setText("▶ Tiếp tục")
            self.sb_start_btn.setEnabled(True)
            self.sb_status_lbl.setText("⏸ Tạm dừng")
            self._sb_log("⏸ Đã tạm dừng hàng chờ (Tác vụ đang chạy sẽ hoàn thành rồi dừng).")
        else:
            self._sb_paused = False
            self.sb_pause_btn.setText("⏸ Tạm dừng")
            self.sb_start_btn.setEnabled(False)
            self.sb_status_lbl.setText("⚙ Đang chạy...")
            self._sb_log("▶ Tiếp tục xử lý hàng chờ...")
            # Reset any failed scenes of active cards so they can retry on resume
            for card in self._sb_active_cards:
                sp = getattr(card, '_story_project', None)
                if sp and sp.scenes:
                    for i, scene in enumerate(sp.scenes):
                        if scene.status == "failed":
                            if scene.storyboard_image_path and Path(scene.storyboard_image_path).exists():
                                scene.status = "img_done"
                                card.update_scene_status(i, "waiting", "Chờ video...")
                            else:
                                scene.status = "pending"
                                card.update_scene_status(i, "waiting", "Chờ ảnh...")
            # Resume: re-scan ALL cards and re-add those with pending work
            for _rc in self._sb_cards:
                _rsp = getattr(_rc, '_story_project', None)
                if not _rsp or _rsp.status not in ('generating', 'scripting', 'queued'):
                    continue
                has_pending = any(s.status not in ('done', 'failed') for s in _rsp.scenes) if _rsp.scenes else True
                if has_pending and _rc not in self._sb_active_cards and _rc not in self._sb_pending_queue:
                    self._sb_active_cards.append(_rc)
            # Re-dispatch scenes for all active cards
            self._sb_dispatch_scenes()
            self._sb_start_next_products()
    def _sb_on_clear_clicked(self):
        if self._sb_running:
            return
        self._sb_clear_grid()
        self.sb_empty_lbl.setVisible(True)
        self._sb_log("🗑 Đã xóa tất cả sản phẩm.")

    def _sb_clear_cards_ui(self):
        """Chỉ xóa các card UI và danh sách cards tạm thời, giữ nguyên dữ liệu gốc."""
        self._sb_cards = []
        self._sb_selected_indices.clear()
        while self.sb_grid_layout.count():
            item = self.sb_grid_layout.takeAt(0)
            if item.widget() and item.widget() != self.sb_empty_lbl:
                item.widget().deleteLater()

    def _sb_clear_grid(self):
        self._sb_clear_cards_ui()
        # Clear saved story projects
        self.proj_mgr.story_projects.clear()
        self.proj_mgr.save_story_projects()

    def _sb_duplicate_product(self, card):
        """Sao chép thông tin sản phẩm và tạo card mới."""
        sp = getattr(card, '_story_project', None)
        if not sp:
            return
        
        # Tạo project mới từ thông tin của project cũ
        new_sp = StoryProject(
            product_image_path=sp.product_image_path,
            name=f"{sp.name} (Copy)",
            project_id=sp.project_id,
            product_info=sp.product_info,
            product_visual_desc=sp.product_visual_desc,
            num_scenes=sp.num_scenes,
            seconds_per_scene=sp.seconds_per_scene,
            panels_per_storyboard=sp.panels_per_storyboard,
            aspect=sp.aspect,
            aspect_label=sp.aspect_label,
            img_model=sp.img_model,
            vid_model=sp.vid_model,
            llm_model=sp.llm_model,
            img_size=sp.img_size,
            img_quality=sp.img_quality,
            video_resolution=sp.video_resolution,
            audio_val=sp.audio_val,
            system_prompt_override=sp.system_prompt_override,
            clone_count=sp.clone_count,
            reference_image_paths=list(sp.reference_image_paths),
            selected_context=sp.selected_context,
            mode=sp.mode,
            role_skill_file=getattr(sp, "role_skill_file", "")
        )
        
        # Tạo card mới trong giao diện
        idx = len(self._sb_cards)
        new_card = SBProductCard(idx, new_sp.product_image_path, self, name=new_sp.name)
        new_card.set_view_mode(self.sb_gallery_view)
        
        # Đồng bộ hóa nội dung hiển thị trên card
        new_card.edit_name.setText(new_sp.name)
        new_card.edit_req.setPlainText(new_sp.product_info)
        new_card.ref_paths = list(new_sp.reference_image_paths)
        new_card._update_ref_thumbnails()
        
        # Chọn bối cảnh cho card mới
        if new_sp.selected_context:
            found_idx = -1
            for i in range(new_card.context_combo.count()):
                if i < len(new_card.contexts) and new_card.contexts[i]["description"] == new_sp.selected_context:
                    found_idx = i
                    break
            if found_idx >= 0:
                new_card.context_combo.blockSignals(True)
                new_card.context_combo.setCurrentIndex(found_idx)
                new_card.context_combo.blockSignals(False)
            new_card.context_preview.setPlainText(new_sp.selected_context)
                
        new_card._story_project = new_sp
        
        # Chèn ngay sau bản gốc thay vì đẩy xuống cuối
        orig_idx = self._sb_cards.index(card) if card in self._sb_cards else len(self._sb_cards)
        insert_pos = orig_idx + 1
        self.proj_mgr.story_projects.insert(insert_pos if insert_pos <= len(self.proj_mgr.story_projects) else len(self.proj_mgr.story_projects), new_sp)
        self._sb_cards.insert(insert_pos if insert_pos <= len(self._sb_cards) else len(self._sb_cards), new_card)
        self.proj_mgr.save_story_projects()
        
        self._sb_log(f"👯 Đã sao chép sản phẩm: {new_sp.name}")
        self._sb_rearrange_grid()

    def _duplicate_project(self, project_id: str):
        """Sao chép một dự án cùng với tất cả thông tin sản phẩm và ảnh của nó (reset trạng thái)."""
        old_proj = next((p for p in self.proj_mgr.projects if p.id == project_id), None)
        if not old_proj:
            return
            
        # 1. Tạo Project mới
        new_proj = Project(
            name=f"{old_proj.name} (Copy)",
            mode=old_proj.mode,
            role_skill_file=getattr(old_proj, "role_skill_file", "")
        )
        # Chèn lên đầu danh sách (mới nhất/vừa sao chép đứng đầu)
        self.proj_mgr.projects.insert(0, new_proj)
        self.proj_mgr.save()
        
        # 2. Đọc file story_projects.json của dự án cũ
        old_path = PROJECTS_DATA_DIR / f"project_{old_proj.id}" / "story_projects.json"
        if old_path.exists():
            try:
                import json
                data = json.loads(old_path.read_text("utf-8"))
                new_data = []
                for d in data:
                    # Sao chép thông tin sản phẩm
                    new_sp = {
                        "id": uuid.uuid4().hex[:12],
                        "project_id": new_proj.id,
                        "name": d.get("name", ""),
                        "product_image_path": d.get("product_image_path", ""),
                        "product_info": d.get("product_info", ""),
                        "product_visual_desc": d.get("product_visual_desc", ""),
                        "video_title": d.get("video_title", ""),
                        "script_json": {},  # Reset kịch bản
                        "scenes": [],       # Reset phân cảnh
                        "final_video_path": "",
                        "status": "queued", # Reset trạng thái
                        "error_msg": "",
                        "num_scenes": d.get("num_scenes", 4),
                        "seconds_per_scene": d.get("seconds_per_scene", 10),
                        "panels_per_storyboard": d.get("panels_per_storyboard", 8),
                        "aspect": d.get("aspect", "16:9"),
                        "aspect_label": d.get("aspect_label", "Ngang (16:9)"),
                        "img_model": d.get("img_model", "gpt-image-2"),
                        "vid_model": d.get("vid_model", "grok-imagine-video-1.5-preview"),
                        "llm_model": d.get("llm_model", "gpt-4o"),
                        "img_size": d.get("img_size", "1536x1024"),
                        "img_quality": d.get("img_quality", "standard"),
                        "video_resolution": d.get("video_resolution", "720p"),
                        "audio_val": d.get("audio_val", "sound_effects_only"),
                        "system_prompt_override": d.get("system_prompt_override", ""),
                        "clone_count": d.get("clone_count", 1),
                        "reference_image_paths": d.get("reference_image_paths", []),
                        "selected_context": d.get("selected_context", ""),
                        "mode": d.get("mode", "storyboard"),
                        "voice_paths": d.get("voice_paths", []),
                        "role_skill_file": d.get("role_skill_file", "")
                    }
                    new_data.append(new_sp)
                
                # Lưu file story_projects.json cho dự án mới
                new_dir = PROJECTS_DATA_DIR / f"project_{new_proj.id}"
                new_dir.mkdir(parents=True, exist_ok=True)
                new_path = new_dir / "story_projects.json"
                new_path.write_text(
                    json.dumps(new_data, indent=2, ensure_ascii=False),
                    encoding="utf-8"
                )
            except Exception as e:
                self._sb_log(f"⚠️ Lỗi sao chép sản phẩm dự án: {e}")
                
        self.refresh_dashboard()
        self._sb_log(f"👯 Đã sao chép dự án: {old_proj.name} → {new_proj.name}")

    def _sb_randomize_contexts(self):
        """Random chọn bối cảnh cho tất cả sản phẩm trong dự án hiện tại."""
        if not self._sb_cards:
            QMessageBox.warning(self, "Trống", "Dự án chưa có sản phẩm nào!")
            return
            
        # Hỏi xác nhận người dùng
        reply = QMessageBox.question(
            self,
            "Xác nhận random",
            "Bạn có chắc muốn chọn ngẫu nhiên bối cảnh cho TẤT CẢ sản phẩm trong dự án này?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return
            
        import random
        for card in self._sb_cards:
            # Lấy danh sách bối cảnh từ card
            contexts = getattr(card, "contexts", [])
            if not contexts:
                continue
            # Chọn ngẫu nhiên một bối cảnh
            chosen = random.choice(contexts)
            # Tìm index của bối cảnh trong combobox
            idx = card.context_combo.findText(chosen["title"])
            if idx >= 0:
                card.context_combo.setCurrentIndex(idx)
                card._on_context_changed(idx)
        
        self.proj_mgr.save_story_projects()
        self._sb_log("🎲 Đã random bối cảnh cho tất cả sản phẩm thành công!")

    def _sb_delete_card(self, card: "SBProductCard"):
        """Xóa 1 product card khỏi pipeline và dữ liệu đã lưu."""
        if self._sb_running:
            QMessageBox.warning(self, "Đang chạy", "Không thể xóa sản phẩm khi pipeline đang hoạt động!")
            return
            
        reply = QMessageBox.question(
            self, "Xác nhận xóa",
            f"Bạn có chắc muốn xóa sản phẩm '{card.edit_name.text()}'?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if reply != QMessageBox.StandardButton.Yes:
            return
            
        # Xóa khỏi danh sách UI
        if card in self._sb_cards:
            self._sb_cards.remove(card)
            
        # Xóa khỏi project manager để persist
        sp = getattr(card, '_story_project', None)
        if sp and sp in self.proj_mgr.story_projects:
            self.proj_mgr.story_projects.remove(sp)
            self.proj_mgr.save_story_projects()
            
        card.deleteLater()
        self._sb_rearrange_grid()
        self._sb_log(f"🗑 Đã xóa sản phẩm: {card.edit_name.text()}")

    def _sb_delete_selected_cards(self):
        """Xóa các product card đã được tích chọn."""
        if self._sb_running:
            QMessageBox.warning(self, "Đang chạy", "Không thể xóa sản phẩm khi pipeline đang hoạt động!")
            return
            
        to_delete = [c for c in self._sb_cards if c.chk_select.isChecked()]
        if not to_delete:
            QMessageBox.information(self, "Thông báo", "Chưa chọn sản phẩm nào để xóa!")
            return
            
        reply = QMessageBox.question(
            self, "Xác nhận xóa",
            f"Bạn có chắc muốn xóa {len(to_delete)} sản phẩm đã chọn?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if reply != QMessageBox.StandardButton.Yes:
            return
            
        for card in to_delete:
            if card in self._sb_cards:
                self._sb_cards.remove(card)
            sp = getattr(card, '_story_project', None)
            if sp and sp in self.proj_mgr.story_projects:
                self.proj_mgr.story_projects.remove(sp)
                
        self.proj_mgr.save_story_projects()
        
        for card in to_delete:
            card.deleteLater()
            
        self._sb_rearrange_grid()
        self._sb_log(f"🗑 Đã xóa {len(to_delete)} sản phẩm đã chọn.")

    def _sb_reset_ui(self):
        self._sb_running = False
        self._sb_paused = False
        self._sb_active_cards = []
        self._sb_active_worker_count = 0
        self._sb_pending_queue = []
        self.sb_start_btn.setEnabled(True)
        self.sb_pause_btn.setEnabled(False)
        self.sb_pause_btn.setText("⏸ Tạm dừng")
        self.sb_clear_btn.setEnabled(True)

    def _sb_build_batch_settings(self) -> dict:
        n = int(self.sb_scene_count.currentText())
        aspect_label = self.sb_aspect_combo.currentText()
        aspect_val   = self._SB_ASPECT_MAP[aspect_label]
        audio_label  = self.sb_audio_combo.currentText()
        audio_val    = self._SB_AUDIO_MAP[audio_label]
        dur_text     = self.sb_duration_combo.currentText()
        duration     = int(dur_text.split()[0])
        img_size     = self._SB_SIZE_MAP[self.sb_img_size_combo.currentText()]
        img_quality  = self._SB_QUALITY_MAP[self.sb_img_quality_combo.currentText()]
        video_res    = self.sb_video_resolution.currentText()

        role_id = self.sb_role_combo.currentData()
        role = next((r for r in self.proj_mgr.role_skills if r["id"] == role_id), None)
        if role:
            system_prompt = role["system_prompt"]
        elif role_id and Path(str(role_id)).suffix.lower() in (".md", ".txt"):
            # Role Skill .MD file from data/role_skills/
            rs_path = get_role_skill_path(role_id)
            if rs_path and rs_path.exists():
                try:
                    system_prompt = rs_path.read_text(encoding="utf-8")
                except Exception:
                    system_prompt = ""
            else:
                system_prompt = ""
        else:
            system_prompt = ""

        panels = int(self.sb_panels_combo.currentText().split()[0])
        # Role Skill mode: force single image (no grid)
        if getattr(self, '_sb_roleskill_mode', False):
            panels = 1

        return {
            "llm_model":      self.sb_llm_model.currentText(),
            "img_model":      self.sb_img_model.currentText(),
            "vid_model":      self.sb_vid_model.currentText(),
            "img_size":       img_size,
            "max_retries":    int(self.sb_retry_spin.currentText().split()[0]) if hasattr(self, 'sb_retry_spin') else 3,
            "img_quality":    img_quality,
            "video_resolution": video_res,
            "clone_count":    int(self.sb_clone_count.currentText()) if hasattr(self, 'sb_clone_count') else 1,
            "scene_count":    n,
            "aspect":         aspect_val,
            "aspect_label":   aspect_label,
            "duration":       duration,
            "audio_val":      audio_val,
            "panels_per_storyboard": panels,
            "style":          "realistic_product_demo",
            "system_prompt":  system_prompt,
            "use_proxy":      self.sb_use_proxy_chk.isChecked() if hasattr(self, 'sb_use_proxy_chk') else False,
        }

    def _sb_select_from_tiktokshop(self):
        dialog = TiktokShopSelectDialog(self)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            path = dialog.selected_image_path
            title = dialog.selected_title
            desc = dialog.selected_description
            
            if path and Path(path).exists():
                if not self._sb_cards:
                    self.sb_empty_lbl.setVisible(False)
                
                idx = len(self._sb_cards)
                card = SBProductCard(idx, path, self)
                card.set_view_mode(self.sb_gallery_view)
                
                # Auto-fill card inputs
                card.edit_name.setText(title)
                card.edit_req.setPlainText(desc)
                
                # Create StoryProject
                settings = self._sb_build_batch_settings()
                sp = StoryProject(
                    product_image_path=path,
                    project_id=getattr(self.proj_mgr, "current_project_id", ""),
                    product_info=desc or title,
                    num_scenes=settings.get("scene_count", 4),
                    seconds_per_scene=settings.get("duration", 10),
                    panels_per_storyboard=settings.get("panels_per_storyboard", 8),
                    aspect=settings.get("aspect", "16:9"),
                    aspect_label=settings.get("aspect_label", "Ngang (16:9)"),
                    img_model=clean_model_name(settings.get("img_model", "gpt-image-2")),
                    vid_model=settings.get("vid_model", "grok-imagine-video-1.5-preview"),
                    llm_model=settings.get("llm_model", "gpt-4o"),
                    img_size=settings.get("img_size", "1536x1024"),
                    img_quality=settings.get("img_quality", "standard"),
                    video_resolution=settings.get("video_resolution", "720p"),
                    audio_val=settings.get("audio_val", "sound_effects_only"),
                    system_prompt_override=settings.get("system_prompt", ""),
                    clone_count=settings.get("clone_count", 1),
                    reference_image_paths=list(card.ref_paths),
                    selected_context=card.context_preview.toPlainText().strip(),
                    mode="roleskill" if getattr(self, "_sb_roleskill_mode", False) else "storyboard",
                    role_skill_file=self.sb_role_combo.currentData() if (getattr(self, "_sb_roleskill_mode", False) and hasattr(self, "sb_role_combo")) else ""
                )
                card._story_project = sp
                sp.voice_paths = dialog.selected_voices if dialog.selected_voices else []
                self.proj_mgr.story_projects.append(sp)
                
                self._sb_cards.append(card)
                self.proj_mgr.save_story_projects()
                self._sb_rearrange_grid()
                self._sb_log(f"✔ Đã thêm sản phẩm TiktokShop: {title}")

