    def ts_write_log(self, text):
        self.ts_txt_logs.append(text)
        self.ts_txt_logs.ensureCursorVisible()

    def ts_check_chrome_status(self):
        def _check():
            try:
                active = is_port_in_use(CDP_PORT) and is_chrome_cdp_active(CDP_PORT)
                self.chrome_status_sig.emit(active)
            except Exception:
                self.chrome_status_sig.emit(False)
        import threading
        threading.Thread(target=_check, daemon=True).start()

    def _safe_chrome_status(self, is_active):
        if hasattr(self, "ts_chrome_status") and self.ts_chrome_status:
            if is_active:
                self.ts_chrome_status.setText("🟢 Trình duyệt Chrome Spy ĐANG HOẠT ĐỘNG (Port 9222)")
                self.ts_chrome_status.setStyleSheet("color: #10b981; font-weight: bold;")
            else:
                self.ts_chrome_status.setText("🔴 Trình duyệt Chrome Spy CHƯA BẬT (Hãy nhấn nút Mở Chrome Spy)")
                self.ts_chrome_status.setStyleSheet("color: #ef4444; font-weight: bold;")

    def ts_action_open_chrome_spy(self):
        self.ts_write_log("[Chrome] Đang khởi động Chrome Spy với Profile & Cổng 9222...")
        if is_port_in_use(CDP_PORT):
            if is_chrome_cdp_active(CDP_PORT):
                self.ts_write_log("🟢 [Chrome] Chrome Spy đã chạy sẵn trên cổng 9222.")
                QMessageBox.information(self, "Chrome Spy", "Chrome Spy đã chạy sẵn trên cổng 9222.\nBạn có thể bắt đầu cào sản phẩm.")
                self.ts_check_chrome_status()
                return
            else:
                self.ts_write_log("⚠️ Cổng 9222 đang bận nhưng không phản hồi CDP. Hãy đóng đúng cửa sổ Chrome Spy cũ hoặc xử lý cổng này; tool không tắt Chrome/Google Flow của ứng dụng khác.")
                return

        chrome_path = find_chrome_path()
        if not chrome_path:
            self.ts_write_log("❌ Không tìm thấy Google Chrome cài đặt trên máy.")
            QMessageBox.critical(self, "Lỗi Chrome Spy", "Không tìm thấy đường dẫn cài đặt Google Chrome trên hệ thống của bạn!")
            return

        cmd = [
            chrome_path,
            f"--user-data-dir={PROFILE_DIR.resolve()}",
            f"--remote-debugging-port={CDP_PORT}",
            "--remote-allow-origins=*",
            "--no-first-run",
            "--no-default-browser-check",
            "--disable-default-apps",
            "--disable-blink-features=AutomationControlled",
            "https://www.tiktok.com"
        ]
        try:
            creation_flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
            subprocess.Popen(cmd, creationflags=creation_flags)
            self.ts_write_log("🟢 Khởi động Chrome Spy thành công.")
            QMessageBox.information(self, "Chrome Spy", "Đã khởi động Chrome thành công.\nVui lòng sử dụng cửa sổ Chrome mới mở này đăng nhập TikTok (nếu cần) và giữ Chrome luôn mở trong lúc cào.")
        except Exception as e:
            self.ts_write_log(f"❌ Lỗi khởi động Chrome: {e}")
            QMessageBox.critical(self, "Lỗi Chrome Spy", f"Không thể khởi động Chrome:\n{e}")
        self.ts_check_chrome_status()

    def ts_action_import_cookies(self):
        cookie_str, ok = QInputDialog.getMultiLineText(
            self, "Nhập Cookies TikTok",
            "Dán Cookie String (dạng name1=value1; name2=value2) hoặc JSON Cookies vào đây:"
        )
        if not ok or not cookie_str.strip():
            return
            
        cookies_list = []
        try:
            parsed = json.loads(cookie_str.strip())
            if isinstance(parsed, list):
                for c in parsed:
                    if isinstance(c, dict) and "name" in c and "value" in c:
                        if "domain" not in c or not c["domain"]:
                            c["domain"] = ".tiktok.com"
                        cookies_list.append(c)
            else:
                raise ValueError("JSON must be a list of cookies")
        except Exception:
            pairs = [p.strip() for p in cookie_str.split(';') if p.strip()]
            for p in pairs:
                if '=' in p:
                    k, v = p.split('=', 1)
                    cookies_list.append({
                        "name": k.strip(),
                        "value": v.strip(),
                        "domain": ".tiktok.com",
                        "path": "/"
                    })
                    
        if not cookies_list:
            QMessageBox.warning(self, "Lỗi", "Không tìm thấy cookies hợp lệ!")
            return
            
        if not is_chrome_cdp_active(CDP_PORT):
            QMessageBox.warning(self, "Lỗi", "Vui lòng bấm 'MỞ CHROME SPY' trước để mở trình duyệt, sau đó mới nhập cookies!")
            return
            
        try:
            from playwright.sync_api import sync_playwright
            with sync_playwright() as p:
                browser = p.chromium.connect_over_cdp(f"http://127.0.0.1:{CDP_PORT}")
                context = browser.contexts[0] if browser.contexts else browser.new_context()
                context.add_cookies(cookies_list)
                page = context.new_page()
                page.goto("https://www.tiktok.com", timeout=15000)
                page.close()
                browser.close()
            self.ts_write_log(f"[Chrome] Đã nhập và áp dụng thành công {len(cookies_list)} cookies vào Chrome Spy!")
            QMessageBox.information(self, "Thành công", f"Đã nhập thành công {len(cookies_list)} cookies vào Chrome Spy!")
        except Exception as e:
            self.ts_write_log(f"❌ Lỗi áp dụng cookies: {e}")
            QMessageBox.critical(self, "Lỗi", f"Không thể áp dụng cookies vào Chrome Spy:\n{e}")

    def ts_action_import_file(self):
        file_path, _ = QFileDialog.getOpenFileName(
            self, "Chọn file chứa Links", "",
            "Supported Files (*.txt *.csv *.xlsx *.xls);;Text Files (*.txt);;CSV Files (*.csv);;All Files (*)"
        )
        if file_path:
            self.ts_lbl_file_path.setText(os.path.basename(file_path))
            try:
                urls = []
                ext = os.path.splitext(file_path)[1].lower()
                if ext in ['.xlsx', '.xls']:
                    self.ts_write_log(f"📁 Đang đọc Excel: {file_path}...")
                    import openpyxl
                    wb = openpyxl.load_workbook(file_path, data_only=True, read_only=True)
                    sheet = wb.active
                    
                    rows = list(sheet.iter_rows(values_only=True))
                    header_row = rows[0] if rows else None
                    link_col_idx = -1
                    if header_row:
                        for idx, val in enumerate(header_row):
                            if val:
                                val_lower = str(val).lower()
                                if 'image' not in val_lower and 'ảnh' not in val_lower and 'video' not in val_lower and any(k in val_lower for k in ['product link', 'liên kết sản phẩm', 'link sản phẩm', 'link', 'url', 'sản phẩm', 'product']):
                                    link_col_idx = idx
                                    break
                    
                    start_row = 1 if link_col_idx >= 0 else 0
                    col_idx = link_col_idx if link_col_idx >= 0 else 0
                    
                    for row in rows[start_row:]:
                        if row and col_idx < len(row) and row[col_idx]:
                            val = str(row[col_idx]).strip()
                            if val.startswith("http"):
                                urls.append(val)
                elif ext == '.csv':
                    self.ts_write_log(f"📁 Đang đọc CSV: {file_path}...")
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        reader = csv.reader(f)
                        for row in reader:
                            if row:
                                for col in row:
                                    val = col.strip()
                                    if val.startswith("http"):
                                        urls.append(val)
                                        break
                else:
                    self.ts_write_log(f"📁 Đang đọc File Text: {file_path}...")
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        for line in f:
                            val = line.strip()
                            if val.startswith("http"):
                                urls.append(val)

                if urls:
                    self.ts_txt_urls.setPlainText("\n".join(urls))
                    self.ts_write_log(f"✅ Đã tìm thấy {len(urls)} links sản phẩm từ file.")
                else:
                    self.ts_write_log("⚠️ Không tìm thấy link hợp lệ nào bắt đầu bằng http trong file.")
            except Exception as e:
                self.ts_write_log(f"❌ Lỗi đọc file: {e}")

    def ts_action_download_voice_selected(self):
        """Tải voice MP3 cho sản phẩm đang chọn trong bảng."""
        row = self.ts_table_products.currentRow()
        if row < 0:
            QMessageBox.warning(self, "Chưa chọn", "Vui lòng chọn một sản phẩm trong danh sách!")
            return

        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            return
        products = json.loads(prod_json.read_text(encoding="utf-8"))
        if row >= len(products):
            return
        prod = products[row]

        # Lấy URL video: ưu tiên URL nhập thủ công, sau đó lấy video liên quan
        manual_url = self.ts_edit_voice_url.text().strip()
        if manual_url and manual_url.startswith("http"):
            video_url = manual_url
        else:
            related = prod.get("related_videos", [])
            if not related:
                QMessageBox.information(self, "Không có video",
                    "Sản phẩm này chưa có video liên quan. Hãy dán link video TikTok vào ô bên cạnh nút Tải Voice!")
                return
            video_url = related[0] if isinstance(related[0], str) else related[0].get("url", "")

        output_dir = DOWNLOADS_DIR / "voices" / prod.get("product_id", f"row_{row}")
        output_dir.mkdir(parents=True, exist_ok=True)

        api_key = getattr(self, "tikwm_api_key", None)
        worker = VoiceDownloadWorker(video_url, str(output_dir), api_key)
        worker.signals = WorkerSignals() if hasattr(worker, 'signals') else None

        def on_done(msg):
            self.ts_write_log(f"✅ Voice [{prod.get('title','')[:30]}]: {msg}")
            self.ts_refresh_products_table()

        def on_err(msg):
            self.ts_write_log(f"❌ Voice [{prod.get('title','')[:30]}]: {msg}")

        worker.finished.connect(on_done)
        worker.error.connect(on_err)
        QThreadPool.globalInstance().start(worker)
        self.ts_write_log(f"🎵 Đang tải voice: {prod.get('title','')[:50]}...")

    def ts_action_download_voice_all(self):
        """Tải voice MP3 cho tất cả sản phẩm chưa có voice."""
        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            self.ts_write_log("⚠️ Chưa có dữ liệu sản phẩm nào.")
            return
        products = json.loads(prod_json.read_text(encoding="utf-8"))
        no_voice = [p for p in products if not p.get("voices")]
        if not no_voice:
            self.ts_write_log("✅ Tất cả sản phẩm đã có voice MP3!")
            return

        self.ts_write_log(f"🎵 Bắt đầu tải voice cho {len(no_voice)} sản phẩm chưa có voice...")
        api_key = getattr(self, "tikwm_api_key", None)
        for prod in no_voice:
            related = prod.get("related_videos", [])
            if not related:
                continue
            video_url = related[0] if isinstance(related[0], str) else related[0].get("url", "")
            if not video_url:
                continue
            output_dir = DOWNLOADS_DIR / "voices" / prod.get("product_id", "unknown")
            output_dir.mkdir(parents=True, exist_ok=True)
            worker = VoiceDownloadWorker(video_url, str(output_dir), api_key)

            def on_done(msg, p=prod):
                self.ts_write_log(f"✅ Voice [{p.get('title','')[:30]}]: {msg}")
                self.ts_refresh_products_table()

            def on_err(msg, p=prod):
                self.ts_write_log(f"❌ Voice [{p.get('title','')[:30]}]: {msg}")

            worker.finished.connect(on_done)
            worker.error.connect(on_err)
            QThreadPool.globalInstance().start(worker)

    def ts_action_add_to_current_project(self):
        """Thêm sản phẩm đang chọn vào dự án đang mở hiện tại."""
        row = self.ts_table_products.currentRow()
        if row < 0:
            QMessageBox.warning(self, "Chưa chọn", "Vui lòng chọn một sản phẩm trong danh sách!")
            return

        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            return
        products = json.loads(prod_json.read_text(encoding="utf-8"))
        if row >= len(products):
            return
        prod = products[row]

        # Lấy project đang mở
        current_pid = getattr(self.proj_mgr, "current_project_id", None)
        if not current_pid:
            QMessageBox.warning(self, "Chưa mở dự án",
                "Bạn chưa mở dự án nào. Hãy chọn hoặc tạo một dự án trước!")
