    def ts_action_start_crawl(self):
        urls_text = self.ts_txt_urls.toPlainText().strip()
        if not urls_text:
            QMessageBox.warning(self, "Lỗi", "Vui lòng nhập danh sách links cần cào!")
            return

        urls = [u.strip() for u in urls_text.split("\n") if u.strip()]
        if not urls:
            return

        if not is_port_in_use(CDP_PORT) or not is_chrome_cdp_active(CDP_PORT):
            QMessageBox.warning(self, "Chưa mở Chrome Spy", "Vui lòng bấm 'Mở Chrome Spy' và đăng nhập TikTok trước khi cào!")
            return

        self.ts_btn_start.setEnabled(False)
        self.ts_btn_stop.setEnabled(True)
        self.ts_progress_bar.setMaximum(len(urls))
        self.ts_progress_bar.setValue(0)

        self.ts_worker = CrawlWorker(urls, thread_count=self.ts_spin_threads.value())
        self.ts_worker.log_signal.connect(self.ts_write_log)
        self.ts_worker.progress_signal.connect(self.ts_on_crawl_progress)
        self.ts_worker.product_done_signal.connect(self.ts_on_product_done)
        self.ts_worker.finished_signal.connect(self.ts_on_crawl_finished)
        self.ts_worker.start()

    def ts_action_stop_crawl(self):
        if self.ts_worker:
            self.ts_worker.stop()
            self.ts_write_log("🛑 Đang dừng cào (đợi các luồng hiện tại tắt)...")
            self.ts_btn_stop.setEnabled(False)

    def ts_on_crawl_progress(self, completed, total):
        self.ts_progress_bar.setValue(completed)

    def ts_on_product_done(self, product_data):
        self.ts_refresh_products_table()

    def ts_on_crawl_finished(self, success, failed):
        self.ts_btn_start.setEnabled(True)
        self.ts_btn_stop.setEnabled(False)
        self.ts_lbl_stats.setText(f"Đã cào: {success+failed}/{success+failed} | Thành công: {success} | Thất bại: {failed}")
        QMessageBox.information(self, "Hoàn thành", f"Hoàn thành crawl! Thành công: {success} | Thất bại: {failed}")

    def ts_refresh_products_table(self):
        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            self.ts_table_products.setRowCount(0)
            return

        try:
            products = json.loads(prod_json.read_text(encoding="utf-8"))
            self.ts_table_products.setRowCount(len(products))
            for idx, prod in enumerate(products):
                self.ts_table_products.setItem(idx, 0, QTableWidgetItem(prod.get("product_id", "")))
                self.ts_table_products.setItem(idx, 1, QTableWidgetItem(prod.get("title", "")))
                self.ts_table_products.setItem(idx, 2, QTableWidgetItem(prod.get("price", "")))
                self.ts_table_products.setItem(idx, 3, QTableWidgetItem(prod.get("seller", "")))
                self.ts_table_products.setItem(idx, 4, QTableWidgetItem(prod.get("status", "Success")))
                # Cột 5: Voice MP3 — hiển thị số lượng file voice đã tải
                voices = prod.get("voices", [])
                voice_item = QTableWidgetItem(f"✅ {len(voices)} files" if voices else "—")
                voice_item.setForeground(QColor("#06b6d4") if voices else QColor("#64748b"))
                voice_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                self.ts_table_products.setItem(idx, 5, voice_item)
        except Exception as e:
            self.ts_write_log(f"⚠️ Lỗi cập nhật bảng sản phẩm: {e}")

    def _ts_load_tikwm_keys(self):
        """Load saved TikWm API keys vào list widget."""
        self._tikwm_keys = []  # list of {key, label, status}
        try:
            if self._TIKWM_KEYS_FILE.exists():
                data = json.loads(self._TIKWM_KEYS_FILE.read_text(encoding='utf-8'))
                self._tikwm_keys = data if isinstance(data, list) else []
        except Exception:
            pass
        # Pre-load user's key if no keys saved yet
        if not self._tikwm_keys:
            preset = getattr(self, 'tikwm_api_key', '') or ''
            if preset:
                self._tikwm_keys = [{'key': preset, 'label': 'Key 1', 'status': 'unknown'}]
        self._ts_refresh_key_list()

    def _ts_save_tikwm_keys(self):
        """Lưu danh sách keys vào file."""
        try:
            self._TIKWM_KEYS_FILE.parent.mkdir(parents=True, exist_ok=True)
            self._TIKWM_KEYS_FILE.write_text(
                json.dumps(self._tikwm_keys, ensure_ascii=False, indent=2), encoding='utf-8')
        except Exception as e:
            self.ts_write_log(f"⚠️ Lưu keys lỗi: {e}")

    def _ts_refresh_key_list(self):
        """Cập nhật hiển thị list widget."""
        if not hasattr(self, 'ts_key_list'):
            return
        self.ts_key_list.clear()
        for i, k in enumerate(self._tikwm_keys):
            st = k.get('status', 'unknown')
            badge = '✅' if st == 'ok' else '❌' if st == 'fail' else '❓'
            label = k.get('label') or f'Key {i+1}'
            display = f"{badge} {label}: {k['key'][:8]}...{k['key'][-4:]}"
            item = QListWidgetItem(display)
            item.setForeground(QColor('#06b6d4' if st == 'ok' else '#f87171' if st == 'fail' else '#94a3b8'))
            self.ts_key_list.addItem(item)
        # Update thread spinner suggestion based on active keys
        active_keys = [k for k in self._tikwm_keys if k.get('status') == 'ok']
        if active_keys:
            # Trial plan: 600 req/min = 10/s; suggest 10 threads
            suggested = min(10 * len(active_keys), 20)
            self.ts_spin_threads.setValue(suggested)
            self.ts_spin_threads.setToolTip(
                f"{len(active_keys)} key active → gợi ý {suggested} luồng (Trial: 10 req/s/key)"
            )
        else:
            self.ts_spin_threads.setValue(1)

    def _ts_add_tikwm_key(self):
        """Thêm key mới từ ô input."""
        key = self.ts_key_input.text().strip()
        if not key:
            return
        if any(k['key'] == key for k in self._tikwm_keys):
            self.ts_write_log("⚠️ Key này đã có trong danh sách.")
            return
        label = f"Key {len(self._tikwm_keys) + 1}"
        self._tikwm_keys.append({'key': key, 'label': label, 'status': 'unknown'})
        self._ts_save_tikwm_keys()
        self._ts_refresh_key_list()
        self.ts_key_input.clear()
        self.ts_write_log(f"➕ Đã thêm key: {key[:8]}... Nhấn 'Test Keys' để kiểm tra.")

    def _ts_del_tikwm_key(self):
        """Xóa key đang chọn."""
        row = self.ts_key_list.currentRow()
        if row < 0 or row >= len(self._tikwm_keys):
            return
        removed = self._tikwm_keys.pop(row)
        self._ts_save_tikwm_keys()
        self._ts_refresh_key_list()
        self.ts_write_log(f"🗑 Đã xóa key: {removed.get('key','')[:12]}...")

    def _ts_test_tikwm_keys(self):
        """Test tất cả keys bằng cách gọi TikWm API."""
        if not self._tikwm_keys:
            self.ts_write_log("⚠️ Chưa có key nào để test.")
            return
        self.ts_write_log(f"🔍 Đang test {len(self._tikwm_keys)} key(s)...")

        import threading
        def _do_test(keys_list):
            import urllib.request, urllib.parse, json as _json
            TEST_URL = "https://www.tiktok.com/@tiktok/video/7106594312292453675"
            for k_dict in keys_list:
                key = k_dict['key']
                try:
                    params = urllib.parse.urlencode({'url': TEST_URL, 'hd': '1', 'api_key': key}).encode()
                    req = urllib.request.Request(
                        'https://www.tikwm.com/api/', data=params, method='POST',
                        headers={'User-Agent': 'Mozilla/5.0',
                                 'Content-Type': 'application/x-www-form-urlencoded'})
                    with urllib.request.urlopen(req, timeout=8) as resp:
                        data = _json.loads(resp.read())
                    code = data.get('code', -1)
                    if code == 0:
                        k_dict['status'] = 'ok'
                        plan_info = ""
                        # Try to detect plan from response headers or quota
                        msg = f"✅ Key {key[:8]}...: Hợp lệ (Paid)"
                    else:
                        k_dict['status'] = 'fail'
                        msg = f"❌ Key {key[:8]}...: {data.get('msg', 'Lỗi')}"
                except Exception as e:
                    k_dict['status'] = 'fail'
                    msg = f"❌ Key {key[:8]}...: {e}"
                from PyQt6.QtCore import QMetaObject, Qt
                QMetaObject.invokeMethod(self, '_ts_on_key_test_result',
                    Qt.ConnectionType.QueuedConnection,
                    Q_ARG(str, msg))
            QMetaObject.invokeMethod(self, '_ts_on_keys_test_done',
                Qt.ConnectionType.QueuedConnection)

        t = threading.Thread(target=_do_test, args=(self._tikwm_keys,), daemon=True)
        t.start()

    from PyQt6.QtCore import pyqtSlot

    @pyqtSlot(str)
    def _ts_on_key_test_result(self, msg: str):
        self.ts_write_log(msg)

    @pyqtSlot()
    def _ts_on_keys_test_done(self):
        self._ts_save_tikwm_keys()
        self._ts_refresh_key_list()
        active = sum(1 for k in self._tikwm_keys if k.get('status') == 'ok')
        self.ts_write_log(f"🔑 Test xong! {active}/{len(self._tikwm_keys)} key hoạt động.")

    def _ts_get_active_key(self):
        """
        Lấy key tiếp theo trong vòng xoay (round-robin).
        Chỉ dùng key có status='ok'.
        Trả về None nếu không có key nào hợp lệ.
        """
        keys = getattr(self, '_tikwm_keys', [])
        active = [k['key'] for k in keys if k.get('status') == 'ok']
        if not active:
            # Fallback: try any key even if not tested
            all_keys = [k['key'] for k in keys]
            if all_keys:
                idx = getattr(self, '_ts_key_rr_idx', 0) % len(all_keys)
                self._ts_key_rr_idx = idx + 1
                return all_keys[idx]
            return None
        idx = getattr(self, '_ts_key_rr_idx', 0) % len(active)
        self._ts_key_rr_idx = idx + 1
        return active[idx]

    def ts_write_log(self, text):
        self.ts_txt_logs.append(text)
        self.ts_txt_logs.ensureCursorVisible()



    def ts_action_open_chrome_spy(self):
        self.ts_write_log("[Chrome] Đang khởi động Chrome Spy với Profile & Cổng 9222...")
        if is_port_in_use(CDP_PORT):
            if is_chrome_cdp_active(CDP_PORT):
                self.ts_write_log("🟢 [Chrome] Chrome Spy đã chạy sẵn trên cổng 9222.")
                QMessageBox.information(self, "Chrome Spy", "Chrome Spy đã chạy sẵn trên cổng 9222.\nBạn có thể bắt đầu cào sản phẩm.")
                self.ts_check_chrome_status()
                return
            else:
                self.ts_write_log("⚠️ Cổng 9222 đang bận nhưng không phản hồi CDP. Hãy đóng đúng cửa sổ Chrome Spy cũ hoặc xử lý cổng này; tool không tắt Chrome/Google Flow của ứng dụng khác.")
                return

        chrome_path = find_chrome_path()
        if not chrome_path:
            self.ts_write_log("❌ Không tìm thấy Google Chrome cài đặt trên máy.")
            QMessageBox.critical(self, "Lỗi Chrome Spy", "Không tìm thấy đường dẫn cài đặt Google Chrome trên hệ thống của bạn!")
            return

        cmd = [
            chrome_path,
            f"--user-data-dir={PROFILE_DIR.resolve()}",
            f"--remote-debugging-port={CDP_PORT}",
            "--remote-allow-origins=*",
            "--no-first-run",
            "--no-default-browser-check",
            "--disable-default-apps",
            "--disable-blink-features=AutomationControlled",
            "https://www.tiktok.com"
        ]
        try:
            creation_flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
            subprocess.Popen(cmd, creationflags=creation_flags)
            self.ts_write_log("🟢 Khởi động Chrome Spy thành công.")
            QMessageBox.information(self, "Chrome Spy", "Đã khởi động Chrome thành công.\nVui lòng sử dụng cửa sổ Chrome mới mở này đăng nhập TikTok (nếu cần) và giữ Chrome luôn mở trong lúc cào.")
        except Exception as e:
            self.ts_write_log(f"❌ Lỗi khởi động Chrome: {e}")
            QMessageBox.critical(self, "Lỗi Chrome Spy", f"Không thể khởi động Chrome:\n{e}")
        self.ts_check_chrome_status()

    def ts_action_download_voice_all(self):
        """Tải voice MP3 cho tất cả sản phẩm chưa có voice — có kiểm soát luồng."""
        prod_json_path = DOWNLOADS_DIR / "products.json"
        if not prod_json_path.exists():
            self.ts_write_log("⚠️ Chưa có dữ liệu sản phẩm nào.")
            return

        products = json.loads(prod_json_path.read_text(encoding="utf-8"))

        queue = []
        skipped = 0
        for p in products:
            pid = p.get("product_id", "")
            voices = list(p.get("voices", []))
            vdir = DOWNLOADS_DIR / "voices" / pid
            if vdir.exists():
                found = [str(f) for f in vdir.glob("*.mp3")]
                voices = list(set(voices + found))
            if voices:
                continue

            related = p.get("related_videos", [])
            if not related:
                skipped += 1
                continue
            vid_url = related[0] if isinstance(related[0], str) else related[0].get("url", "")
            if not vid_url:
                skipped += 1
                continue
            queue.append((p, vid_url))

        if not queue:
            self.ts_write_log("✅ Tất cả sản phẩm có video đều đã có voice MP3!")
            if skipped:
                self.ts_write_log(f"ℹ️ {skipped} sản phẩm bỏ qua (chưa có video liên quan).")
            return

        # ── Phát hiện chế độ Free / Paid dựa vào key pool ──
        active_keys = [k['key'] for k in getattr(self, '_tikwm_keys', []) if k.get('status') == 'ok']
        any_key = self._ts_get_active_key()  # round-robin getter
        has_paid = bool(active_keys)

        max_threads = self.ts_spin_threads.value() if hasattr(self, "ts_spin_threads") else 1
        if not has_paid:
            max_threads = 1
            delay_ms    = 1200
            self.ts_write_log(
                f"ℹ️ Chế độ FREE (không có key hợp lệ): 1 luồng, delay 1.2s. "
                f"Thêm key TikWm đã test vào bảng quản lý để tăng tốc."
            )
        else:
            # Trial plan: 600req/min = 10 req/s per key
            max_threads = min(self.ts_spin_threads.value(), 10 * len(active_keys))
            delay_ms    = 100  # 10 req/s per key
            self.ts_write_log(
                f"✨ Chế độ PAID (có API Key): {max_threads} luồng, delay {delay_ms}ms/slot."
            )

        total = len(queue)
        self.ts_write_log(f"🎵 Bắt đầu tải voice: {total} sản phẩm, {max_threads} luồng, {skipped} bỏ qua.")

        if not hasattr(self, "_ts_voice_workers"):
            self._ts_voice_workers = []

        self._ts_voice_stop = False
        self._ts_voice_queue = list(queue)
        self._ts_voice_active = 0
        self._ts_voice_done = 0
        self._ts_voice_total = total
        self._ts_voice_max = max_threads
        self._ts_voice_delay = delay_ms
        # NOTE: key is obtained per-worker via _ts_get_active_key() in dispatch_next
        self._ts_voice_json = prod_json_path

        if hasattr(self, "ts_btn_stop"):
            self.ts_btn_stop.setEnabled(True)
            try:
                self.ts_btn_stop.clicked.disconnect()
            except:
                pass
            self.ts_btn_stop.clicked.connect(self._ts_voice_stop_all)

        self._ts_voice_dispatch_next()

    def _ts_voice_stop_all(self):
        self._ts_voice_stop = True
        self.ts_write_log("🛑 Đang dừng tải voice... (các luồng đang chạy sẽ hoàn thành trước khi dừng)")
        if hasattr(self, "ts_btn_stop"):
            self.ts_btn_stop.setEnabled(False)

    def _ts_voice_dispatch_next(self):
        if self._ts_voice_stop:
            return

        while (self._ts_voice_active < self._ts_voice_max
               and self._ts_voice_queue):
            prod, vid_url = self._ts_voice_queue.pop(0)
            pid = prod.get("product_id", "unknown")
            folder_name = prod.get("folder", "Chưa phân loại")
            safe_title = clean_filename(prod.get("title", "product"))
            if folder_name and folder_name != "Chưa phân loại":
                out_dir = DOWNLOADS_DIR / folder_name / f"{pid}_{safe_title}" / "voices"
            else:
                out_dir = DOWNLOADS_DIR / "voices" / pid
            out_dir.mkdir(parents=True, exist_ok=True)

            # Get next key in round-robin (per-worker)
            per_worker_key = self._ts_get_active_key()
            worker = VoiceDownloadWorker(vid_url, str(out_dir), per_worker_key)
            self._ts_voice_workers.append(worker)
            self._ts_voice_active += 1

            idx = self._ts_voice_done + self._ts_voice_active
            self.ts_write_log(
                f"  🎵 [{idx}/{self._ts_voice_total}] {prod.get('title','')[:45]}..."
            )

            def _make_cb(p=prod, w=worker):
                def on_done(ok, fpath):
                    self._ts_voice_active = max(0, self._ts_voice_active - 1)
                    self._ts_voice_done += 1
                    if ok and fpath:
                        try:
                            prods = json.loads(self._ts_voice_json.read_text(encoding='utf-8'))
                            _pid = p.get('product_id', '')
                            for _p in prods:
                                if _p.get('product_id') == _pid:
                                    vl = _p.setdefault('voices', [])
                                    if fpath not in vl:
                                        vl.append(fpath)
                                    break
                            self._ts_voice_json.write_text(
                                json.dumps(prods, ensure_ascii=False, indent=2), encoding='utf-8'
                            )
                        except Exception as ex:
                            self.ts_write_log(f"⚠️ Lưu voice path lỗi: {ex}")
                        self.ts_write_log(
                            f"  ✅ [{self._ts_voice_done}/{self._ts_voice_total}] "
                            f"{p.get('title','')[:30]} → {Path(fpath).name}"
                        )
                        self.ts_refresh_products_table()
                    else:
                        self.ts_write_log(
                            f"  ❌ [{self._ts_voice_done}/{self._ts_voice_total}] "
                            f"{p.get('title','')[:30]}: {fpath}"
                        )
                    if w in self._ts_voice_workers:
                        self._ts_voice_workers.remove(w)
                    if self._ts_voice_queue and not self._ts_voice_stop:
                        QTimer.singleShot(self._ts_voice_delay, self._ts_voice_dispatch_next)
                    elif not self._ts_voice_queue and self._ts_voice_active == 0:
                        self.ts_write_log(
                            f"✅ Hoàn thành tải voice! "
                            f"{self._ts_voice_done}/{self._ts_voice_total} sản phẩm xử lý."
                        )
                        if hasattr(self, "ts_btn_stop"):
                            self.ts_btn_stop.setEnabled(False)
                return on_done

            worker.log_signal.connect(self.ts_write_log)
            worker.finished_signal.connect(_make_cb())
            worker.start()

    # ───────────────────────────────────────────────
    # HELPER: Parse dòng dạng "[Link SP] | [V1];[V2]"
    # ───────────────────────────────────────────────
    @staticmethod
    def _ts_parse_pipe_lines(text):
        """
        Hỗ trợ 2 định dạng:
          1) [Link SP] | [Video1];[Video2];...
          2) Chỉ là URL thông thường (1 URL mỗi dòng)
        Trả về: list of dict {product_url, related_videos}
        """
        results = []
        for raw_line in text.strip().splitlines():
            line = raw_line.strip()
            if not line:
                continue
            if '|' in line:
                parts = line.split('|', 1)
                prod_url = parts[0].strip()
                vid_part = parts[1].strip() if len(parts) > 1 else ''
                videos = [v.strip() for v in vid_part.split(';') if v.strip().startswith('http')]
                if prod_url.startswith('http'):
                    results.append({'product_url': prod_url, 'related_videos': videos})
            elif line.startswith('http'):
                results.append({'product_url': line, 'related_videos': []})
        return results

    def ts_parse_and_save_products(self, parsed_lines):
        """
        Nhận list từ _ts_parse_pipe_lines, merge vào products.json.
        - Sản phẩm đã có data: giữ nguyên, chỉ cập nhật related_videos nếu chưa có
        - Sản phẩm chưa có voice và có video: tự thiếu tải voice
        """
        prod_json = DOWNLOADS_DIR / "products.json"
        DOWNLOADS_DIR.mkdir(parents=True, exist_ok=True)

        if not hasattr(self, '_ts_voice_workers'):
            self._ts_voice_workers = []

        existing = []
        if prod_json.exists():
            try:
                existing = json.loads(prod_json.read_text(encoding='utf-8'))
            except Exception:
                existing = []

        existing_by_url = {p.get('product_url', ''): p for p in existing}
        api_key = getattr(self, 'tikwm_api_key', None)
        new_count = 0
        voice_queued = 0

        # Lấy tên thư mục phân loại hiện tại từ combo box
        current_folder = "Chưa phân loại"
        if hasattr(self, "ts_combo_folder") and self.ts_combo_folder.count() > 0:
            txt = self.ts_combo_folder.currentText()
            if txt not in ("📁 Tất cả thư mục", "📁 Chưa phân loại"):
                current_folder = txt.replace("📁 ", "").strip()

        for entry in parsed_lines:
            purl = entry['product_url']
            videos = entry['related_videos']

            if purl in existing_by_url:
                prod = existing_by_url[purl]
                prod["folder"] = current_folder
                # Cập nhập related_videos nếu chưa có
                if videos and not prod.get('related_videos'):
                    prod['related_videos'] = videos
                # Tự tải voice nếu chưa có và có video
                if not prod.get('voices') and (videos or prod.get('related_videos')):
                    vlist = videos or prod.get('related_videos', [])
                    if vlist:
                        vid_url = vlist[0]
                        pid = prod.get('product_id') or uuid.uuid4().hex[:8]
                        out_dir = DOWNLOADS_DIR / 'voices' / pid
                        out_dir.mkdir(parents=True, exist_ok=True)
                        self.ts_write_log(f"🎵 Tự tải voice cho: {prod.get('title', purl[:40])}...")
                        worker = VoiceDownloadWorker(vid_url, str(out_dir), api_key)
                        self._ts_voice_workers.append(worker)
                        def _on_voice_done(ok, fpath, _prod=prod, _pid=pid, _worker=worker):
                            if _worker in self._ts_voice_workers:
                                self._ts_voice_workers.remove(_worker)
                            if ok and fpath:
                                _prod.setdefault('voices', []).append(fpath)
                                prod_json.write_text(json.dumps(existing, ensure_ascii=False, indent=2), encoding='utf-8')
                                self.ts_write_log(f"✅ Voice: {Path(fpath).name} → [{_prod.get('title','')[:30]}]")
                                self.ts_refresh_products_table()
                            else:
                                self.ts_write_log(f"❌ Lỗi tải voice: {fpath}")
                        worker.finished_signal.connect(_on_voice_done)
                        worker.start()
                        voice_queued += 1
            else:
                # Sản phẩm mới
                prod = {
                    'product_url': purl,
                    'product_id': uuid.uuid4().hex[:8],
                    'title': purl.split('/')[-1][:60] or purl[:60],
                    'related_videos': videos,
                    'voices': [],
                    'images': [],
                    'status': 'imported',
                    'folder': current_folder,
                }
                existing.append(prod)
                existing_by_url[purl] = prod
                new_count += 1

                # Tự tải voice nếu có video
                if videos:
                    pid = prod['product_id']
                    out_dir = DOWNLOADS_DIR / 'voices' / pid
                    out_dir.mkdir(parents=True, exist_ok=True)
                    self.ts_write_log(f"🎵 Tải voice mới: {prod['title'][:40]}...")
                    worker = VoiceDownloadWorker(videos[0], str(out_dir), api_key)
                    self._ts_voice_workers.append(worker)
                    def _on_voice_new(ok, fpath, _prod=prod, _worker=worker):
                        if _worker in self._ts_voice_workers:
                            self._ts_voice_workers.remove(_worker)
                        if ok and fpath:
                            _prod.setdefault('voices', []).append(fpath)
                            prod_json.write_text(json.dumps(existing, ensure_ascii=False, indent=2), encoding='utf-8')
                            self.ts_write_log(f"✅ Voice: {Path(fpath).name} → [{_prod.get('title','')[:30]}]")
                            self.ts_refresh_products_table()
                        else:
                            self.ts_write_log(f"❌ Lỗi tải voice: {fpath}")
                    worker.finished_signal.connect(_on_voice_new)
                    worker.start()
                    voice_queued += 1

        prod_json.write_text(json.dumps(existing, ensure_ascii=False, indent=2), encoding='utf-8')
        self.ts_write_log(f"✅ Đã lưu {len(existing)} sản phẩm (mới: {new_count}, đang tải voice: {voice_queued} sản phẩm).")
        self.ts_refresh_products_table()

    def ts_action_import_file(self):
        file_path, _ = QFileDialog.getOpenFileName(
            self, "Chọn file chứa Links", "",
            "Supported Files (*.txt *.csv *.xlsx *.xls);;Text Files (*.txt);;CSV Files (*.csv);;All Files (*)"
        )
        if not file_path:
            return

        from PyQt6.QtWidgets import QInputDialog, QLineEdit
        default_folder_name = os.path.splitext(os.path.basename(file_path))[0]
        folder_name, ok = QInputDialog.getText(
            self, "Phân loại thư mục", 
            "Nhập tên thư mục phân loại cho các sản phẩm từ file này:",
            QLineEdit.EchoMode.Normal, default_folder_name
        )
        if not ok or not folder_name.strip():
            folder_name = "Chưa phân loại"
        else:
            folder_name = folder_name.strip()

        if folder_name != "Chưa phân loại":
            idx = self.ts_combo_folder.findText(f"📁 {folder_name}")
            if idx < 0:
                self.ts_combo_folder.blockSignals(True)
                self.ts_combo_folder.addItem(f"📁 {folder_name}")
                self.ts_combo_folder.blockSignals(False)
                idx = self.ts_combo_folder.findText(f"📁 {folder_name}")
            if idx >= 0:
                self.ts_combo_folder.setCurrentIndex(idx)
        else:
            self.ts_combo_folder.setCurrentIndex(0)

        self.ts_lbl_file_path.setText(os.path.basename(file_path))
        try:
            ext = os.path.splitext(file_path)[1].lower()
            if ext in ['.xlsx', '.xls']:
                self.ts_write_log(f"📁 Đang đọc Excel: {file_path}...")
                import openpyxl
                wb = openpyxl.load_workbook(file_path, data_only=True, read_only=True)
                sheet = wb.active
                rows = list(sheet.iter_rows(values_only=True))
                header_row = rows[0] if rows else None
                if not header_row:
                    self.ts_write_log("⚠️ File Excel trống!")
                    return
                headers_lower = [str(h).lower().strip() if h else '' for h in header_row]

                is_tiktokshop = any(
                    any(k in h for k in ['tên sản phẩm', 'liên kết sản phẩm', 'video liên quan', 'product name', 'product link', 'related videos'])
                    for h in headers_lower
                )

                if is_tiktokshop:
                    self.ts_write_log("🛒 Phát hiện file TiktokShop — Đang parse sản phẩm...")
                    col_map = {}
                    for idx, h in enumerate(headers_lower):
                        if any(k in h for k in ['hình ảnh', 'hinh anh', 'product image']) and 'image' not in col_map:
                            col_map['image'] = idx
                        elif any(k in h for k in ['tên sản phẩm', 'ten san pham', 'product name']) and 'title' not in col_map:
                            col_map['title'] = idx
                        elif any(k in h for k in ['liên kết sản phẩm', 'product link']) and 'product_url' not in col_map:
                            col_map['product_url'] = idx
                        elif any(k in h for k in ['video liên quan', 'related videos']) and 'số lượng' not in h and 'count' not in h and 'videos' not in col_map:
                            col_map['videos'] = idx
                        elif any(k in h for k in ['id sản phẩm', 'product id']) and 'product_id' not in col_map:
                            col_map['product_id'] = idx
                        elif any(k in h for k in ['thuộc danh mục', 'danh muc', 'category belonging']) and 'category' not in col_map:
                            col_map['category'] = idx

                    self.ts_write_log(f"  📋 Cột: {col_map}")
                    parsed_lines = []
                    for row in rows[1:]:
                        if not row or not any(row):
                            continue
                        def _get(key, _r=row):
                            i = col_map.get(key, -1)
                            if i < 0 or i >= len(_r): return None
                            v = _r[i]
                            return str(v).strip() if v else None
                        title = _get('title') or ''
                        product_url = _get('product_url') or ''
                        product_id = _get('product_id') or ''
                        category = _get('category') or ''
                        image_url = _get('image') or ''
                        videos_raw = _get('videos') or ''
                        if not title:
                            continue
                        related_videos = [v.strip() for v in videos_raw.split('\n') if v.strip().startswith('http')]
                        parsed_lines.append({
                            'product_url': product_url,
                            'related_videos': related_videos,
                            '_meta': {'title': title, 'product_id': product_id, 'category': category, 'image_url': image_url},
                        })

                    if parsed_lines:
                        self.ts_write_log(f"✅ Parse được {len(parsed_lines)} sản phẩm từ file TiktokShop.")
                        # Merge meta into existing
                        prod_json = DOWNLOADS_DIR / 'products.json'
                        DOWNLOADS_DIR.mkdir(parents=True, exist_ok=True)
                        existing = []
                        if prod_json.exists():
                            try: existing = json.loads(prod_json.read_text(encoding='utf-8'))
                            except: pass
                        existing_by_url = {p.get('product_url', ''): p for p in existing}
                        for entry in parsed_lines:
                            purl = entry['product_url']
                            meta = entry.get('_meta', {})
                            if purl in existing_by_url:
                                p = existing_by_url[purl]
                                p["folder"] = folder_name
                                for k, v in meta.items():
                                    if v and not p.get(k): p[k] = v
                                if entry['related_videos'] and not p.get('related_videos'):
                                    p['related_videos'] = entry['related_videos']
                            else:
                                new_p = {'product_url': purl, **meta,
                                         'related_videos': entry['related_videos'],
                                         'voices': [], 'images': [], 'status': 'imported',
                                         'folder': folder_name}
                                existing.append(new_p)
                                existing_by_url[purl] = new_p
                        prod_json.write_text(json.dumps(existing, ensure_ascii=False, indent=2), encoding='utf-8')
                        self.ts_refresh_products_table()
                        self.ts_write_log(f"📂 Đã lưu {len(existing)} sản phẩm. Nhấn 'Tải Voice Tất Cả' để tải MP3.")
                        # Also display in URL box
                        url_box = '\n'.join(
                            f"{e['product_url']} | {';'.join(e['related_videos'])}"
                            if e['related_videos'] else e['product_url']
                            for e in parsed_lines if e['product_url'].startswith('http')
                        )
                        self.ts_txt_urls.setPlainText(url_box)
                    else:
                        self.ts_write_log("⚠️ Không parse được sản phẩm nào từ file TiktokShop.")
                    return

                else:
                    # Generic Excel: scan all cells for http
                    all_text_lines = []
                    for row in rows[1:]:
                        if not row: continue
                        for cell in row:
                            if cell:
                                val = str(cell).strip()
                                if val.startswith('http'):
                                    all_text_lines.append(val)
                                    break
                    if all_text_lines:
                        self.ts_txt_urls.setPlainText('\n'.join(all_text_lines))
                        self.ts_write_log(f"✅ Tìm thấy {len(all_text_lines)} URL từ Excel.")
                    else:
                        self.ts_write_log("⚠️ Không tìm thấy URL nào trong file Excel.")
                    return

            else:  # txt / csv
                self.ts_write_log(f"📁 Đang đọc file: {file_path}...")
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    raw_text = f.read()
                self.ts_txt_urls.setPlainText(raw_text.strip())
                self.ts_write_log("✅ Đã điền nội dung file vào ô Links.")

        except Exception as e:
            self.ts_write_log(f"❌ Lỗi đọc file: {e}")
            import traceback
            self.ts_write_log(traceback.format_exc()[-500:])


    def ts_action_download_voice_selected(self):
        """Tải voice MP3 cho sản phẩm đang chọn trong bảng."""
        row = self.ts_table_products.currentRow()
        if row < 0:
            QMessageBox.warning(self, "Chưa chọn", "Vui lòng chọn một sản phẩm trong danh sách!")
            return

        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            return
        products = json.loads(prod_json.read_text(encoding="utf-8"))
        if row >= len(products):
            return
        prod = products[row]

        # Lấy URL video: ưu tiên URL nhập thủ công, sau đó lấy video liên quan
        manual_url = self.ts_edit_voice_url.text().strip()
        if manual_url and manual_url.startswith("http"):
            video_url = manual_url
        else:
            related = prod.get("related_videos", [])
            if not related:
                QMessageBox.information(self, "Không có video",
                    "Sản phẩm này chưa có video liên quan. Hãy dán link video TikTok vào ô bên cạnh nút Tải Voice!")
                return
            video_url = related[0] if isinstance(related[0], str) else related[0].get("url", "")

        output_dir = DOWNLOADS_DIR / "voices" / prod.get("product_id", f"row_{row}")
        output_dir.mkdir(parents=True, exist_ok=True)

        api_key = getattr(self, "tikwm_api_key", None)
        if not hasattr(self, "_ts_voice_workers"):
            self._ts_voice_workers = []
        worker = VoiceDownloadWorker(video_url, str(output_dir), api_key)
        self._ts_voice_workers.append(worker)  # prevent GC

        def on_voice_done(ok, fpath, _prod=prod, _worker=worker):
            if ok and fpath:
                # Lưu path MP3 vào products.json
                prod_json = DOWNLOADS_DIR / "products.json"
                try:
                    prods = json.loads(prod_json.read_text(encoding='utf-8'))
                    pid = _prod.get('product_id', '')
                    for p in prods:
                        if p.get('product_id') == pid:
                            vlist = p.setdefault('voices', [])
                            if fpath not in vlist:
                                vlist.append(fpath)
                            break
                    prod_json.write_text(json.dumps(prods, ensure_ascii=False, indent=2), encoding='utf-8')
                except Exception as ex:
                    self.ts_write_log(f"⚠️ Không lưu được voice path: {ex}")
                self.ts_write_log(f"✅ Voice [{_prod.get('title','')[:30]}]: {Path(fpath).name}")
                self.ts_refresh_products_table()
            else:
                self.ts_write_log(f"❌ Lỗi tải voice [{_prod.get('title','')[:30]}]: {fpath}")
            # Remove from active list
            if _worker in self._ts_voice_workers:
                self._ts_voice_workers.remove(_worker)

        worker.log_signal.connect(self.ts_write_log)
        worker.finished_signal.connect(on_voice_done)
        worker.start()
        self.ts_write_log(f"🎵 Đang tải voice: {prod.get('title','')[:50]}...")


    def ts_action_add_to_current_project(self):
        """Thêm sản phẩm đang chọn vào dự án đang mở hiện tại."""
        row = self.ts_table_products.currentRow()
        if row < 0:
            QMessageBox.warning(self, "Chưa chọn", "Vui lòng chọn một sản phẩm trong danh sách!")
            return

        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            return
        products = json.loads(prod_json.read_text(encoding="utf-8"))
        if row >= len(products):
            return
        prod = products[row]

        # Lấy project đang mở
        current_pid = getattr(self.proj_mgr, "current_project_id", None)
        if not current_pid:
            QMessageBox.warning(self, "Chưa mở dự án",
                "Bạn chưa mở dự án nào. Hãy chọn hoặc tạo một dự án trước!")
            return

        # Mở TiktokShopSelectDialog đã lọc theo sản phẩm này
        dlg = TiktokShopSelectDialog(self)
        dlg.load_crawled_products()
        # Tìm và chọn sản phẩm theo product_id
        pid = prod.get("product_id", "")
        for r in range(dlg.table.rowCount()):
            item = dlg.table.item(r, 0)
            if item and item.text() == pid:
                dlg.table.selectRow(r)
                break
        if dlg.exec() == QDialog.DialogCode.Accepted:
            sel_img   = dlg.selected_image_path
            sel_title = dlg.selected_title
            sel_desc  = dlg.selected_description
            sel_voices = dlg.selected_voices
            if sel_img:
                self._open_tiktokshop_product_in_project(sel_img, sel_title, sel_desc, sel_voices)


    def _open_tiktokshop_product_in_project(self, image_path: str, title: str, description: str, voice_paths: list):
        """
        Tạo StoryProject từ sản phẩm TiktokShop đã chọn và thêm vào Storyboard.
        - image_path : ảnh thumbnail/collage sản phẩm
        - title      : tên sản phẩm (dùng làm folder + card name)
        - description: mô tả / yêu cầu riêng
        - voice_paths: danh sách file MP3 voice đã tải
        """
        if not image_path or not Path(image_path).exists():
            QMessageBox.warning(self, "Lỗi", f"Ảnh sản phẩm không tồn tại:\n{image_path}")
            return

        # Bật Storyboard tab nếu chưa mở
        try:
            self.stacked_widget.setCurrentIndex(8)   # index 8 = Storyboard panel
        except Exception:
            pass

        # ── Tạo tên sạch từ tiêu đề sản phẩm ──────────────────────────────
        # Lấy tối đa 8 từ đầu, bỏ ký tự đặc biệt không hợp lệ trong tên thư mục
        def _clean_product_name(raw: str, max_words: int = 8) -> str:
            import re as _re
            if not raw or not raw.strip():
                return ""
            # Lấy tối đa max_words từ đầu
            words = raw.strip().split()[:max_words]
            short = " ".join(words)
            # Bỏ ký tự không hợp lệ trong tên file/thư mục
            safe = _re.sub(r'[\\/:*?"<>|]', '', short).strip().strip(" .")
            return safe if safe else ""

        clean_name = _clean_product_name(title, max_words=8)
        if not clean_name:
            # Fallback: dùng stem ảnh gốc (không phải collage) hoặc id ngắn
            img_stem = Path(image_path).stem
            if img_stem.startswith("collage_") or len(img_stem) < 4:
                clean_name = f"SP_{uuid.uuid4().hex[:6]}"
            else:
                clean_name = img_stem[:40].strip(" .")

        settings = self._sb_build_batch_settings()
        sp = StoryProject(
            product_image_path=image_path,
            name=clean_name,
            project_id=getattr(self.proj_mgr, "current_project_id", ""),
            product_info=description or title,
            num_scenes=settings.get("scene_count", 4),
            seconds_per_scene=settings.get("duration", 10),
            panels_per_storyboard=settings.get("panels_per_storyboard", 8),
            aspect=settings.get("aspect", "16:9"),
            aspect_label=settings.get("aspect_label", "Ngang (16:9)"),
            img_model=clean_model_name(settings.get("img_model", "gpt-image-2")),
            vid_model=settings.get("vid_model", "grok-imagine-video-1.5-preview"),
            llm_model=settings.get("llm_model", "gpt-4o"),
            img_size=settings.get("img_size", "1536x1024"),
            img_quality=settings.get("img_quality", "standard"),
            video_resolution=settings.get("video_resolution", "720p"),
            audio_val=settings.get("audio_val", "sound_effects_only"),
            system_prompt_override=settings.get("system_prompt", ""),
            clone_count=settings.get("clone_count", 1),
            mode="roleskill" if getattr(self, "_sb_roleskill_mode", False) else "storyboard",
            role_skill_file=self.sb_role_combo.currentData() if (getattr(self, "_sb_roleskill_mode", False) and hasattr(self, "sb_role_combo")) else ""
        )
        # Gán voice paths từ TiktokShop
        sp.voice_paths = [v for v in (voice_paths or []) if v and Path(v).exists()]

        idx = len(self._sb_cards)
        card = SBProductCard(idx, image_path, self, name=clean_name)
        card._story_project = sp
        card.edit_name.setText(sp.name)          # Hiển thị tên sản phẩm thật
        card.edit_req.setPlainText(sp.product_info)
        card.set_view_mode(self.sb_gallery_view)
        if self._sb_cards:
            self.sb_empty_lbl.setVisible(False)

        self._sb_cards.append(card)
        self.proj_mgr.story_projects.append(sp)
        self.proj_mgr.save_story_projects()
        self._sb_rearrange_grid()
        self._sb_log(f"+ Đã thêm sản phẩm TiktokShop: {sp.name} | {len(sp.voice_paths)} voice(s)")


    def ts_action_start_crawl(self):
        urls_text = self.ts_txt_urls.toPlainText().strip()
        if not urls_text:
            QMessageBox.warning(self, "Lỗi", "Vui lòng nhập danh sách links cần cào!")
            return

        # Lấy tất cả URL (hỗ trợ cả dạng có chứa | video)
        urls = [line.strip() for line in urls_text.splitlines()
                if line.strip() and line.strip().startswith('http')]

        if not urls:
            QMessageBox.warning(self, "Lỗi", "Không tìm thấy liên kết sản phẩm hợp lệ!")
            return

        if not is_port_in_use(CDP_PORT) or not is_chrome_cdp_active(CDP_PORT):
            QMessageBox.warning(self, "Chưa mở Chrome Spy", "Vui lòng bấm 'Mở Chrome Spy' và đăng nhập TikTok trước khi cào!")
            return

        self.ts_btn_start.setEnabled(False)
        self.ts_btn_stop.setEnabled(True)
        self.ts_progress_bar.setMaximum(len(urls))
        self.ts_progress_bar.setValue(0)

        # Xác định thư mục phân loại đích cho các sản phẩm cào mới
        current_folder = "Chưa phân loại"
        if hasattr(self, "ts_combo_folder") and self.ts_combo_folder.count() > 0:
            txt = self.ts_combo_folder.currentText()
            if txt not in ("📁 Tất cả thư mục", "📁 Chưa phân loại"):
                current_folder = txt.replace("📁 ", "").strip()

        self.ts_worker = CrawlWorker(urls, thread_count=self.ts_spin_threads.value())
        self.ts_worker.target_folder = current_folder
        self.ts_worker.log_signal.connect(self.ts_write_log)
        self.ts_worker.progress_signal.connect(self.ts_on_crawl_progress)
        self.ts_worker.product_done_signal.connect(self.ts_on_product_done)
        self.ts_worker.finished_signal.connect(self.ts_on_crawl_finished)
        self.ts_worker.start()

    def ts_action_stop_crawl(self):
        if self.ts_worker:
            self.ts_worker.stop()
            self.ts_write_log("🛑 Đang dừng cào (đợi các luồng hiện tại tắt)...")
            self.ts_btn_stop.setEnabled(False)

    def ts_on_crawl_progress(self, completed, total):
        self.ts_progress_bar.setValue(completed)

    def ts_on_product_done(self, product_data):
        self.ts_refresh_products_table()

    def ts_on_crawl_finished(self, success, failed):
        self.ts_btn_start.setEnabled(True)
        self.ts_btn_stop.setEnabled(False)
        self.ts_lbl_stats.setText(f"Đã cào: {success+failed}/{success+failed} | Thành công: {success} | Thất bại: {failed}")
        QMessageBox.information(self, "Hoàn thành", f"Hoàn thành crawl! Thành công: {success} | Thất bại: {failed}")

    def ts_refresh_products_table(self):
        prod_json = DOWNLOADS_DIR / "products.json"
        if not prod_json.exists():
            self.ts_table_products.setRowCount(0)
            return
        try:
            products = json.loads(prod_json.read_text(encoding="utf-8"))
            
            selected_folder = "📁 Tất cả thư mục"
            if hasattr(self, "ts_combo_folder") and self.ts_combo_folder.count() > 0:
                selected_folder = self.ts_combo_folder.currentText()
                
            filtered = []
            for prod in products:
                folder_name = prod.get("folder", "Chưa phân loại")
                if selected_folder == "📁 Tất cả thư mục":
                    filtered.append(prod)
                elif selected_folder == "📁 Chưa phân loại" and folder_name == "Chưa phân loại":
                    filtered.append(prod)
                elif selected_folder == f"📁 {folder_name}":
                    filtered.append(prod)
                    
            self.products = filtered
            
            self.ts_table_products.setRowCount(len(filtered))
            for idx, prod in enumerate(filtered):
                self.ts_table_products.setItem(idx, 0, QTableWidgetItem(prod.get("product_id", "")))
                # Title + category
                title_str = prod.get("title", "")
                cat_str = prod.get("category", "")
                if cat_str:
                    title_str = f"{title_str}  [{cat_str.split('->')[-1].strip()}]"
                self.ts_table_products.setItem(idx, 1, QTableWidgetItem(title_str))
                self.ts_table_products.setItem(idx, 2, QTableWidgetItem(prod.get("price", "")))
                # Seller / product_url snippet
                seller = prod.get("seller", "") or prod.get("product_url", "")[-50:]
                self.ts_table_products.setItem(idx, 3, QTableWidgetItem(seller))
                # Status + related_videos count
                n_vid = len(prod.get("related_videos", []))
                status_str = prod.get("status", "OK")
                if n_vid:
                    status_str += f"  | 🎥{n_vid} video"
                status_item = QTableWidgetItem(status_str)
                self.ts_table_products.setItem(idx, 4, status_item)
                # Voice MP3
                voices = prod.get("voices", [])
                # Also scan voice dir
                pid = prod.get("product_id", "")
                voice_dirs = [DOWNLOADS_DIR / "voices" / pid]
                folder_name = prod.get("folder", "Chưa phân loại")
                if folder_name and folder_name != "Chưa phân loại":
                    safe_title = clean_filename(prod.get("title", "product"))
                    voice_dirs.append(DOWNLOADS_DIR / folder_name / f"{pid}_{safe_title}" / "voices")
                
                for voice_dir in voice_dirs:
                    if voice_dir.exists():
                        found = [str(f) for f in voice_dir.glob("*.mp3")]
                        if found:
                            for f in found:
                                if f not in voices:
                                    voices.append(f)
                prod["voices"] = voices  # update in memory
                
                voice_item = QTableWidgetItem(f"✅ {len(voices)} MP3" if voices else "—")
                voice_item.setForeground(QColor("#06b6d4") if voices else QColor("#64748b"))
                voice_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                self.ts_table_products.setItem(idx, 5, voice_item)
        except Exception as e:
            self.ts_write_log(f"⚠️ Lỗi cập nhật bảng sản phẩm: {e}")


    def ts_refresh_folder_list(self):
        current_folder = self.ts_combo_folder.currentText() if hasattr(self, "ts_combo_folder") and self.ts_combo_folder.count() > 0 else "📁 Tất cả thư mục"
        
        folders = set()
        prod_json = DOWNLOADS_DIR / "products.json"
        if prod_json.exists():
            try:
                products = json.loads(prod_json.read_text(encoding="utf-8"))
                for p in products:
                    f = p.get("folder", "Chưa phân loại")
                    if f:
                        folders.add(f)
            except Exception:
                pass
                
        folder_list = sorted(list(folders))
        if "Chưa phân loại" in folder_list:
            folder_list.remove("Chưa phân loại")
            
        display_list = ["📁 Tất cả thư mục", "📁 Chưa phân loại"] + [f"📁 {f}" for f in folder_list]
        
        self.ts_combo_folder.blockSignals(True)
        self.ts_combo_folder.clear()
        self.ts_combo_folder.addItems(display_list)
        
        idx = self.ts_combo_folder.findText(current_folder)
        if idx >= 0:
            self.ts_combo_folder.setCurrentIndex(idx)
        else:
            self.ts_combo_folder.setCurrentIndex(0)
        self.ts_combo_folder.blockSignals(False)

    def ts_action_move_folder(self):
        selected_rows = [index.row() for index in self.ts_table_products.selectionModel().selectedRows()]
        if not selected_rows:
            QMessageBox.warning(self, "Chưa chọn", "Vui lòng chọn các sản phẩm cần phân loại!")
            return
            
        folders = set()
        prod_json = DOWNLOADS_DIR / "products.json"
        if prod_json.exists():
            try:
                products = json.loads(prod_json.read_text(encoding="utf-8"))
                for p in products:
                    f = p.get("folder", "Chưa phân loại")
                    if f:
                        folders.add(f)
            except Exception:
                pass
                
        folder_list = sorted(list(folders))
        if "Chưa phân loại" in folder_list:
            folder_list.remove("Chưa phân loại")
        folder_list = ["Chưa phân loại"] + folder_list + ["➕ Tạo thư mục mới..."]
        
        from PyQt6.QtWidgets import QInputDialog
        item, ok = QInputDialog.getItem(self, "Phân loại sản phẩm", "Chọn thư mục lưu trữ:", folder_list, 0, False)
        if not ok:
            return
            
        target_folder = item
        if item == "➕ Tạo thư mục mới...":
            new_name, ok = QInputDialog.getText(self, "Thư mục mới", "Nhập tên thư mục phân loại mới:")
            if not ok or not new_name.strip():
                return
            target_folder = new_name.strip()
            
        if prod_json.exists():
            try:
                products = json.loads(prod_json.read_text(encoding="utf-8"))
                selected_pids = [self.ts_table_products.item(r, 0).text() for r in selected_rows if self.ts_table_products.item(r, 0)]
                
                moved_count = 0
                for p in products:
                    if p.get("product_id") in selected_pids:
                        old_folder = p.get("folder", "Chưa phân loại")
                        p["folder"] = target_folder
                        
                        safe_title = clean_filename(p.get("title", "product"))
                        pid = p.get("product_id")
                        
                        if old_folder and old_folder != "Chưa phân loại":
                            old_dir = DOWNLOADS_DIR / old_folder / f"{pid}_{safe_title}"
                        else:
                            old_dir = DOWNLOADS_DIR / f"{pid}_{safe_title}"
                            
                        if target_folder and target_folder != "Chưa phân loại":
                            new_dir = DOWNLOADS_DIR / target_folder / f"{pid}_{safe_title}"
                        else:
                            new_dir = DOWNLOADS_DIR / f"{pid}_{safe_title}"
                            
                        if old_dir.exists() and old_dir.resolve() != new_dir.resolve():
                            new_dir.parent.mkdir(parents=True, exist_ok=True)
                            try:
                                import shutil
                                shutil.move(str(old_dir), str(new_dir))
                                if p.get("local_images"):
                                    p["local_images"] = [x.replace(str(old_dir), str(new_dir)) for x in p["local_images"]]
                                if p.get("voices"):
                                    p["voices"] = [x.replace(str(old_dir), str(new_dir)) for x in p["voices"]]
                            except Exception as ex:
                                self.ts_write_log(f"⚠️ Không thể di chuyển thư mục vật lý: {ex}")
                        moved_count += 1
                        
                prod_json.write_text(json.dumps(products, ensure_ascii=False, indent=2), encoding="utf-8")
                self.ts_refresh_folder_list()
                self.ts_refresh_products_table()
                self.ts_write_log(f"📁 Đã chuyển {moved_count} sản phẩm vào thư mục: {target_folder}")
            except Exception as e:
                QMessageBox.critical(self, "Lỗi", f"Không thể lưu phân loại: {e}")

    def ts_open_product_folder(self):
        row = self.ts_table_products.currentRow()
        if row < 0:
            import os
            os.startfile(DOWNLOADS_DIR)
            return

        pid_item = self.ts_table_products.item(row, 0)
        title_item = self.ts_table_products.item(row, 1)
        if not pid_item:
            import os
            os.startfile(DOWNLOADS_DIR)
            return

        pid = pid_item.text().strip()
        title = title_item.text().strip() if title_item else ""
        if "  [" in title:
            title = title.split("  [")[0].strip()

        # Tìm thư mục phân loại trong products.json
        folder_name = "Chưa phân loại"
        prod_json = DOWNLOADS_DIR / "products.json"
        if prod_json.exists():
            try:
                products = json.loads(prod_json.read_text(encoding="utf-8"))
                prod = next((p for p in products if p.get("product_id") == pid), None)
                if prod:
                    folder_name = prod.get("folder", "Chưa phân loại")
            except Exception:
                pass

        import os
        safe_title = clean_filename(title)

        if folder_name and folder_name != "Chưa phân loại":
            prod_dir = DOWNLOADS_DIR / folder_name / f"{pid}_{safe_title}"
        else:
            prod_dir = DOWNLOADS_DIR / f"{pid}_{safe_title}"

        if not prod_dir.exists():
            found_dir = None
            try:
                search_dirs = [DOWNLOADS_DIR]
                if folder_name and folder_name != "Chưa phân loại":
                    search_dirs.insert(0, DOWNLOADS_DIR / folder_name)
                
                for s_dir in search_dirs:
                    if s_dir.exists():
                        for entry in s_dir.iterdir():
                            if entry.is_dir() and entry.name.startswith(pid):
                                found_dir = entry
                                break
                        if found_dir:
                            break
            except Exception:
                pass
            if found_dir:
                prod_dir = found_dir
            else:
                prod_dir = DOWNLOADS_DIR

        os.startfile(str(prod_dir))

    def _sb_browse_product_image(self):
        paths, _ = QFileDialog.getOpenFileNames(
            self, "Chọn các ảnh sản phẩm", "",
            "Images (*.png *.jpg *.jpeg *.webp *.bmp)"
        )
        if paths:
            if not self._sb_cards:
                self.sb_empty_lbl.setVisible(False)
            
            for path in paths:
                idx = len(self._sb_cards)
                clean_name = extract_product_name_from_path(path)
                card = SBProductCard(idx, path, self, name=clean_name)
                card.set_view_mode(self.sb_gallery_view)
                
                # Tạo StoryProject ngay lập tức để lưu lại!
                settings = self._sb_build_batch_settings()
                sp = StoryProject(
                    product_image_path=path,
                    name=clean_name,
                    project_id=getattr(self.proj_mgr, "current_project_id", ""),
                    product_info=card.edit_req.toPlainText().strip() or clean_name,
                    num_scenes=settings.get("scene_count", 4),
                    seconds_per_scene=settings.get("duration", 10),
                    panels_per_storyboard=settings.get("panels_per_storyboard", 8),
                    aspect=settings.get("aspect", "16:9"),
                    aspect_label=settings.get("aspect_label", "Ngang (16:9)"),
                    img_model=clean_model_name(settings.get("img_model", "gpt-image-2")),
                    vid_model=settings.get("vid_model", "grok-imagine-video-1.5-preview"),
                    llm_model=settings.get("llm_model", "gpt-4o"),
                    img_size=settings.get("img_size", "1536x1024"),
                    img_quality=settings.get("img_quality", "standard"),
                    video_resolution=settings.get("video_resolution", "720p"),
                    audio_val=settings.get("audio_val", "sound_effects_only"),
                    system_prompt_override=settings.get("system_prompt", ""),
                    clone_count=settings.get("clone_count", 1),
                    reference_image_paths=list(card.ref_paths),
                    selected_context=card.context_preview.toPlainText().strip(),
                    mode="roleskill" if getattr(self, "_sb_roleskill_mode", False) else "storyboard",
                    role_skill_file=self.sb_role_combo.currentData() if (getattr(self, "_sb_roleskill_mode", False) and hasattr(self, "sb_role_combo")) else "",
                    use_proxy=settings.get("use_proxy", False)
                )
                card._story_project = sp
                self.proj_mgr.story_projects.append(sp)
                
                self._sb_cards.append(card)
                self._sb_log(f"✔ Đã thêm sản phẩm: {Path(path).name}")
            
            self.proj_mgr.save_story_projects()
            self._sb_rearrange_grid()


    def _sb_load_saved_projects(self):
        """Tải lại các StoryProject đã lưu — progressive loading, hiển realtime, log tiến trình."""
        projects = []
        for sp in self.proj_mgr.story_projects:
            if sp.product_image_path:
                resolved = resolve_moved_product_path(sp.product_image_path)
                if resolved:
                    if sp.product_image_path != resolved:
                        sp.product_image_path = resolved
                    projects.append(sp)
        if not projects:
            return

        self._sb_pending_img_loads = []
        self._sb_load_queue = list(projects)
        total = len(projects)

        if hasattr(self, 'sb_empty_lbl'):
            self.sb_empty_lbl.setVisible(False)
        self._sb_log(f"📦 Đang tải {total} sản phẩm...")

        self._sb_load_progress = 0
        self._sb_load_total = total
        QTimer.singleShot(0, self._sb_load_next_card)

    def _sb_load_next_card(self):
        """Tạo 1 card từ queue rồi yield về event loop — không block UI."""
        queue = getattr(self, '_sb_load_queue', [])
        total = getattr(self, '_sb_load_total', 1)

        if not queue:
            # All cards done — freeze repaint → layout toàn bộ 1 lần → unfreeze (không nhấp nháy)
            n = len(self._sb_cards)
            if n > 0:
                self.sb_grid_widget.setUpdatesEnabled(False)
                self._sb_rearrange_grid()
                self.sb_grid_widget.setUpdatesEnabled(True)
                self._sb_log(f"✅ Đã tải xong {n} sản phẩm.")
                QTimer.singleShot(30, self._sb_load_next_scene_image)
            return

        sp = queue.pop(0)
        self._sb_load_progress = getattr(self, '_sb_load_progress', 0) + 1
        progress = self._sb_load_progress

        try:
            idx  = len(self._sb_cards)
            card = SBProductCard(idx, sp.product_image_path, self)
            card._story_project = sp
            card.edit_name.setText(sp.product_name)
            if sp.product_info:
                card.edit_req.setPlainText(sp.product_info)

            # Restore reference images (defer thumbnail loading)
            if getattr(sp, "reference_image_paths", []):
                card.ref_paths = list(sp.reference_image_paths)
                QTimer.singleShot(200 + progress * 20, card._update_ref_thumbnails)

            # Restore context combo & role skill combo
            if getattr(sp, "selected_context", ""):
                for i in range(card.context_combo.count()):
                    if card.contexts[i]["description"] == sp.selected_context:
                        card.context_combo.blockSignals(True)
                        card.context_combo.setCurrentIndex(i)
                        card.context_combo.blockSignals(False)
                        break
                card.context_preview.setPlainText(sp.selected_context)
            if getattr(sp, "role_skill_file", "") and hasattr(self, "sb_role_combo"):
                idx_role = self.sb_role_combo.findData(sp.role_skill_file)
                if idx_role >= 0:
                    self.sb_role_combo.blockSignals(True)
                    self.sb_role_combo.setCurrentIndex(idx_role)
                    self.sb_role_combo.blockSignals(False)
                    self.update_active_role_ui()

            card.set_view_mode(self.sb_gallery_view)

            if sp.video_title or sp.product_visual_desc:
                card.set_script_info(sp.video_title, sp.product_visual_desc)

            # Build scene rows — no disk I/O (img deferred)
            if sp.scenes:
                ui_scenes = []
                for i, sc in enumerate(sp.scenes):
                    ui_scenes.append({
                        "scene_idx":  i,
                        "img_prompt": sc.storyboard_prompt,
                        "vid_prompt": sc.video_prompt,
                        "img_path":   "",
                        "video_path": "",
                        "status":     sc.status,
                        "title":      sc.scene_title,
                        "purpose":    sc.scene_purpose,
                    })
                card.init_scenes(ui_scenes)

                for _i, _sc in enumerate(sp.scenes):
                    _img = (_sc.storyboard_image_path
                            if _sc.storyboard_image_path and Path(_sc.storyboard_image_path).exists()
                            else "")
                    # Heal video_path từ video_options nếu file gốc đã bị xóa
                    _vid_resolved = (
                        _sc.video_path
                        if _sc.video_path and Path(_sc.video_path).exists()
                        else ""
                    )
                    if not _vid_resolved:
                        for _opt in getattr(_sc, "video_options", []):
                            if _opt and Path(_opt).exists():
                                _vid_resolved = _opt
                                # Tự sửa video_path để tool không bị mất trạng thái
                                _sc.video_path = _opt
                                _sc.selected_video_option = _opt
                                break
                    _vid = _vid_resolved
                    if _img or _vid:
                        self._sb_pending_img_loads.append((card, _i, _img, _vid))

            if sp.status == "done":
                card.set_status("done")
            elif sp.status == "failed":
                card.set_status("error", sp.error_msg[:20] if sp.error_msg else "Lỗi")
            elif sp.status == "generating":
                card.set_status("running", "Đang xử lý")
            else:
                card.set_status("waiting")

            self._sb_cards.append(card)
            # Thêm vào layout ngay lập tức → hiển realtime từng card
            self.sb_grid_layout.addWidget(card, idx, 0, 1, 1)
            # Log tiến trình mỗi 5 card hoặc card cuối
            if progress % 5 == 0 or progress == total:
                self._sb_log(f"  ⏳ Đang tải... ({progress}/{total})")

        except Exception as ex:
            self._sb_log(f"⚠️ Lỗi tải card #{progress}: {ex}")

        # Yield về event loop, tải card tiếp theo
        QTimer.singleShot(0, self._sb_load_next_card)


    def _sb_load_next_scene_image(self):
        """Batch-load scene images/videos one at a time without blocking UI."""
        queue = getattr(self, '_sb_pending_img_loads', [])
        if not queue:
            return
        card, idx, img_path, video_path = queue.pop(0)
        try:
            if img_path and card._is_alive():
                card.update_scene_image(idx, img_path)
            if video_path and card._is_alive():
                card.update_scene_video(idx, video_path)
        except RuntimeError:
            pass
        if queue:
            QTimer.singleShot(0, self._sb_load_next_scene_image)  # yield to event loop

    def _sb_start_next_products(self):
        try:
            self._sb_start_next_products_inner()
        except Exception as e:
            import traceback
            self._sb_log(f"❌ [_sb_start_next_products] Lỗi: {e}")
            self._sb_log(f"    Traceback: {traceback.format_exc()}")

    def _sb_start_next_products_inner(self):
        if not self._sb_running or self._sb_paused:
            return

        # Clean up deleted cards
        self._sb_cards = [c for c in self._sb_cards if c and c._is_alive()]
        self._sb_pending_queue = [c for c in self._sb_pending_queue if c and c._is_alive()]
        self._sb_active_cards = [c for c in self._sb_active_cards if c and c._is_alive()]
            
        # Check if all cards are done
        total_done = sum(1 for c in self._sb_cards if c._status == "done")
        self.sb_total_progress.setValue(total_done)
        
        if total_done == len(self._sb_cards) and not self._sb_pending_queue and not self._sb_active_cards:
            self._sb_log("✔ Đã hoàn thành xử lý tất cả sản phẩm trong hàng chờ.")
            self.sb_status_lbl.setText("✔ Hoàn thành")
            self._sb_reset_ui()
            return

        # Check if we can start a new card
        # Parse thread spin box value, e.g. "3 luồng" -> 3
        max_threads = int(self.sb_chat_thread_combo.currentText().split()[0]) if hasattr(self, 'sb_chat_thread_combo') else 3
        
        # If we have slots available and pending cards
        while self._sb_active_chat_count < max_threads and self._sb_pending_queue:
            now = time.time()
            # Parse delay combo value, e.g. "7 giây" -> 7
            stagger_sec = float(self.sb_delay_spin.currentText().split()[0])
            elapsed = now - self._sb_last_start_time
            if elapsed < stagger_sec:
                # Schedule a timer to check again
                wait_ms = int((stagger_sec - elapsed) * 1000)
                QTimer.singleShot(max(50, wait_ms), self._sb_start_next_products)
                break
                
            card = self._sb_pending_queue.pop(0)
            self._sb_active_cards.append(card)
            self._sb_last_start_time = now
            self._sb_log(f"🚀 Khởi chạy luồng cho sản phẩm: {card.edit_name.text()}")
            self._sb_process_card(card)

    _pipeline_debug_path = Path(os.environ.get('TEMP', '.')) / 'autogrok_pipeline_debug.log'

    def _pipeline_dbg(self, msg):
        """Write debug log to file (always works, independent of Qt signal)."""
        try:
            with open(self._pipeline_debug_path, 'a', encoding='utf-8') as f:
                f.write(f"[{time.strftime('%H:%M:%S')}] {msg}\n")
        except Exception:
            pass

    def _sb_process_card(self, card):
        """Xử lý 1 product card: tạo StoryProject, sinh prompt, dispatch scenes."""
        self._pipeline_dbg(f"_sb_process_card ENTER for card={card.edit_name.text() if hasattr(card, 'edit_name') else '?'}")
        try:
            self._sb_process_card_inner(card)
            self._pipeline_dbg("_sb_process_card_inner returned OK")
        except Exception as e:
            import traceback
            tb = traceback.format_exc()
            self._pipeline_dbg(f"_sb_process_card EXCEPTION: {e}\n{tb}")
            self._sb_log(f"❌ [_sb_process_card] Lỗi nghiêm trọng: {e}")
            self._sb_log(f"    Traceback: {tb}")
            sp = getattr(card, '_story_project', None)
            if sp:
                sp.status = "failed"
                sp.error_msg = str(e)
            card.set_status("error", str(e)[:30])
            if card in self._sb_active_cards:
                self._sb_active_cards.remove(card)
            self._sb_start_next_products()

    def _sb_process_card_inner(self, card):
        """Inner implementation of _sb_process_card."""
        self._pipeline_dbg("  INNER START")
        self._sb_log(f"  🔍 [DEBUG] _sb_process_card_inner START | paused={self._sb_paused} | running={self._sb_running}")
        if self._sb_paused or not self._sb_running:
            self._sb_log(f"  🔍 [DEBUG] Skipped (paused/not running)")
            return

        # Step 0: Tạo StoryProject + sinh kịch bản nếu chưa có
        if not hasattr(card, '_story_project') or card._story_project is None:
            self._pipeline_dbg("  Creating StoryProject...")
            # Tạo StoryProject từ card info + settings
            settings = self._sb_build_batch_settings()
            self._pipeline_dbg(f"  settings OK: llm={settings.get('llm_model')}, img={settings.get('img_model')}, vid={settings.get('vid_model')}")
            # Lấy tên sản phẩm từ card (edit_name hoặc tên trong product_info)
            _card_name = card.edit_name.text().strip() if hasattr(card, 'edit_name') else ""
            if not _card_name:
                _card_name = card.edit_req.toPlainText().strip().split('\n')[0][:80] if hasattr(card, 'edit_req') else ""
            sp = StoryProject(
                name=_card_name,
                product_image_path=card.img_path,
                project_id=getattr(self.proj_mgr, "current_project_id", ""),
                product_info=card.edit_req.toPlainText().strip() or Path(card.img_path).stem,
                num_scenes=settings.get("scene_count", 4),
                seconds_per_scene=settings.get("duration", 10),
                panels_per_storyboard=settings.get("panels_per_storyboard", 8),
                aspect=settings.get("aspect", "16:9"),
                aspect_label=settings.get("aspect_label", "Ngang (16:9)"),
                img_model=clean_model_name(settings.get("img_model", "gpt-image-2")),
                vid_model=settings.get("vid_model", "grok-imagine-video-1.5-preview"),
                llm_model=settings.get("llm_model", "gpt-4o"),
                img_size=settings.get("img_size", "1536x1024"),
                img_quality=settings.get("img_quality", "standard"),
                video_resolution=settings.get("video_resolution", "720p"),
                audio_val=settings.get("audio_val", "sound_effects_only"),
                system_prompt_override=settings.get("system_prompt", ""),
                max_retries=settings.get("max_retries", 3),
                clone_count=settings.get("clone_count", 1),
                reference_image_paths=list(card.ref_paths),
                selected_context=card.context_preview.toPlainText().strip(),
                mode="roleskill" if getattr(self, "_sb_roleskill_mode", False) else "storyboard",
                role_skill_file=self.sb_role_combo.currentData() if (getattr(self, "_sb_roleskill_mode", False) and hasattr(self, "sb_role_combo")) else "",
                use_proxy=settings.get("use_proxy", False)
            )
            card._story_project = sp
            # Pre-cache output_dir ngay khi tạo để đảm bảo tên thư mục đúng ngay từ đầu
            _ = sp.output_dir
            # ── Role Skill mode: inject .MD content as system prompt, force 1 panel ──
            if getattr(self, '_sb_roleskill_mode', False):
                sp.panels_per_storyboard = 1  # Ảnh đơn, không grid
                rs_file = self.sb_role_combo.currentData() if hasattr(self, 'sb_role_combo') else ""
                if rs_file:
                    rs_path = get_role_skill_path(rs_file)
                    if rs_path and rs_path.exists():
                        try:
                            sp.role_skill_file = rs_file
                            sp.system_prompt_override = rs_path.read_text(encoding="utf-8")
                            self._sb_log(f"🎭 Đã load Role Skill: {rs_file}")
                        except Exception as e:
                            self._sb_log(f"⚠️ Lỗi đọc Role Skill: {e}")
            # Thêm vào project manager để persist
            self.proj_mgr.story_projects.append(sp)
            self._pipeline_dbg(f"  StoryProject created OK: name={sp.name[:30]}, llm={sp.llm_model}")

        sp = card._story_project
        self._sb_log(f"  🔍 [DEBUG] sp.status={sp.status!r}, sp.scenes={len(sp.scenes) if sp.scenes else 0}, card.scene_prompts={len(card.scene_prompts)}")

        # Đồng bộ và làm mới system prompt từ Role Skill đã chọn nếu đang ở chế độ roleskill
        if getattr(self, '_sb_roleskill_mode', False) and hasattr(self, 'sb_role_combo'):
            rs_file = self.sb_role_combo.currentData()
            if rs_file:
                rs_path = get_role_skill_path(rs_file)
                if rs_path and rs_path.exists():
                    try:
                        sp.role_skill_file = rs_file
                        sp.system_prompt_override = rs_path.read_text(encoding="utf-8")
                    except Exception as e:
                        self._sb_log(f"⚠️ Lỗi cập nhật Role Skill: {e}")

        # ── Reset projects bị failed mà chưa có scenes → cho retry ──
        if sp.status == "failed" and not sp.scenes:
            self._sb_log(f"[{card.edit_name.text()}] 🔄 Reset project failed (chưa có scenes) → thử lại...")
            sp.status = "queued"
            sp.error_msg = ""

        _need_script = (not card.scene_prompts and not sp.scenes and sp.status in ("queued", "scripting", "generating"))
        self._sb_log(f"  🔍 [DEBUG] need_script={_need_script} (status={sp.status!r})")

        if _need_script:
            sp.status = "scripting"
            card.set_status("generating", "Sinh kịch bản...")
            self._sb_log(f"[{card.edit_name.text()}] ▶ Bắt đầu kịch bản quảng cáo...")

            self._pipeline_dbg(f"  need_script=True, getting account for model={sp.llm_model}")
            acc = self.acc_mgr.next_for_model(sp.llm_model)
            self._pipeline_dbg(f"  acc={acc.name if acc else 'NONE'}")
            if not acc:
                sp.status = "failed"
                sp.error_msg = "Không có tài khoản active"
                card.set_status("error", "Không có TK")
                self._sb_log(f"[{card.edit_name.text()}] ❌ Lỗi: Không có tài khoản.")
                if card in self._sb_active_cards:
                    self._sb_active_cards.remove(card)
                self.proj_mgr.save_story_projects()
                self._sb_start_next_products()
                return

            self._sb_log(f"  🔍 [DEBUG] Tạo SBPromptGenWorker, acc={acc.name if hasattr(acc, 'name') else acc}, model={sp.llm_model}")
            worker = SBPromptGenWorker(acc, sp)
            worker.log_signal.connect(self._sb_log)

            def on_prompts_ok(script_dict, _card=card, _sp=sp):
                self._sb_active_chat_count = max(0, self._sb_active_chat_count - 1)
                _sp.script_json = script_dict
                _sp.product_visual_desc = script_dict.get("product_visual_description", "")
                _sp.video_title = script_dict.get("video_title", "")
                _sp.status = "generating"

                # Convert scenes from dict to StoryScene objects
                scenes_data = script_dict.get("scenes", [])
                _sp.scenes = []
                for sd in scenes_data:
                    img_p = sd.get("storyboard_prompt") or sd.get("image_prompt") or sd.get("img_prompt") or ""
                    vid_p = sd.get("video_prompt") or sd.get("vid_prompt") or ""
                    _sp.scenes.append(StoryScene(
                        scene_number=sd.get("scene_number", len(_sp.scenes) + 1),
                        scene_title=sd.get("scene_title") or sd.get("title") or "",
                        scene_purpose=sd.get("scene_purpose", ""),
                        scene_description=sd.get("scene_description") or sd.get("description") or "",
                        storyboard_prompt=img_p,
                        video_prompt=vid_p,
                    ))

                # Init UI scenes
                ui_scenes = []
                for i, sc in enumerate(_sp.scenes):
                    ui_scenes.append({
                        "scene_idx": i,
                        "img_prompt": sc.storyboard_prompt,
                        "vid_prompt": sc.video_prompt,
                        "img_path": "",
                        "video_path": "",
                        "status": "pending",
                        "title": sc.scene_title,
                        "purpose": sc.scene_purpose,
                    })
                _card.init_scenes(ui_scenes)
                _card.set_status("waiting")
                _card.set_script_info(_sp.video_title, _sp.product_visual_desc)
                self._sb_log(f"[{_card.edit_name.text()}] ✔ Kịch bản: {_sp.video_title}")
                self._sb_log(f"[{_card.edit_name.text()}] ✔ Đã tạo xong {len(_sp.scenes)} phân cảnh.")
                self.proj_mgr.save_story_projects()
                QTimer.singleShot(300, self._sb_dispatch_scenes)

            def on_prompts_err(msg, _card=card, _sp=sp):
                self._sb_active_chat_count = max(0, self._sb_active_chat_count - 1)
                # Detect transient server errors -> auto retry
                _transient = any(f'API error {code}' in msg for code in ['520', '503', '502', '429', '500'])
                _retry_count = getattr(_sp, '_prompt_retry_count', 0)
                if _transient and _retry_count < 3:
                    _sp._prompt_retry_count = _retry_count + 1
                    _sp.status = 'queued'  # Reset to retry
                    _card.set_status('waiting', f'Retry {_retry_count+1}/3...')
                    self._sb_log(f'[{_card.edit_name.text()}] ⚠ Lỗi tạm thời (retry {_retry_count+1}/3): {msg[:60]}')
                    self._sb_log(f'[{_card.edit_name.text()}] Thử lại sau 8 giây với account khác...')
                    QTimer.singleShot(8000, lambda _c=_card: self._sb_process_card(_c))
                    return
                # Permanent error or max retries exceeded
                _sp._prompt_retry_count = 0
                _sp.status = 'failed'
                _sp.error_msg = msg
                _card.set_status('error', msg[:30])
                self._sb_log(f'[{_card.edit_name.text()}] Lỗi tạo kịch bản: {msg}')
                if _card in self._sb_active_cards:
                    self._sb_active_cards.remove(_card)
                self.proj_mgr.save_story_projects()
                self._sb_start_next_products()

            worker.prompts_ready.connect(on_prompts_ok)
            worker.error_signal.connect(on_prompts_err)
            card.active_worker = worker
            self._sb_log(f"  🔍 [DEBUG] worker.start() → LLM đang chạy trong thread riêng...")
            self._sb_active_chat_count += 1
            worker.start()
            return

        self._sb_log(f"  🔍 [DEBUG] Không vào nhánh script → kiểm tra sp.scenes...")
        if sp.scenes:
            has_pending = any(s.status not in ("done", "failed") for s in sp.scenes)
            if has_pending and sp.status not in ("generating", "scripting", "assembling"):
                # Status bị sai (queued/done) khi load từ disk → fix về generating
                self._sb_log(f"[{card.edit_name.text()}] \U0001f504 Tr\u1ea1ng th\u00e1i sp={sp.status!r}, c\u00f2n {sum(1 for s in sp.scenes if s.status not in ('done','failed'))} scene → \u0111\u1eb7t 'generating'")
                sp.status = "generating"
        self._sb_dispatch_scenes()

    def _sb_dispatch_scenes(self):
        """Dispatch scene work từ TẤT CẢ products, song song tối đa max_threads."""
        try:
            self._sb_dispatch_scenes_inner()
        except Exception as e:
            import traceback
            self._sb_log(f"❌ [_sb_dispatch_scenes] Lỗi: {e}")
            self._sb_log(f"    Traceback: {traceback.format_exc()}")

    def _sb_dispatch_scenes_inner(self):
        if not self._sb_running or self._sb_paused:
            return

        # Clean up deleted cards
        self._sb_cards = [c for c in self._sb_cards if c and c._is_alive()]
        self._sb_pending_queue = [c for c in self._sb_pending_queue if c and c._is_alive()]
        self._sb_active_cards = [c for c in self._sb_active_cards if c and c._is_alive()]

        max_chat_threads = int(self.sb_chat_thread_combo.currentText().split()[0]) if hasattr(self, 'sb_chat_thread_combo') else 3
        max_img_threads = int(self.sb_img_thread_combo.currentText().split()[0]) if hasattr(self, 'sb_img_thread_combo') else 5
        max_vid_threads = int(self.sb_vid_thread_combo.currentText().split()[0]) if hasattr(self, 'sb_vid_thread_combo') else 3

        # Kiểm tra hoàn thành từng product
        for card in list(self._sb_active_cards):
            sp = getattr(card, '_story_project', None)
            if not sp or not sp.scenes:
                continue
            all_done = all(s.status in ("done", "failed") for s in sp.scenes)
            if all_done and sp.status == "generating":
                # Tất cả scenes xong → Step 3: nối video
                successful = [s for s in sp.scenes if s.status == "done" and s.video_path]
                failed = [s for s in sp.scenes if s.status == "failed"]
                
                if failed and getattr(self, "sb_auto_retry_failed_chk", None) and self.sb_auto_retry_failed_chk.isChecked():
                    self._sb_log(f"[{card.edit_name.text()}] 🔄 Phát hiện {len(failed)} phân cảnh lỗi. Tự động chuyển trạng thái về 'pending' để chạy lại...")
                    for s in failed:
                        s.status = "pending"
                        s.error_msg = ""
                    self.proj_mgr.save_story_projects()
                    # Trigger dispatch_scenes lại sau 1s để chạy tiếp
                    QTimer.singleShot(1000, self._sb_dispatch_scenes)
                    continue

                if failed:
                    self._sb_log(f"[{card.edit_name.text()}] ⚠️ {len(failed)} scene lỗi, {len(successful)} OK")
                
                if successful:
                    sp.status = "assembling"
                    card.set_status("generating", "Đang nối video...")
                    self._sb_log(f"[{card.edit_name.text()}] 🔗 Bắt đầu nối {len(successful)} video...")
                    self._sb_concat_videos(card, sp)
                else:
                    if getattr(sp, "render_only", "both") == "image":
                        sp.status = "done"
                        card.set_status("done")
                        self._sb_log(f"[{card.edit_name.text()}] ✅ Đã hoàn thành vẽ ảnh phân cảnh!")
                    else:
                        sp.status = "failed"
                        sp.error_msg = "Tất cả scene đều thất bại"
                        card.set_status("done")
                        self._sb_log(f"[{card.edit_name.text()}] ❌ Tất cả scene thất bại.")
                    
                    if card in self._sb_active_cards:
                        self._sb_active_cards.remove(card)
                    self.proj_mgr.save_story_projects()
                    self._sb_start_next_products()
                continue

        # Cập nhật progress
        total_done = sum(1 for c in self._sb_cards if c._status == "done")
        self.sb_total_progress.setValue(total_done)

        # Pipeline stops only when queue empty AND all active workers are done
        all_products_done = (
            not self._sb_pending_queue
            and self._sb_active_chat_count == 0
            and self._sb_active_img_count == 0
            and self._sb_active_vid_count == 0
            and all(c._status in ('done', 'error') for c in self._sb_cards)
        ) if self._sb_cards else False
        if all_products_done:
            self._sb_log('✔ Đã hoàn thành xử lý tất cả sản phẩm!')
            self.sb_status_lbl.setText('✔ Hoàn thành')
            self._sb_reset_ui()
            return

        # Status label showing separate counts
        total_scenes = sum(len(getattr(c, '_story_project', None).scenes) for c in self._sb_active_cards if getattr(c, '_story_project', None) and getattr(c, '_story_project', None).scenes)
        done_scenes = sum(1 for c in self._sb_active_cards if getattr(c, '_story_project', None) for s in (getattr(c, '_story_project', None).scenes or []) if s.status in ("done", "failed"))
        
        chat_act = self._sb_active_chat_count
        img_act = self._sb_active_img_count
        vid_act = self._sb_active_vid_count
        self.sb_status_lbl.setText(
            f"⚙ Luồng: Chat {chat_act} | Ảnh {img_act} | Video {vid_act} | "
            f"Phân cảnh: {done_scenes}/{total_scenes}"
        )

        # Dispatch thêm scene work (với delay riêng biệt cho Ảnh và Video)
        delay_sec = float(self.sb_delay_spin.currentText().split()[0])
        for card in self._sb_active_cards:
            sp = getattr(card, '_story_project', None)
            if not sp or not sp.scenes or sp.status != "generating":
                continue
            for i, scene in enumerate(sp.scenes):
                # --- Tự sửa trạng thái (self-healing) dựa trên file thực tế trên đĩa ---
                _has_img = scene.storyboard_image_path and Path(scene.storyboard_image_path).exists()
                _has_vid = scene.video_path and Path(scene.video_path).exists()
                if _has_vid:
                    if scene.status != "done":
                        scene.status = "done"
                elif _has_img:
                    if scene.status not in ("img_done", "vid_gen"):
                        scene.status = "img_done"
                else:
                    if scene.status not in ("pending", "img_gen"):
                        scene.status = "pending"

                is_img_needed = (not scene.storyboard_image_path or not Path(scene.storyboard_image_path).exists()) and scene.status not in ("img_gen", "vid_gen", "done", "failed")
                is_vid_needed = scene.storyboard_image_path and Path(scene.storyboard_image_path).exists() and not scene.video_path and scene.status == "img_done"
                
                if is_img_needed:
                    if self._sb_active_img_count >= max_img_threads:
                        continue
                    now = time.time()
                    elapsed = now - self._sb_last_img_dispatch_time
                    if delay_sec > 0 and self._sb_last_img_dispatch_time > 0 and elapsed < delay_sec:
                        wait_ms = int((delay_sec - elapsed) * 1000)
                        QTimer.singleShot(max(100, wait_ms), self._sb_dispatch_scenes)
                        return
                    self._sb_last_img_dispatch_time = time.time()
                    self._sb_active_img_count += 1
                    self._sb_process_scene(card, i)
                    
                elif is_vid_needed:
                    if self._sb_active_vid_count >= max_vid_threads:
                        continue
                    now = time.time()
                    elapsed = now - self._sb_last_vid_dispatch_time
                    if delay_sec > 0 and self._sb_last_vid_dispatch_time > 0 and elapsed < delay_sec:
                        wait_ms = int((delay_sec - elapsed) * 1000)
                        QTimer.singleShot(max(100, wait_ms), self._sb_dispatch_scenes)
                        return
                    self._sb_last_vid_dispatch_time = time.time()
                    self._sb_active_vid_count += 1
                    self._sb_process_scene(card, i)

        # Start more products if Chat slots available
        if self._sb_active_chat_count < max_chat_threads and self._sb_pending_queue:
            self._sb_start_next_products()

    def _sb_process_scene(self, card, scene_idx: int):
        """Xử lý 1 scene: ảnh storyboard → video. Chạy song song."""
        if self._sb_paused or not self._sb_running:
            return

        sp = card._story_project
        scene = sp.scenes[scene_idx]
        name = card.edit_name.text()

        # Điều chỉnh status theo file thực tế (tránh bị stuck do status không khớp với disk)
        _has_img_f = scene.storyboard_image_path and Path(scene.storyboard_image_path).exists()
        _has_vid_f = scene.video_path and Path(scene.video_path).exists()
        if _has_vid_f and scene.status != "done":
            scene.status = "done"
            self.proj_mgr.save_story_projects()
            QTimer.singleShot(200, self._sb_dispatch_scenes)
            return
        elif _has_img_f and scene.status not in ("img_done", "vid_gen", "done"):
            scene.status = "img_done"  # Ảnh có sẵn → đối sang video

        # Step 1: Tạo ảnh storyboard
        if not scene.storyboard_image_path or not Path(scene.storyboard_image_path).exists():
            scene.status = "img_gen"
            card.update_scene_status(scene_idx, "generating", "Đang vẽ ảnh...")
            card.set_status("generating", f"Ảnh {scene_idx+1}/{len(sp.scenes)}")

            selected_model = sp.img_model
            is_veo_img = is_veo_model(selected_model)
            acc = None
            v_acc = None
            if is_veo_img:
                v_acc = self.next_veo_account()
                if not v_acc:
                    scene.status = "failed"
                    scene.error_msg = "Không có TK Google"
                    card.update_scene_status(scene_idx, "error", "Không TK Google")
                    self._sb_active_img_count = max(0, self._sb_active_img_count - 1)
                    self.proj_mgr.save_story_projects()
                    QTimer.singleShot(500, self._sb_dispatch_scenes)
                    return
                acc_tag = f"Google:{v_acc.name}"
            else:
                acc = self.acc_mgr.next_for_model(selected_model)
                if not acc:
                    scene.status = "failed"
                    scene.error_msg = "Không có TK"
                    card.update_scene_status(scene_idx, "error", "Không TK")
                    self._sb_active_img_count = max(0, self._sb_active_img_count - 1)
                    self.proj_mgr.save_story_projects()
                    QTimer.singleShot(500, self._sb_dispatch_scenes)
                    return
                acc_tag = f"{getattr(acc, 'tag', 'Acc')}:{getattr(acc, 'name', '?')}"

            self._sb_log(f"[{name}] [Cảnh {scene_idx+1}] [{acc_tag}] 🎨 {scene.scene_title} — Đang vẽ ảnh...")

            worker = SBImageWorker(acc, scene_idx, sp)
            worker.app = self
            if is_veo_img and v_acc:
                worker.veo_bearer = v_acc.api_key
                worker.veo_project_id = v_acc.proxy_url
                worker.google_account_name = v_acc.name
                worker.google_profile_name = _google_profile_name_for_account(v_acc)
            else:
                worker.veo_bearer = ""
                worker.veo_project_id = ""
            worker.captcha_bridge = getattr(self, "captcha_bridge", None)
            worker.log_signal.connect(self._sb_log)

            def on_img_ok(idx, path, _card=card, _sp=sp):
                _sp.scenes[idx].storyboard_image_path = path
                if getattr(_sp, "render_only", "both") == "image":
                    _sp.scenes[idx].status = "done"
                else:
                    _sp.scenes[idx].status = "img_done"
                self._sb_active_img_count = max(0, self._sb_active_img_count - 1)
                self.proj_mgr.save_story_projects()
                try:
                    _card.update_scene_image(idx, path)
                    self._sb_log(f"[{_card.edit_name.text()}] [Cảnh {idx+1}] ✔ Ảnh storyboard xong!")
                except RuntimeError:
                    self._sb_log(f"[Cảnh {idx+1}] ✔ Ảnh xong (card đã rebuild do token refresh).")
                QTimer.singleShot(300, self._sb_dispatch_scenes)

            def on_img_err(idx, msg, _card=card, _sp=sp):
                _sp.scenes[idx].status = "failed"
                _sp.scenes[idx].error_msg = msg
                self._sb_active_img_count = max(0, self._sb_active_img_count - 1)
                self.proj_mgr.save_story_projects()
                try:
                    _card.update_scene_status(idx, "error", msg[:30])
                    self._sb_log(f"[{_card.edit_name.text()}] [Cảnh {idx+1}] ❌ Lỗi ảnh: {msg}")
                except RuntimeError:
                    self._sb_log(f"[Cảnh {idx+1}] ❌ Lỗi ảnh: {msg} (card đã rebuild).")
                QTimer.singleShot(500, self._sb_dispatch_scenes)

            worker.image_ready.connect(on_img_ok)
            worker.error_signal.connect(on_img_err)
            card.active_worker = worker
            worker.start()
            return

        # Step 2: Tạo video từ storyboard
        if not scene.video_path and scene.status == "img_done":
            scene.status = "vid_gen"
            card.update_scene_status(scene_idx, "generating", "Đang dựng video...")
            card.set_status("generating", f"Video {scene_idx+1}/{len(sp.scenes)}")

            selected_vid_model = sp.vid_model
            is_veo_vid = is_veo_model(selected_vid_model)
            acc = None
            v_acc = None
            if is_veo_vid:
                v_acc = self.next_veo_account()
                if not v_acc:
                    scene.status = "failed"
                    scene.error_msg = "Không có TK Google"
                    card.update_scene_status(scene_idx, "error", "Không TK Google")
                    self._sb_active_vid_count = max(0, self._sb_active_vid_count - 1)
                    self.proj_mgr.save_story_projects()
                    QTimer.singleShot(500, self._sb_dispatch_scenes)
                    return
            else:
                acc = self.acc_mgr.next_for_model(selected_vid_model)
                if not acc:
                    scene.status = "failed"
                    scene.error_msg = "Không có TK"
                    card.update_scene_status(scene_idx, "error", "Không TK")
                    self._sb_active_vid_count = max(0, self._sb_active_vid_count - 1)
                    self.proj_mgr.save_story_projects()
                    QTimer.singleShot(500, self._sb_dispatch_scenes)
                    return

            # Determine account for logging
            _vid_acc = v_acc if is_veo_vid else acc
            _vid_tag = ('Google:' + getattr(_vid_acc, 'name', '?')) if is_veo_vid else (getattr(_vid_acc, 'tag', 'Acc') + ':' + getattr(_vid_acc, 'name', '?')) if _vid_acc else 'no_acc'
            self._sb_log(f'[{name}] [Cảnh {scene_idx+1}] [{_vid_tag}] 🎥 {scene.scene_title} — Đang tạo video...')

            worker = SBVideoWorker(acc, scene_idx, sp)
            worker.app = self
            if is_veo_vid and v_acc:
                worker.veo_bearer = v_acc.api_key
                worker.veo_project_id = v_acc.proxy_url
                worker.google_account_name = v_acc.name
                worker.google_profile_name = _google_profile_name_for_account(v_acc)
            else:
                worker.veo_bearer = ""
                worker.veo_project_id = ""
            worker.captcha_bridge = getattr(self, "captcha_bridge", None)
            worker.log_signal.connect(self._sb_log)

            def on_vid_ok(idx, video_path, _card=card, _sp=sp, _worker=worker):
                _sp.scenes[idx].video_path = video_path
                _sp.scenes[idx].video_options = getattr(getattr(_worker, "job", None), "video_options", [video_path])
                _sp.scenes[idx].selected_video_option = video_path
                _sp.scenes[idx].status = "done"
                self._sb_active_vid_count = max(0, self._sb_active_vid_count - 1)
                self.proj_mgr.save_story_projects()
                try:
                    _card.update_scene_video(idx, video_path)
                    self._sb_log(f"[{_card.edit_name.text()}] [Cảnh {idx+1}] ✅ Video hoàn thành!")
                except RuntimeError:
                    self._sb_log(f"[Cảnh {idx+1}] ✅ Video xong (card đã rebuild do token refresh).")
                QTimer.singleShot(300, self._sb_dispatch_scenes)

            def on_vid_err(idx, msg, _card=card, _sp=sp):
                _sp.scenes[idx].status = "failed"
                _sp.scenes[idx].error_msg = msg
                self._sb_active_vid_count = max(0, self._sb_active_vid_count - 1)
                self.proj_mgr.save_story_projects()
                try:
                    _card.update_scene_status(idx, "error", msg[:30])
                    self._sb_log(f"[{_card.edit_name.text()}] [Cảnh {idx+1}] ❌ Lỗi video: {msg}")
                except RuntimeError:
                    self._sb_log(f"[Cảnh {idx+1}] ❌ Lỗi video: {msg} (card đã rebuild).")
                QTimer.singleShot(500, self._sb_dispatch_scenes)

            worker.video_ready.connect(on_vid_ok)
            worker.error_signal.connect(on_vid_err)
            card.active_worker = worker
            worker.start()
            return

    def _sb_concat_videos(self, card, sp):
        """Step 3: Hiện PreConcatDialog hoặc tự động nối video theo settings."""
        # 1. Kiểm tra nếu chế độ Tự động nối video được bật
        if getattr(self, "sb_auto_concat_chk", None) and self.sb_auto_concat_chk.isChecked():
            saved = getattr(self, "sb_auto_concat_settings", None) or {
                "transition": "Không (cắt thẳng)",
                "num_outputs": 1,
                "no_duplicate": False,
                "bg_music_path": None,
                "voiceover_path": None,
                "voice_speed_adjust": True,
                "bg_music_vol": 0.3,
                "voiceover_vol": 1.0,
                "orig_video_vol": 1.0,
            }
            
            settings = {
                "transition": saved.get("transition", "Không (cắt thẳng)"),
                "num_outputs": saved.get("num_outputs", 1),
                "no_duplicate": saved.get("no_duplicate", False),
                "bg_music_path": saved.get("bg_music_path"),
                "voiceover_path": (
                    __import__('random').choice([v for v in getattr(sp, 'voice_paths', []) if v and __import__('pathlib').Path(v).exists()])
                    if getattr(sp, 'voice_paths', []) else saved.get("voiceover_path")
                ),
                "voice_speed_adjust": saved.get("voice_speed_adjust", True),
                "bg_music_vol": saved.get("bg_music_vol", 0.3),
                "voiceover_vol": saved.get("voiceover_vol", 1.0),
                "orig_video_vol": saved.get("orig_video_vol", 1.0),
                "scenes": []
            }

            
            for scene in sorted(sp.scenes, key=lambda s: s.scene_number):
                opts = getattr(scene, "video_options", [])
                if not opts and scene.video_path:
                    opts = [scene.video_path]
                valid_opts = [o for o in opts if o and Path(o).exists()]
                if not valid_opts and scene.video_path and Path(scene.video_path).exists():
                    valid_opts = [scene.video_path]
                
                for _vopt in valid_opts:  # Them tat ca clone vao list
                    settings["scenes"].append({
                        "scene_number": scene.scene_number,
                        "video_path": _vopt,
                        "trim_start": 0.0,
                        "duration": float(sp.seconds_per_scene),
                    })
            if not settings["scenes"]:
                self._sb_log(f"[{card.edit_name.text()}] ⚠️ Không tìm thấy scene video nào hợp lệ để tự động nối.")
                sp.status = "done"
                card.set_status("done")
                if card in self._sb_active_cards:
                    self._sb_active_cards.remove(card)
                self.proj_mgr.save_story_projects()
                self._sb_start_next_products()
                QTimer.singleShot(500, self._sb_dispatch_scenes)
                return
                
            self._sb_log(f"[{card.edit_name.text()}] 🤖 Auto Render: Đang tự động nối {len(settings['scenes'])} scenes...")
            self._sb_log(f"[{card.edit_name.text()}]   Hiệu ứng: {settings['transition']}")
            
            worker = FFmpegConcatWorker(sp, concat_settings=settings)
            worker.log_signal.connect(self._sb_log)

            def on_auto_ok(final_path, _card=card, _sp=sp):
                _sp.final_video_path = final_path
                _sp.status = "done"
                _card.set_status("done")
                self._sb_log(f"[{_card.edit_name.text()}] ✅ Auto Render hoàn thành! Final: {Path(final_path).name}")
                if _card in self._sb_active_cards:
                    self._sb_active_cards.remove(_card)
                self.proj_mgr.save_story_projects()
                self._sb_start_next_products()
                QTimer.singleShot(500, self._sb_dispatch_scenes)

            def on_auto_err(msg, _card=card, _sp=sp):
                _sp.status = "done"
                _sp.error_msg = f"Nối video lỗi: {msg}"
                _card.set_status("done")
                self._sb_log(f"[{_card.edit_name.text()}] ⚠️ Auto Render lỗi nối: {msg} (Nhưng giữ các clip lẻ)")
                if _card in self._sb_active_cards:
                    self._sb_active_cards.remove(_card)
                self.proj_mgr.save_story_projects()
                self._sb_start_next_products()
                QTimer.singleShot(500, self._sb_dispatch_scenes)

            worker.concat_ready.connect(on_auto_ok)
            worker.error_signal.connect(on_auto_err)
            card.active_worker = worker
            worker.start()
            return

        # 2. Ngược lại, trì hoãn hiển thị Dialog modal bằng QTimer để tránh xung đột re-entrancy / chặn luồng
        def show_dialog_deferred(_card=card, _sp=sp):
            try:
                dialog = PreConcatDialog(_sp, self)
                result = dialog.exec()
                
                if result == QDialog.DialogCode.Accepted and dialog.result_settings:
                    settings = dialog.result_settings
                    self._sb_log(f"[{_card.edit_name.text()}] 🎬 Bắt đầu nối {len(settings['scenes'])} scenes...")
                    self._sb_log(f"[{_card.edit_name.text()}]   Hiệu ứng: {settings['transition']}")
                    for s in settings["scenes"]:
                        if s["trim_start"] > 0:
                            self._sb_log(f"[{_card.edit_name.text()}]   Cảnh {s['scene_number']}: cắt {s['trim_start']}s đầu")
                    
                    worker = FFmpegConcatWorker(_sp, concat_settings=settings)
                    worker.log_signal.connect(self._sb_log)

                    def on_ok(final_path):
                        _sp.final_video_path = final_path
                        _sp.status = "done"
                        _card.set_status("done")
                        self._sb_log(f"[{_card.edit_name.text()}] ✅ Hoàn thành! Final: {Path(final_path).name}")
                        if _card in self._sb_active_cards:
                            self._sb_active_cards.remove(_card)
                        self.proj_mgr.save_story_projects()
                        self._sb_start_next_products()
                        QTimer.singleShot(500, self._sb_dispatch_scenes)

                    def on_err(msg):
                        _sp.status = "done"
                        _sp.error_msg = f"Nối video lỗi: {msg}"
                        _card.set_status("done")
                        self._sb_log(f"[{_card.edit_name.text()}] ⚠️ Nối video lỗi: {msg}")
                        self._sb_log(f"[{_card.edit_name.text()}] → Videos riêng lẻ vẫn có trong thư mục output.")
                        if _card in self._sb_active_cards:
                            self._sb_active_cards.remove(_card)
                        self.proj_mgr.save_story_projects()
                        self._sb_start_next_products()
                        QTimer.singleShot(500, self._sb_dispatch_scenes)

                    worker.concat_ready.connect(on_ok)
                    worker.error_signal.connect(on_err)
                    _card.active_worker = worker
                    worker.start()
                else:
                    # User cancelled
                    _sp.status = "done"
                    _card.set_status("done")
                    self._sb_log(f"[{_card.edit_name.text()}] ⏭ Bỏ qua nối video (user huỷ)")
                    if _card in self._sb_active_cards:
                        self._sb_active_cards.remove(_card)
                    self.proj_mgr.save_story_projects()
                    self._sb_start_next_products()
                    QTimer.singleShot(500, self._sb_dispatch_scenes)
            except Exception as ex:
                self._sb_log(f"[{_card.edit_name.text()}] ❌ Lỗi hiển thị dialog nối: {ex}")
                _sp.status = "done"
                _card.set_status("done")
                if _card in self._sb_active_cards:
                    self._sb_active_cards.remove(_card)
                self.proj_mgr.save_story_projects()
                self._sb_start_next_products()
                QTimer.singleShot(500, self._sb_dispatch_scenes)

        QTimer.singleShot(0, show_dialog_deferred)

    def _sb_configure_auto_concat(self):
        """Mở cấu hình thiết lập tự động nối video."""
        # Thu thập voice_paths từ tất cả sản phẩm hiện tại
        all_voices: list = []
        for _sp in getattr(getattr(self, "proj_mgr", None), "story_projects", []):
            for _v in get_voices_for_project(_sp):
                if _v and Path(_v).exists() and _v not in all_voices:
                    all_voices.append(_v)
        dialog = AutoConcatConfigDialog(
            self,
            getattr(self, "sb_auto_concat_settings", None),
            voice_paths=all_voices,
        )
        if dialog.exec() == QDialog.DialogCode.Accepted:
            self.sb_auto_concat_settings = dialog.result_settings
            self._sb_log("⚙ Đã lưu cấu hình nối video tự động thành công!")


    def _sb_run_render_for_card(self, card, sp, settings):
        """Render video final theo settings từ PreConcatDialog (gọi từ nút Render trên card)."""
        self._sb_log(f"[{card.edit_name.text()}] 🎬 Render thủ công — {len(settings['scenes'])} scenes...")
        self._sb_log(f"[{card.edit_name.text()}]   Hiệu ứng: {settings['transition']}")
        for s in settings["scenes"]:
            if s["trim_start"] > 0:
                self._sb_log(f"[{card.edit_name.text()}]   Cảnh {s['scene_number']}: cắt {s['trim_start']}s đầu")
        
        card.set_status("generating", "Đang render...")
        card.btn_render.setEnabled(False)
        
        worker = FFmpegConcatWorker(sp, concat_settings=settings)
        worker.log_signal.connect(self._sb_log)

        def on_ok(final_path, _card=card, _sp=sp):
            _sp.final_video_path = final_path
            _sp.status = "done"
            _card.set_status("done")
            _card.btn_render.setEnabled(True)
            self._sb_log(f"[{_card.edit_name.text()}] ✅ Render xong! Final: {Path(final_path).name}")
            self.proj_mgr.save_story_projects()

        def on_err(msg, _card=card, _sp=sp):
            _card.set_status("done")
            _card.btn_render.setEnabled(True)
            self._sb_log(f"[{_card.edit_name.text()}] ⚠️ Render lỗi: {msg}")
            self._sb_log(f"[{_card.edit_name.text()}] → Videos riêng lẻ vẫn có trong thư mục output.")

        worker.concat_ready.connect(on_ok)
        worker.error_signal.connect(on_err)
        card.active_worker = worker
        worker.start()

    def _sb_retry_card(self, card, sp):
        """Retry failed scenes cho một product card — gọi từ nút 'Render lại' trên card."""
        card._story_project = sp
        sp.status = "generating"
        
        if card not in self._sb_active_cards:
            self._sb_active_cards.append(card)

        # Giữ nguyên các thiết lập gốc của dự án khi chạy lại (sp.vid_model và sp.img_model đã được cập nhật từ dialog chọn model)
        if getattr(sp, "use_proxy", False):
            self._ensure_proxies_active()

        # Đếm scene cần retry
        waiting = [s for s in sp.scenes if s.status == "waiting"]
        self._sb_log(f"🔄 [{card.edit_name.text()}] Retry {len(waiting)} scene(s) với model img={sp.img_model}, vid={sp.vid_model}")
        
        # Update card UI cho scenes đang waiting
        for i, scene in enumerate(sp.scenes):
            if scene.status == "waiting":
                card.update_scene_status(i, "waiting", "Chờ retry...")
        card.set_status("running")
        card.update_scene_progress()
        
        # Save project state
        self.proj_mgr.save_story_projects()
        
        # Re-enable pipeline nếu chưa chạy 
        self._sb_running = True
        self._sb_paused = False
        
        # Cập nhật nút bấm giao diện chính
        self.sb_start_btn.setEnabled(False)
        self.sb_pause_btn.setEnabled(True)
        self.sb_pause_btn.setText("⏸ Tạm dừng")
        self.sb_clear_btn.setEnabled(False)
        self.sb_status_lbl.setText("⚙ Đang chạy...")
        
        # Dispatch scenes
        QTimer.singleShot(300, self._sb_dispatch_scenes)

    def _sb_rerun_all(self):
        """Reset TẤT CẢ phân cảnh về pending, backup video cũ, rồi chạy lại toàn bộ."""
        sps = getattr(self.proj_mgr, 'story_projects', [])
        if not sps:
            QMessageBox.information(self, "Trống", "Dự án chưa có sản phẩm nào!")
            return

        total_scenes = sum(len(sp.scenes) for sp in sps)
        reply = QMessageBox.question(
            self, "🔄 Chạy lại toàn bộ",
            f"Dự án có <b>{len(sps)} sản phẩm</b> và <b>{total_scenes} phân cảnh</b>.<br><br>"
            "• Video cũ sẽ được <b>đổi tên để giữ lại</b> (không xóa)<br>"
            "• Tất cả phân cảnh sẽ reset về <b>pending</b><br><br>"
            "Bạn có muốn tiếp tục?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return

        from datetime import datetime as _dt
        ts = _dt.now().strftime("%Y%m%d_%H%M%S")
        backed_up = 0

        for sp in sps:
            for scene in sp.scenes:
                # Backup video
                vp = scene.video_path
                if vp and Path(vp).exists() and Path(vp).is_file():
                    p = Path(vp)
                    bk = p.parent / f"{p.stem}_bk_{ts}{p.suffix}"
                    try:
                        p.rename(bk)
                        backed_up += 1
                    except Exception:
                        pass
                # Backup storyboard image
                ip = scene.storyboard_image_path
                if ip and Path(ip).exists() and Path(ip).is_file():
                    p = Path(ip)
                    bk = p.parent / f"{p.stem}_bk_{ts}{p.suffix}"
                    try:
                        p.rename(bk)
                    except Exception:
                        pass
                # Reset scene
                scene.status = "pending"
                scene.video_path = ""
                scene.storyboard_image_path = ""
                scene.video_options = []
                scene.selected_video_option = ""
                scene.error_msg = ""
            sp.status = "pending"
            sp.final_video_path = getattr(sp, 'final_video_path', '')

        self.proj_mgr.save_story_projects()

        # Refresh UI cards
        self._sb_clear_cards_ui()
        self._sb_load_saved_projects()

        QMessageBox.information(
            self, "✅ Sẵn sàng chạy lại",
            f"Đã backup {backed_up} video cũ (thêm đuôi _bk_{ts}).\n"
            f"Tổng {total_scenes} phân cảnh đã được reset về pending.\n\n"
            "Bấm ▶ Bắt đầu để chạy lại."
        )

    def _sb_rerun_failed(self):
        """Chỉ reset phân cảnh BỊ LỖI về waiting, giữ nguyên phân cảnh đã xong."""
        if self._sb_running:
            QMessageBox.warning(self, "Đang chạy", "Pipeline đang hoạt động, không thể chạy retry!")
            return

        self._sb_cards = [c for c in self._sb_cards if c and c._is_alive()]
        if not self._sb_cards:
            QMessageBox.information(self, "Trống", "Dự án chưa có sản phẩm nào!")
            return

        reset_count = 0
        needs_work = []

        for card in self._sb_cards:
            sp = getattr(card, '_story_project', None)
            if not sp:
                continue
            has_reset = False
            for i, scene in enumerate(sp.scenes):
                if scene.status in ("failed", "error"):
                    _has_img = scene.storyboard_image_path and Path(scene.storyboard_image_path).exists()
                    scene.status = "img_done" if _has_img else "pending"
                    scene.error_msg = ""
                    reset_count += 1
                    has_reset = True
                    # Cập nhật UI hàng scene trực tiếp không cần load lại
                    card.update_scene_status(i, "waiting", "Chờ video..." if _has_img else "Chờ ảnh...")
            
            if has_reset:
                sp.status = "generating"
                card.set_status("waiting", "Đang chờ...")
                needs_work.append(card)
            else:
                # Nếu card đã xong hoàn toàn thì bỏ qua, ngược lại vẫn cần xử lý tiếp
                if sp.status in ('done',) and sp.scenes and all(s.status == 'done' for s in sp.scenes):
                    continue
                needs_work.append(card)

        if reset_count == 0:
            QMessageBox.information(
                self, "Không có lỗi",
                "Không có phân cảnh nào đang bị lỗi!\n"
                "Tất cả đang ở trạng thái done hoặc pending."
            )
            return

        self.proj_mgr.save_story_projects()

        # Giữ nguyên thiết lập gốc của các dự án khi chạy lại phân cảnh lỗi, không ghi đè từ toolbar
        for card in needs_work:
            _sp = getattr(card, '_story_project', None)
            if _sp and getattr(_sp, "use_proxy", False):
                self._ensure_proxies_active()
                break
        self.proj_mgr.save_story_projects()

        # Kích hoạt pipeline
        self._sb_running = True
        self._sb_paused = False
        self._sb_pending_queue = needs_work
        self._sb_active_cards = []

        # Reset counters
        self._sb_active_chat_count = 0
        self._sb_active_img_count = 0
        self._sb_active_vid_count = 0
        self._sb_last_start_time = 0.0

        self.sb_start_btn.setEnabled(False)
        self.sb_pause_btn.setEnabled(True)
        self.sb_pause_btn.setText("⏸ Tạm dừng")
        self.sb_clear_btn.setEnabled(False)
        self.sb_status_lbl.setText("⚙ Đang chạy retry...")

        self._sb_log(f"🔄 Đã đưa {reset_count} phân cảnh lỗi vào hàng đợi retry.")
        self._sb_start_next_products()

    def _update_sb_available_models(self):
        pass

    def update_active_role_ui(self):
        if not hasattr(self, "sb_role_combo") or not hasattr(self, "sb_active_role_lbl"):
            return
        idx = self.sb_role_combo.currentIndex()
        if idx < 0:
            self.sb_active_role_lbl.setText("Chưa chọn")
            return
        text = self.sb_role_combo.itemText(idx)
        clean_text = text.replace("📄 ", "").replace("🎬 ", "").replace("🎥 ", "").replace("💄 ", "").replace("💻 ", "").replace("📱 ", "")
        self.sb_active_role_lbl.setText(clean_text)

    def _refresh_role_combo(self):
        self.sb_role_combo.blockSignals(True)
        self.sb_role_combo.clear()
        if getattr(self, '_sb_roleskill_mode', False):
            # Role Skill mode: show only custom MD role skills
            for f in ProjectManager.list_role_skill_files():
                display_name = f"📄 {Path(f).stem}"
                existing = [self.sb_role_combo.itemData(i) for i in range(self.sb_role_combo.count())]
                if f not in existing:
                    self.sb_role_combo.addItem(display_name, f)
        else:
            # Storyboard mode: show only default storyboard rules
            for rs in self.proj_mgr.role_skills:
                self.sb_role_combo.addItem(rs["name"], rs["id"])
        self.sb_role_combo.blockSignals(False)
        self.update_active_role_ui()

    def _on_sb_role_changed(self, index):
        if index < 0:
            if hasattr(self, "sb_active_role_lbl"):
                self.sb_active_role_lbl.setText("Chưa chọn")
            return
        self.update_active_role_ui()
        role_file = self.sb_role_combo.itemData(index)
        text = self.sb_role_combo.itemText(index)
        self._sb_log(f"🎭 Đã chọn Role Skill: {text}")
        
        # Cập nhật cho tất cả sản phẩm trong dự án hiện tại
        if getattr(self, '_sb_roleskill_mode', False) and role_file:
            # Lưu lại vào Project hiện tại
            if hasattr(self.proj_mgr, "current_project_id") and self.proj_mgr.current_project_id:
                curr_proj = next((p for p in self.proj_mgr.projects if p.id == self.proj_mgr.current_project_id), None)
                if curr_proj:
                    curr_proj.role_skill_file = role_file
                    self.proj_mgr.save()

            rs_path = get_role_skill_path(role_file)
            if rs_path and rs_path.exists():
                try:
                    content = rs_path.read_text(encoding="utf-8")
                    updated_count = 0
                    for card in self._sb_cards:
                        sp = getattr(card, '_story_project', None)
                        if sp:
                            sp.role_skill_file = role_file
                            sp.system_prompt_override = content
                            updated_count += 1
                    if updated_count > 0:
                        self._sb_log(f"   → Đã cập nhật Role Skill cho {updated_count} sản phẩm.")
                        self.proj_mgr.save_story_projects()
                except Exception as e:
                    self._sb_log(f"⚠️ Lỗi cập nhật Role Skill: {e}")

    def _sb_log(self, msg: str):
        from datetime import datetime
        ts = datetime.now().strftime("%H:%M:%S")
        colored = (
            f'<span style="color:#475569;">[{ts}]</span> '
            f'<span style="color:#e2e8f0;">{msg}</span>'
        )
        self.sb_log_txt.append(colored)
        self.sb_log_txt.moveCursor(self.sb_log_txt.textCursor().MoveOperation.End)

    def show_role_skills_dialog(self):
        if getattr(self, '_sb_roleskill_mode', False):
            dialog = RoleSkillsMDDialog(self, self.proj_mgr)
        else:
            dialog = RoleSkillsDialog(self, self.proj_mgr)
        if dialog.exec():
            self._refresh_role_combo()

