    # ─────────────────── PANEL WRAPPERS (QSS Card + Console) ───────────────────
    def create_panel_layout(self, title_txt: str, icon_txt: str) -> tuple:
        panel_w = QWidget()
        lay = QVBoxLayout(panel_w)
        lay.setContentsMargins(20, 15, 20, 15)
        lay.setSpacing(10)

        # Header
        h_frame = QWidget()
        h_lay = QHBoxLayout(h_frame)
        h_lay.setContentsMargins(0, 0, 0, 0)
        h_title = QLabel(f"{icon_txt}  {title_txt}", styleSheet="font-size: 22px; font-weight: bold;")
        h_lay.addWidget(h_title)
        
        n_accs = len(self.acc_mgr.active)
        h_accs = QLabel(f"⚡ {n_accs} tài khoản")
        h_accs.setStyleSheet("color: #7c3aed; font-weight: bold;")
        h_lay.addWidget(h_accs, alignment=Qt.AlignmentFlag.AlignRight)
        lay.addWidget(h_frame)

        # Form Scroll area
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setObjectName("form_scroll")
        scroll.setStyleSheet("QScrollArea#form_scroll { border: 1px solid #e2e8f0; border-radius: 12px; background-color: #f8fafc; }")
        
        form_w = QWidget()
        form_w.setObjectName("card_body")
        form_w.setStyleSheet("QWidget#card_body { background-color: #f8fafc; }")
        form_lay = QVBoxLayout(form_w)
        form_lay.setContentsMargins(20, 20, 20, 20)
        form_lay.setSpacing(12)
        
        scroll.setWidget(form_w)
        lay.addWidget(scroll, stretch=1)

        # Console text edit
        console_w = QFrame()
        console_w.setObjectName("card")
        console_w.setFixedHeight(160)
        c_lay = QVBoxLayout(console_w)
        c_lay.setContentsMargins(12, 8, 12, 8)
        c_lay.addWidget(QLabel("📋 Nhật ký Console Output", styleSheet="font-size: 10px; font-weight: bold; color: #64748b;"))
        
        console_box = QTextEdit()
        console_box.setReadOnly(True)
        console_box.setStyleSheet("font-family: 'Cascadia Code', 'Courier New', monospace; font-size: 11px; background-color: #ffffff; border: 1px solid #cbd5e1;")
        c_lay.addWidget(console_box)
        lay.addWidget(console_w)

        return panel_w, form_lay, console_box

