    def create_settings_row(self, layout) -> tuple:
        row_widget = QWidget()
        r_lay = QHBoxLayout(row_widget)
        r_lay.setContentsMargins(0, 0, 0, 0)
        r_lay.setSpacing(10)

        # Duration widget (custom wrapper supporting both slider & flow combo)
        dur_widget = DurationWidget()
        r_lay.addWidget(dur_widget, stretch=1)

        # Resolution
        res_frame = QWidget()
        res_lay = QVBoxLayout(res_frame)
        res_lay.setContentsMargins(0, 0, 0, 0)
        res_lay.addWidget(QLabel("📐 Độ phân giải", styleSheet="font-size: 11px;"))
        res_combo = QComboBox()
        res_combo.addItems(["480p", "720p", "1080p"])
        res_combo.setCurrentText(DEFAULT_RESOLUTION)
        res_lay.addWidget(res_combo)
        r_lay.addWidget(res_frame, stretch=1)

        # Aspect
        asp_frame = QWidget()
        asp_lay = QVBoxLayout(asp_frame)
        asp_lay.setContentsMargins(0, 0, 0, 0)
        asp_lay.addWidget(QLabel("📏 Tỉ lệ khung hình", styleSheet="font-size: 11px;"))
        asp_combo = QComboBox()
        asp_combo.addItems(["16:9", "9:16", "1:1", "4:3"])
        asp_combo.setCurrentText(DEFAULT_ASPECT)
        asp_lay.addWidget(asp_combo)
        r_lay.addWidget(asp_frame, stretch=1)

        # Model
        mod_frame = QWidget()
        mod_lay = QVBoxLayout(mod_frame)
        mod_lay.setContentsMargins(0, 0, 0, 0)
        mod_lay.addWidget(QLabel("🤖 Mô hình (Model)", styleSheet="font-size: 11px;"))
        mod_combo = QComboBox()
        mod_combo.addItems([
            "grok-imagine-video", "grok-imagine-video-1.5-preview",
            "Veo 3.1 - Lite [Lower Priority]", "Veo 3.1 - Lite", "Veo 3.1 - Fast", "Veo 3.1 - Quality", "Omni Flash"
        ])
        mod_combo.setCurrentText(DEFAULT_MODEL)
        mod_lay.addWidget(mod_combo)
        r_lay.addWidget(mod_frame, stretch=1)

        def update_ui_for_model(model_text):
            is_veo = is_veo_model(model_text)
            is_banana = "banana" in model_text.lower()
            is_grok = "grok" in model_text.lower()
            is_codex = "gpt" in model_text.lower() or "dall-e" in model_text.lower() or "codex" in model_text.lower()

            # Duration Visibility & Mode
            if is_banana or is_codex:
                dur_widget.setMode("hidden")
            elif is_veo:
                dur_widget.setMode("combo")
                if "omni flash" in model_text.lower() or "omni_flash" in model_text.lower() or model_text == "Omni Flash":
                    dur_widget.setComboItems(["4 giây", "6 giây", "8 giây", "10 giây"])
                else:
                    dur_widget.setComboItems(["4 giây", "6 giây", "8 giây"])
            else:
                dur_widget.setMode("slider")

            # Resolution Visibility
            if is_veo or is_banana or is_codex:
                res_frame.hide()
            else:
                res_frame.show()

            # Aspect Ratio options
            current_aspect = asp_combo.currentText()
            asp_combo.blockSignals(True)
            asp_combo.clear()
            if is_codex:
                asp_combo.addItems(["1:1", "16:9", "9:16"])
            elif is_veo or is_banana:
                asp_combo.addItems(["16:9", "9:16", "1:1", "4:3", "21:9"])
            else:
                asp_combo.addItems(["16:9", "9:16", "1:1", "4:3", "3:4", "21:9"])
            
            idx = asp_combo.findText(current_aspect)
            if idx != -1:
                asp_combo.setCurrentIndex(idx)
            else:
                asp_combo.setCurrentText("16:9")
            asp_combo.blockSignals(False)

        mod_combo.currentTextChanged.connect(update_ui_for_model)
        # Trigger default UI update
        update_ui_for_model(DEFAULT_MODEL)

        layout.addWidget(row_widget)
        return dur_widget, res_combo, asp_combo, mod_combo

    def log_to_console(self, box: QTextEdit, msg: str):
        box.append(f"[{datetime.now().strftime('%H:%M:%S')}] {msg}")
        box.moveCursor(box.textCursor().MoveOperation.End)

    def run_single_job_bg(self, job: VideoJob, console_box: QTextEdit, progress_bar: QProgressBar):
        is_veo = is_veo_model(job.model)
        
        if is_veo:
            v_acc = self.next_veo_account()
            if not v_acc:
                self.log_to_console(console_box, "❌ Không tìm thấy cấu hình Google Flow! Hãy thêm tài khoản Google hoặc cấu hình token trong Settings.")
                return
            
            job.account_name = v_acc.name
            job.google_profile_name = _google_profile_name_for_account(v_acc)
            progress_bar.setValue(0)
            self.log_to_console(console_box, f"🚀 Job {job.id} bắt đầu qua Google AI Sandbox [{v_acc.name}]...")
            
            worker = JobWorker(job, None)
            worker.veo_bearer = v_acc.api_key
            worker.veo_project_id = v_acc.proxy_url
            worker.captcha_bridge = getattr(self, "captcha_bridge", None)
            
            worker.log_sig.connect(lambda msg: self.log_to_console(console_box, msg))
            worker.progress_sig.connect(lambda jid, val: progress_bar.setValue(int(val * 100)))
            
            def on_done(jid, status, path_err):
                job.status = status
                self.history.insert(0, job)
                self.save_history_to_disk()
                self.refresh_sidebar_acc_lbl()
                if status == "done":
                    self.extract_thumbnail_pyqt(jid, job.local_path)
                self.active_workers.pop(jid, None)
                self.refresh_gallery_ui()

            worker.status_sig.connect(on_done)
            self.active_workers[job.id] = worker
            worker.start()
            return

        acc = self.acc_mgr.next_for_model(job.model)
        if not acc:
            self.log_to_console(console_box, "❌ Chưa có tài khoản nào hoạt động! Cấu hình trong tab Accounts.")
            return
        
        job.account_name = acc.name
        client = GrokClient(acc.proxy_url, acc.api_key)

        progress_bar.setValue(0)
        self.log_to_console(console_box, f"🚀 Job {job.id} bắt đầu → account [{acc.name}]")

        worker = JobWorker(job, client)
        
        # Connect signals thread-safely
        worker.log_sig.connect(lambda msg: self.log_to_console(console_box, msg))
        worker.progress_sig.connect(lambda jid, val: progress_bar.setValue(int(val * 100)))
        
        def on_done(jid, status, path_err):
            self.history.insert(0, job)
            self.save_history_to_disk()
            self.refresh_sidebar_acc_lbl()
            if status == "done":
                # Trích xuất thumbnail
                self.extract_thumbnail_pyqt(jid, job.local_path)
            self.active_workers.pop(jid, None)

        worker.status_sig.connect(on_done)
        
        self.active_workers[job.id] = worker
        worker.start()

