        comp_slider.valueChanged.connect(lambda v: comp_lbl.setText(f"🗜️ Độ nén (Compression): {v}%"))
        comp_lay.addWidget(comp_lbl, stretch=1)
        comp_lay.addWidget(comp_slider, stretch=2)
        lay.addWidget(comp_widget)

        # Progress bar
        pb = QProgressBar()
        pb.setValue(0)
        lay.addWidget(pb)

        # Action btn
        btn = QPushButton("🎨  Bắt Đầu Tạo Ảnh")
        btn.setObjectName("accent_btn")
        btn.setFixedHeight(45)

        def run():
            p = tb.toPlainText().strip()
            if not p:
                return QMessageBox.warning(self, "⚠️", "Nhập prompt tạo ảnh!")

            save_path = out_e.text().strip()
            if not save_path:
                return QMessageBox.warning(self, "⚠️", "Chọn nơi lưu ảnh đầu ra!")
            
            target_path = Path(save_path)
            out_folder_val = target_path.parent
            out_name_val = target_path.stem

            selected_model = mod_combo.currentText()
            is_veo = is_veo_model(selected_model)
            allowed_accs = []
            if not is_veo:
                # Filter accounts only for proxy-based image models.  Veo and
                # Banana use the separately selected Google Flow profile.
                is_codex_model = "gpt-image" in selected_model
                required_prefix = "Codex" if is_codex_model else "Grok"
                allowed_accs = [
                    a for a in self.acc_mgr.active if a.name.startswith(required_prefix)
                ]
                if not allowed_accs:
                    self.log_to_console(console, f"❌ Chưa có tài khoản {required_prefix} nào hoạt động! Hãy cấu hình/bật tài khoản {required_prefix} trong tab Quản Lý Tài Khoản.")
                    return QMessageBox.warning(self, "⚠️", f"Chưa có tài khoản {required_prefix} nào hoạt động để chạy model {selected_model}!")
            
            if is_veo:
                v_acc = self.next_veo_account()
                if not v_acc:
                    self.log_to_console(console, "❌ Không tìm thấy cấu hình Google Flow! Cấu hình trong Accounts/Settings.")
                    return QMessageBox.warning(self, "⚠️", "Chưa cấu hình tài khoản Google Flow!")
                
                job = VideoJob(
                    id=f"img_{uuid.uuid4().hex[:6]}",
                    mode="image-generation",
                    prompt=p,
                    output_name=out_name_val,
                    local_path=str(target_path),
                    model=selected_model,
                    resolution=size_combo.currentText(),
                    account_name=v_acc.name,
                    google_profile_name=_google_profile_name_for_account(v_acc),
                )
                pb.setValue(0)
                self.log_to_console(console, f"🚀 Bắt đầu tạo ảnh {job.id} qua Google AI Sandbox [{v_acc.name}]...")
                
                worker = ImageGenWorker(
                    client=None,
                    prompt=p,
                    model=job.model,
                    size=job.resolution,
                    quality=qual_combo.currentText(),
                    output_format=fmt_combo.currentText(),
                    output_compression=int(comp_slider.value()),
                    background=bg_combo.currentText(),
                    moderation=mod_filter_combo.currentText(),
                    output_name=job.output_name,
                    out_folder=out_folder_val
                )
                worker.veo_bearer = v_acc.api_key
                worker.veo_project_id = v_acc.proxy_url
                worker.google_account_name = v_acc.name
                worker.google_profile_name = _google_profile_name_for_account(v_acc)
                worker.captcha_bridge = getattr(self, "captcha_bridge", None)
                
                worker.log_sig.connect(lambda msg: self.log_to_console(console, msg))
                
                def on_done(jid, status, path_err):
                    job.status = status
                    if status == "done":
                        job.local_path = path_err
                        pb.setValue(100)
                        self.log_to_console(console, f"✅ Hoàn tất tải ảnh thành công -> {Path(path_err).name}")
                    else:
                        job.error = path_err
                        pb.setValue(0)
                        self.log_to_console(console, f"❌ Lỗi: {path_err}")
                    self.history.insert(0, job)
                    self.save_history_to_disk()
                    self.refresh_gallery_ui()
                
                worker.status_sig.connect(on_done)
                worker.start()
                return

            if not hasattr(self, "_imggen_acc_idx"):
                self._imggen_acc_idx = 0
            acc = allowed_accs[self._imggen_acc_idx % len(allowed_accs)]
            self._imggen_acc_idx += 1
            acc.jobs_done += 1
            self.acc_mgr.save()
            
            # Create a VideoJob representation for history
            job = VideoJob(
                id=f"img_{uuid.uuid4().hex[:6]}",
                mode="image-generation",
                prompt=p,
                output_name=out_name_val,
                local_path=str(target_path),
                model=mod_combo.currentText(),
                resolution=size_combo.currentText(),
                account_name=acc.name
            )

            client = GrokClient(acc.proxy_url, acc.api_key)
            pb.setValue(0)
            self.log_to_console(console, f"🚀 Bắt đầu tạo ảnh {job.id} qua tài khoản [{acc.name}]...")
            
            # Start worker thread
            worker = ImageGenWorker(
                client=client,
                prompt=p,
                model=job.model,
                size=job.resolution,
                quality=qual_combo.currentText(),
                output_format=fmt_combo.currentText(),
                output_compression=int(comp_slider.value()),
                background=bg_combo.currentText(),
                moderation=mod_filter_combo.currentText(),
                output_name=job.output_name,
                out_folder=out_folder_val
            )
            
            worker.log_sig.connect(lambda msg: self.log_to_console(console, msg))
            
            def on_done(jid, status, path_err):
                job.status = status
                if status == "done":
                    job.local_path = path_err
                    pb.setValue(100)
                    self.log_to_console(console, f"✅ Hoàn tất tải ảnh thành công -> {Path(path_err).name}")
                else:
                    job.error = path_err
                    pb.setValue(0)
                    self.log_to_console(console, f"❌ Thất bại: {path_err}")
                
                self.history.insert(0, job)
                self.save_history_to_disk()
                self.refresh_sidebar_acc_lbl()
                self.active_workers.pop(jid, None)

            worker.status_sig.connect(on_done)
            self.active_workers[job.id] = worker
            worker.start()

        btn.clicked.connect(run)
        lay.addWidget(btn)
        self.stacked_widget.addWidget(panel)

