    def eventFilter(self, obj, event):
        # Override bộ lọc cuộn chuột (Ctrl + Wheel)
        if hasattr(self, "gallery_scroll") and obj == self.gallery_scroll.viewport():
            if event.type() == event.Type.Wheel:
                if event.modifiers() == Qt.KeyboardModifier.ControlModifier:
                    delta = event.angleDelta().y()
                    if delta > 0:
                        self.zoom_in_gallery()
                    else:
                        self.zoom_out_gallery()
                    event.accept()
                    return True
        return super().eventFilter(obj, event)

    def zoom_in_gallery(self):
        self.zoom_factor = min(2.0, self.zoom_factor + 0.1)
        self.refresh_gallery_ui()

    def zoom_out_gallery(self):
        self.zoom_factor = max(0.5, self.zoom_factor - 0.1)
        self.refresh_gallery_ui()

    # ── MODEL CAPABILITY MATRIX ──────────────────────────────────────
    # Model video (Grok/xAI)
    #   grok-imagine-video      → T2V ✓ I2V ✓ Ref(≤7) ✓ Edit ✓ Extend ✓
    #   grok-imagine-video-1.5  → T2V ✓ I2V ✓ Ref(≤7) ✓ Edit ✓ Extend ✓ (tốt hơn)
    # Model ảnh
    #   gpt-image-1             → T2I ✓ I2I ✓ (Codex account) ref≤1
    #   gpt-image-2             → T2I ✓ I2I ✓ (Codex account) ref≤1  [default]
    #   grok-imagine-image      → T2I ✓ I2I ✓ (Grok account)  ref≤3
    # ────────────────────────────────────────────────────────────────
    _MODEL_INFO = {
        "grok-imagine-video":             "📌 T2V · I2V · Ref≤7 · Edit · Extend  |  Tài khoản: Grok",
        "grok-imagine-video-1.5-preview": "📌 T2V · I2V · Ref≤7 · Edit · Extend  |  Tài khoản: Grok (khuyến nghị)",
        "gpt-image-1.5":                  "📌 T2I · I2I(ref≤1)  |  Tài khoản: Codex (ChatGPT Plus)",
        "gpt-image-2":                    "📌 T2I · I2I(ref≤1)  |  Tài khoản: Codex (ChatGPT Plus) [mặc định]",
        "grok-imagine-image":             "📌 T2I  |  Tài khoản: Grok",
        "grok-imagine-image-quality":     "📌 T2I (High Quality)  |  Tài khoản: Grok",
    }

    def on_batch_mode_changed(self, text):
        val_map = {
            "📝  Chữ → Video": "text-to-video",
            "🖼️  Ảnh → Video": "image-to-video",
            "🎨  Ảnh Tham Chiếu": "reference-to-video",
            "✏️  Chỉnh Sửa Video": "edit-video",
            "⏩  Kéo Dài Video": "extend-video",
            "📸  Chữ → Ảnh": "image-generation",
            "🖼️  Ảnh → Ảnh (Sửa ảnh)": "image-to-image"
        }
        self.selected_mode = val_map.get(text, "text-to-video")

        # Update model list based on mode (Image vs Video)
        self.b_model_combo.blockSignals(True)
        if self.selected_mode in ("image-generation", "image-to-image"):
            self.b_model_combo.clear()
            if self.selected_mode == "image-to-image":
                # Only show image models that allow uploading reference images (OpenAI Codex)
                self.b_model_combo.addItems(["gpt-image-2", "gpt-image-1.5"])
                self.b_model_combo.setCurrentText("gpt-image-2")
            else:
                # Text-to-image can use all image models
                self.b_model_combo.addItems([
                    "gpt-image-2", "gpt-image-1.5", 
                    "grok-imagine-image", "grok-imagine-image-quality",
                    "Nano Banana Pro", "Nano Banana 2", "Nano Banana 2 Lite"
                ])
                self.b_model_combo.setCurrentText("gpt-image-2")
        else:
            self.b_model_combo.clear()
            self.b_model_combo.addItems([
            "grok-imagine-video", "grok-imagine-video-1.5-preview",
            "Veo 3.1 - Lite [Lower Priority]", "Veo 3.1 - Lite", "Veo 3.1 - Fast", "Veo 3.1 - Quality", "Omni Flash",
        ])
            if self.selected_mode in ("image-to-video", "reference-to-video"):
                self.b_model_combo.setCurrentText("grok-imagine-video-1.5-preview")
            else:
                self.b_model_combo.setCurrentText("grok-imagine-video")
        self.b_model_combo.blockSignals(False)
        self._update_model_info_lbl()

        # Clear dynamic layout
        for widget in self.b_dynamic_container.findChildren(QWidget):
            widget.setParent(None)

        # Re-build dynamic widget depending on mode
        if self.selected_mode in ("image-to-video", "image-to-image"):
            label_text = "🖼️ ẢNH GỐC THAM CHIẾU" if self.selected_mode == "image-to-image" else "🖼️ ẢNH ĐẦU VÀO MẪU"
            self.b_dyn_lay.addWidget(QLabel(label_text, styleSheet="font-size: 11px; font-weight: bold; color: #64748b;"))
            row = QWidget()
            row_lay = QHBoxLayout(row)
            row_lay.setContentsMargins(0, 0, 0, 0)
            self.b_img_path = QLineEdit(placeholderText="Chọn ảnh mẫu cục bộ...")
            row_lay.addWidget(self.b_img_path)

            def browse():
                p, _ = QFileDialog.getOpenFileName(self, "Chọn ảnh đầu vào", "", "Images (*.jpg *.jpeg *.png *.webp)")
                if p: self.b_img_path.setText(p)

            btn = QPushButton("📂")
            btn.setObjectName("normal_btn")
            btn.setFixedWidth(36)
            btn.clicked.connect(browse)
            row_lay.addWidget(btn)
            self.b_dyn_lay.addWidget(row)

        elif self.selected_mode == "reference-to-video":
            self.b_dyn_lay.addWidget(QLabel(
                "🎨 ẢNH THAM CHIẾU (tối đa 7 ảnh, mỗi dòng 1 link hoặc đường dẫn)",
                styleSheet="font-size: 10px; font-weight: bold; color: #64748b;"))
            self.b_ref_urls = QTextEdit()
            self.b_ref_urls.setPlaceholderText("https://... hoặc C:/path/to/image.jpg\nhttps://...")
            self.b_ref_urls.setFixedHeight(72)
            self.b_dyn_lay.addWidget(self.b_ref_urls)

        elif self.selected_mode in ("edit-video", "extend-video"):
            self.b_dyn_lay.addWidget(QLabel("🎥 URL VIDEO ĐẦU VÀO (mp4)", styleSheet="font-size: 11px; font-weight: bold; color: #64748b;"))
            self.b_vid_url = QLineEdit(placeholderText="Nhập link video mp4...")
            self.b_dyn_lay.addWidget(self.b_vid_url)

    def _update_model_info_lbl(self):
        if not hasattr(self, "b_model_info_lbl"):
            return
        model = self.b_model_combo.currentText() if hasattr(self, "b_model_combo") else ""
        info = self._MODEL_INFO.get(model, "")
        self.b_model_info_lbl.setText(info)

