    def add_prompts_to_draft(self):
        prompts_raw = self.b_prompt_text.toPlainText().strip()
        prompts = [p.strip() for p in prompts_raw.split("\n") if p.strip()]
        if not prompts:
            return QMessageBox.warning(self, "Cảnh báo", "Vui lòng nhập danh sách prompts!")

        # Dynamic sample input configuration
        sample_img = None
        sample_refs = []
        sample_vid = None
        if self.selected_mode == "image-to-video" and hasattr(self, "b_img_path"):
            sample_img = self.b_img_path.text().strip()
        elif self.selected_mode == "reference-to-video" and hasattr(self, "b_ref_urls"):
            sample_refs = [u.strip() for u in self.b_ref_urls.toPlainText().strip().split("\n") if u.strip()]
        elif self.selected_mode in ("edit-video", "extend-video") and hasattr(self, "b_vid_url"):
            sample_vid = self.b_vid_url.text().strip()

        for prompt in prompts:
            j_id = f"job_{uuid.uuid4().hex[:6]}"
            job = VideoJob(
                id=j_id,
                mode=self.selected_mode,
                prompt=prompt,
                model=self.b_model_combo.currentText(),
                resolution=DEFAULT_RESOLUTION,
                aspect_ratio=self.selected_ratio,
                duration=DEFAULT_DURATION,
                image_url=sample_img,
                reference_image_urls=sample_refs.copy(),
                video_url=sample_vid,
                status="draft"
            )
            self.history.insert(0, job)

        self.b_prompt_text.clear()
        self.update_batch_prompts_count()
        self.save_history_to_disk()
        self.refresh_gallery_ui()
        self.log_global(f"➕ Đã thêm {len(prompts)} prompts vào danh sách Bản thảo.")

    def assign_images_to_drafts(self):
        paths, _ = QFileDialog.getOpenFileNames(self, "Chọn ảnh hàng loạt", "", "Images (*.jpg *.jpeg *.png *.webp)")
        if not paths:
            return

        # Lấy các bản thảo từ cũ nhất đến mới nhất
        drafts = [j for j in self.history if j.status == "draft"]
        drafts.reverse()

        if not drafts:
            return QMessageBox.warning(self, "Cảnh báo", "Không tìm thấy Bản thảo nào để gán ảnh!")

        assigned = 0
        for idx, path in enumerate(paths):
            if idx < len(drafts):
                job = drafts[idx]
                if job.mode == "reference-to-video":
                    # Ở chế độ ảnh tham chiếu, gán làm ảnh tham chiếu đầu tiên
                    job.reference_image_urls = [path]
                else:
                    job.image_url = path
                assigned += 1

        self.save_history_to_disk()
        self.refresh_gallery_ui()
        QMessageBox.information(self, "Thành công", f"Đã gán {assigned} ảnh cho các Bản thảo theo thứ tự.")

    def choose_image_for_job(self, job: VideoJob):
        p, _ = QFileDialog.getOpenFileName(self, "Chọn ảnh đầu vào", "", "Images (*.jpg *.jpeg *.png *.webp)")
        if p:
            if job.mode == "reference-to-video":
                job.reference_image_urls = [p]
            else:
                job.image_url = p
            self.save_history_to_disk()
            self.refresh_gallery_ui()

    def add_ref_image_for_job(self, job: VideoJob):
        p, _ = QFileDialog.getOpenFileName(self, "Thêm ảnh tham chiếu", "", "Images (*.jpg *.jpeg *.png *.webp)")
        if p:
            job.reference_image_urls.append(p)
            self.save_history_to_disk()
            self.refresh_gallery_ui()

    def refresh_queue_ui(self):
        for i in reversed(range(self.queue_scroll_lay.count())):
            item = self.queue_scroll_lay.itemAt(i).widget()
            if item: item.setParent(None)

        active_jobs = [j for j in self.queue if j.status in ("pending", "submitted", "polling", "scheduled")]
        if not active_jobs:
            lbl = QLabel("Hàng đợi trống", styleSheet="color: #94a3b8; font-style: italic; text-align: center;")
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.queue_scroll_lay.addWidget(lbl)
            return

        for idx, job in enumerate(active_jobs):
            q_card = QFrame()
            q_card.setObjectName("card")
            q_card.setStyleSheet("QFrame#card { background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; }")
            q_lay = QVBoxLayout(q_card)
            q_lay.setContentsMargins(8, 8, 8, 8)
            q_lay.setSpacing(4)

            # Header row
            h_row = QWidget()
            hr_lay = QHBoxLayout(h_row)
            hr_lay.setContentsMargins(0, 0, 0, 0)
            
            id_lbl = QLabel(f"#{job.id}", styleSheet="font-weight: bold; color: #7c3aed;")
            hr_lay.addWidget(id_lbl)

            pct = int(job.progress_val * 100)
            status_text = f"{pct}% hoàn" if job.status == "polling" else ("Đang chờ" if job.status == "pending" else "Đang gửi...")
            status_color = "#7c3aed" if job.status == "polling" else "#64748b"
            status_lbl = QLabel(status_text, styleSheet=f"font-weight: bold; color: {status_color}; font-size: 11px;")
            hr_lay.addWidget(status_lbl, alignment=Qt.AlignmentFlag.AlignCenter)

            cancel_btn = QPushButton("✕")
            cancel_btn.setFixedSize(20, 20)
            cancel_btn.setStyleSheet("background-color: transparent; border: none; font-weight: bold; color: #ef4444;")
            def make_cancel(jid=job.id):
                return lambda: self.cancel_queued_job(jid)
            cancel_btn.clicked.connect(make_cancel(job.id))
            hr_lay.addWidget(cancel_btn, alignment=Qt.AlignmentFlag.AlignRight)
            q_lay.addLayout(hr_lay)

            info = QLabel(f"Tài khoản: {job.account_name or 'Đang gán...'}\nPrompt: {job.prompt[:25]}...", styleSheet="color: #64748b; font-size: 10px;")
            q_lay.addWidget(info)

            pb = QProgressBar()
            pb.setFixedHeight(4)
            pb.setTextVisible(False)
            pb.setValue(pct)
            q_lay.addWidget(pb)

            self.queue_scroll_lay.addWidget(q_card)
        self.queue_scroll_lay.addStretch()

    def cancel_queued_job(self, job_id):
        worker = self.active_workers.pop(job_id, None)
        if worker:
            try: worker.terminate()
            except Exception: pass

        for j in self.queue:
            if j.id == job_id:
                j.status = "failed"
                j.error = "Bị hủy bởi người dùng"
                self.queue.remove(j)
                if j not in self.history:
                    self.history.insert(0, j)
                self.save_history_to_disk()
                self.refresh_queue_ui()
                self.refresh_gallery_ui()
                break

    def switch_gallery_tab(self, tab):
        self.active_tab = tab
        for btn, k in ((self.b_tab_all, "all"), (self.b_tab_draft, "draft"), (self.b_tab_done, "done"), (self.b_tab_failed, "failed")):
            btn.setProperty("active", "true" if k == tab else "false")
            btn.style().unpolish(btn)
            btn.style().polish(btn)
        self.refresh_gallery_ui()

    def set_gallery_view(self, val):
        self.gallery_view = val
        self.b_btn_grid.setProperty("active", "true" if val == "grid" else "false")
        self.b_btn_grid.style().unpolish(self.b_btn_grid)
        self.b_btn_grid.style().polish(self.b_btn_grid)

        self.b_btn_list.setProperty("active", "true" if val == "list" else "false")
        self.b_btn_list.style().unpolish(self.b_btn_list)
        self.b_btn_list.style().polish(self.b_btn_list)

        self.refresh_gallery_ui()

    def set_gallery_cols(self, cols):
        self.gallery_columns = cols
        for k, btn in self.col_buttons.items():
            btn.setProperty("active", "true" if k == cols else "false")
            btn.style().unpolish(btn)
            btn.style().polish(btn)
        self.refresh_gallery_ui()

    def _get_filtered_sorted_jobs(self) -> list:
        """Returns history filtered by active tab, search text, sorted by sort_order."""
        # 1. Tab filter
        tab = self.active_tab
        if tab == "draft":
            filtered = [j for j in self.history if j.status == "draft"]
        elif tab == "done":
            filtered = [j for j in self.history if j.status == "done"]
        elif tab == "failed":
            filtered = [j for j in self.history if j.status == "failed"]
        else:
            filtered = list(self.history)

        # 2. Search filter
        q = getattr(self, "gallery_search_text", "")
        if q:
            filtered = [j for j in filtered if q in j.prompt.lower()
                        or q in (j.id or "").lower()
                        or q in (j.account_name or "").lower()]

        # 3. Sort
        order = getattr(self, "gallery_sort_order", "newest")
        status_rank = {"pending": 0, "submitted": 0, "polling": 0, "scheduled": 0,
                       "draft": 1, "failed": 2, "done": 3}
        if order == "oldest":
            filtered = list(reversed(filtered))
        elif order == "status":
            filtered.sort(key=lambda j: status_rank.get(j.status, 9))

        return filtered

    def refresh_gallery_ui(self):
        # 1. Update tab counts (always from full history)
        all_c   = len(self.history)
        draft_c = sum(1 for j in self.history if j.status == "draft")
        done_c  = sum(1 for j in self.history if j.status == "done")
        fail_c  = sum(1 for j in self.history if j.status == "failed")

        self.b_tab_all.setText(f"Tất cả ({all_c})")
        self.b_tab_draft.setText(f"Bản thảo ({draft_c})")
        self.b_tab_done.setText(f"Hoàn thành ({done_c})")
        self.b_tab_failed.setText(f"Thất bại ({fail_c})")

        # 2. Clear grid
        for i in reversed(range(self.gallery_grid.count())):
            item = self.gallery_grid.itemAt(i).widget()
            if item: item.setParent(None)

        # 3. Get filtered + sorted list
        filtered = self._get_filtered_sorted_jobs()

        if not filtered:
            q = getattr(self, "gallery_search_text", "")
            msg = f"Không tìm thấy kết quả cho \"{q}\"" if q else "Danh sách trống"
            lbl = QLabel(msg, styleSheet="color: #94a3b8; font-style: italic;")
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.gallery_grid.addWidget(lbl, 0, 0)
            return

        # 4. Render cards
        cols = 1 if self.gallery_view == "list" else self.gallery_columns
        for idx, job in enumerate(filtered):
            card = self.create_gallery_card_pyqt(job)
            row = idx // cols
            col = idx % cols
            self.gallery_grid.addWidget(card, row, col)

        # 5. Bottom spacer to prevent vertical stretching
        next_row = (len(filtered) - 1) // cols + 1
        spacer = QWidget()
        spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.gallery_grid.addWidget(spacer, next_row, 0, 1, cols)

        self.gallery_grid.setRowStretch(next_row, 1)

    def get_image_placeholder_pixmap(self) -> QPixmap:
        # Scale to zoom factor
        w = int(220 * self.zoom_factor)
        h = int(124 * self.zoom_factor)
        pix = QPixmap(w, h)
        pix.fill(QColor("#f1f5f9"))
        painter = QPainter(pix)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        
        # Camera icon (scaled)
        pw = int(30 * self.zoom_factor)
        ph = int(24 * self.zoom_factor)
        px = (w - pw) // 2
        py = (h - ph) // 2
        painter.setPen(QPen(QColor("#94a3b8"), max(1, int(2 * self.zoom_factor))))
        painter.setBrush(QColor("#ffffff"))
        painter.drawRoundedRect(px, py, pw, ph, 3, 3)
        
        # Lens
        ld = int(12 * self.zoom_factor)
        lx = px + (pw - ld) // 2
        ly = py + (ph - ld) // 2
        painter.setPen(QPen(QColor("#94a3b8"), max(1, int(1.5 * self.zoom_factor))))
        painter.setBrush(QColor("#f1f5f9"))
        painter.drawEllipse(lx, ly, ld, ld)
        
        painter.end()
        return pix


    def closeEvent(self, event):
        self.queue_timer.stop()
        if hasattr(self, "captcha_bridge") and self.captcha_bridge:
            try:
                self.captcha_bridge.stop()
            except Exception:
                pass
        if self.proxy_process:
            try:
                self.proxy_process.terminate()
                self.proxy_process.wait(timeout=2)
            except Exception:
                try:
                    self.proxy_process.kill()
                except Exception:
                    pass
        event.accept()

    # ─────────────────── HISTORY PERSISTENCE ───────────────────
    def load_history_from_disk(self):
        if HISTORY_FILE.exists():
            try:
                data = json.loads(HISTORY_FILE.read_text("utf-8"))
                self.history = []
                for d in data:
                    j = VideoJob(
                        id=d.get("id", ""),
                        mode=d.get("mode", "text-to-video"),
                        prompt=d.get("prompt", ""),
                        output_name=d.get("output_name", ""),
                        model=d.get("model", ""),
                        duration=d.get("duration", 8),
                        resolution=d.get("resolution", "720p"),
                        aspect_ratio=d.get("aspect_ratio", "16:9"),
                        image_url=d.get("image_url", None),
                        reference_image_urls=d.get("reference_image_urls", []),
                        video_url=d.get("video_url", None),
                        account_name=d.get("account_name", ""),
                        status=d.get("status", "done"),
                        local_path=d.get("local_path", None),
                        error=d.get("error", None)
                    )
                    self.history.append(j)
            except Exception:
                self.history = []

    def save_history_to_disk(self):
        try:
            data = []
            for j in self.history:
                data.append({
                    "id": j.id, "mode": j.mode, "prompt": j.prompt,
                    "output_name": j.output_name, "model": j.model,
                    "duration": j.duration, "resolution": j.resolution,
                    "aspect_ratio": j.aspect_ratio,
                    "image_url": j.image_url,
                    "reference_image_urls": j.reference_image_urls,
                    "video_url": j.video_url,
                    "account_name": j.account_name,
                    "status": j.status, "local_path": j.local_path, "error": j.error
                })
            HISTORY_FILE.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass

    # ─────────────────── THUMBNAIL PLACEHOLDER DRAWER ───────────────────
    def get_placeholder_pixmap(self) -> QPixmap:

        w = int(220 * self.zoom_factor)
        h = int(124 * self.zoom_factor)
        pix = QPixmap(w, h)
        pix.fill(QColor("#f1f5f9"))
        painter = QPainter(pix)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        
        # Play icon vector (scaled)
        path = QPainterPath()
        path.moveTo(int(96 * self.zoom_factor), int(42 * self.zoom_factor))
        path.lineTo(int(96 * self.zoom_factor), int(82 * self.zoom_factor))
        path.lineTo(int(128 * self.zoom_factor), int(62 * self.zoom_factor))
        path.closeSubpath()
        painter.fillPath(path, QColor("#7c3aed"))
        painter.end()
        return pix

    # ── MODE BADGE COLORS ─────────────────────────────────────────────
    _MODE_BADGE = {
        "text-to-video":    ("T2V",   "#7c3aed", "#ede9fe"),
        "image-to-video":   ("I2V",   "#0369a1", "#e0f2fe"),
        "reference-to-video":("REF",  "#0f766e", "#ccfbf1"),
        "edit-video":       ("EDIT",  "#b45309", "#fef3c7"),
        "extend-video":     ("EXT",   "#6d28d9", "#ede9fe"),
        "image-generation": ("T2I",   "#be185d", "#fdf2f8"),
        "image-to-image":   ("I2I",   "#7c3aed", "#ede9fe"),
    }

    def create_gallery_card_pyqt(self, job: VideoJob) -> QFrame:
        is_selected = job.id in self.selected_job_ids
        border_color = "#7c3aed" if is_selected else "#e2e8f0"
        bg_color     = "#f5f3ff" if is_selected else "#ffffff"

        card = QFrame()
        card.setObjectName("studio_card")
        card.setStyleSheet(
            f"QFrame#studio_card {{ background-color: {bg_color}; border: 2px solid {border_color}; border-radius: 10px; }}"
            f"QFrame#studio_card:hover {{ border-color: #7c3aed; }}"
        )

        # ── Shared helper: toggle selection ─────────────────────────
        def toggle_selection(j=job):
            if j.id in self.selected_job_ids:
                self.selected_job_ids.discard(j.id)
            else:
                self.selected_job_ids.add(j.id)
            self._update_bulk_toolbar()
            self.refresh_gallery_ui()

        # ── Context menu ─────────────────────────────────────────────
        card.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        def show_context_menu(pos, j=job):
            menu = QMenu(card)
            menu.setStyleSheet(
                "QMenu { background-color: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 4px; }"
                "QMenu::item { padding: 6px 20px; border-radius: 4px; color: #334155; }"
                "QMenu::item:selected { background-color: #7c3aed; color: white; }"
                "QMenu::separator { height: 1px; background: #e2e8f0; margin: 3px 10px; }"
            )
            if j.status == "draft":
                menu.addAction("✏️  Sửa Prompt",      lambda: self.edit_draft_prompt(j))
                menu.addAction("📋  Sao chép Prompt",  lambda: self.copy_job_prompt(j))
                if j.mode in ("image-to-video", "reference-to-video", "image-to-image"):
                    menu.addAction("🖼️  Gán Ảnh đầu vào", lambda: self.choose_image_for_job(j))
                if j.mode == "reference-to-video":
                    menu.addAction("➕  Thêm ảnh tham chiếu", lambda: self.add_ref_image_for_job(j))
                menu.addSeparator()
                menu.addAction("▶️  Chạy job này",    lambda: self.quick_run_single_job(j))
                menu.addAction("🗑️  Xóa bản thảo",    lambda: self.delete_job_card(j))
            elif j.status in ("done", "failed"):
                if j.status == "done":
                    menu.addAction("▶  Xem / Phát",       lambda: self.play_downloaded_video(j))
                    menu.addAction("📥  Tải bản sao",      lambda: self.save_video_copy(j))
                    menu.addAction("📂  Mở thư mục",       lambda: self.open_video_folder(j))
                menu.addAction("📋  Sao chép Prompt",      lambda: self.copy_job_prompt(j))
                menu.addAction("🔄  Tạo lại (retry)",      lambda: self.rerun_job_card(j))
                menu.addSeparator()
                menu.addAction("🗑️  Xóa card",            lambda: self.delete_job_card(j))
            elif j.status in ("pending", "submitted", "polling", "scheduled"):
                menu.addAction("✕  Hủy job này",          lambda: self.cancel_queued_job(j.id))
                menu.addAction("📋  Sao chép Prompt",      lambda: self.copy_job_prompt(j))

            menu.addSeparator()
            sel_text = "☐ Bỏ chọn" if j.id in self.selected_job_ids else "☑ Chọn"
            menu.addAction(sel_text, lambda: toggle_selection(j))
            menu.addAction("☑ Chọn tất cả",   self.select_all_jobs)
            menu.addAction("☐ Bỏ chọn tất cả", self.deselect_all_jobs)
            menu.exec(card.mapToGlobal(pos))

        card.customContextMenuRequested.connect(show_context_menu)

        # ── LIST VIEW ────────────────────────────────────────────────
        if self.gallery_view == "list":
            card_h = max(80, int(88 * self.zoom_factor))
            card.setFixedHeight(card_h)
            lay = QHBoxLayout(card)
            lay.setContentsMargins(8, 4, 8, 4)
            lay.setSpacing(8)

            # Checkbox
            chk = QCheckBox()
            chk.setChecked(is_selected)
            chk.setFixedSize(16, 16)
            chk.stateChanged.connect(lambda s, j=job: self._on_card_checkbox(j, s))
            lay.addWidget(chk, alignment=Qt.AlignmentFlag.AlignVCenter)

            # Thumbnail nhỏ
            t_box = self.create_thumb_lbl_box(job, for_list=True)
            lay.addWidget(t_box, alignment=Qt.AlignmentFlag.AlignVCenter)

            # Info block (giữa) - giới hạn chiều cao để không vượt card
            c_widget = QWidget()
            c_widget.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Ignored)
            c_lay = QVBoxLayout(c_widget)
            c_lay.setContentsMargins(0, 2, 0, 2)
            c_lay.setSpacing(2)

            # Dòng 1: id + mode badge + status badge + account
            r1 = QWidget()
            r1_lay = QHBoxLayout(r1)
            r1_lay.setContentsMargins(0, 0, 0, 0)
            r1_lay.setSpacing(4)
            r1_lay.addWidget(QLabel(f"#{job.id}", styleSheet="font-weight: bold; color: #7c3aed; font-size: 11px;"))
            r1_lay.addWidget(self._make_mode_badge(job.mode))
            r1_lay.addWidget(self.get_status_badge_lbl(job))
            acc = job.account_name.split("@")[0] if job.account_name else "—"
            r1_lay.addWidget(QLabel(f"👤 {acc}", styleSheet="color: #64748b; font-size: 10px;"))
            # Ratio + duration
            ratio_txt = getattr(job, "aspect_ratio", "") or ""
            dur_val = getattr(job, "duration", None)
            extra = " · ".join(filter(None, [ratio_txt, f"{dur_val}s" if dur_val else ""]))
            if extra:
                r1_lay.addWidget(QLabel(extra, styleSheet="color: #94a3b8; font-size: 10px;"))
            r1_lay.addStretch()
            c_lay.addWidget(r1)

            # Dòng 2: prompt
            p_lbl = QLabel(job.prompt[:160] + ("..." if len(job.prompt) > 160 else ""))
            p_lbl.setStyleSheet("font-size: 10px; color: #334155;")
            p_lbl.setWordWrap(False)  # Không wordwrap để giữ chiều cao cố định
            c_lay.addWidget(p_lbl)

            # Dòng 3: error nếu có
            if job.status == "failed" and job.error:
                err = QLabel(f"⚠ {job.error[:80]}", styleSheet="color: #ef4444; font-size: 10px;")
                c_lay.addWidget(err)

            lay.addWidget(c_widget, stretch=1)

            # Action buttons cố định bên phải
            actions = self.create_card_actions_row(job)
            lay.addWidget(actions, alignment=Qt.AlignmentFlag.AlignVCenter)

        # ── GRID VIEW ────────────────────────────────────────────────
        else:
            # Kích thước card cố định (tính toán chính xác để không mất nút)
            thumb_w = int(218 * self.zoom_factor)
            thumb_h = int(123 * self.zoom_factor)
            card_w  = thumb_w + 12          # margin trái + phải = 6+6
            # Chiều cao = thumbnail + info_bar + actions + prompt + spacing + margins
            INFO_H    = 22   # dòng checkbox+id+badge
            ACTIONS_H = 28   # dòng nút hành động
            PROMPT_H  = 22   # dòng prompt text (không wordwrap)
            SPACING   = 3    # spacing giữa rows
            MARGIN_V  = 10   # margin top + bottom = 5+5
            card_h = int((thumb_h + INFO_H + ACTIONS_H + PROMPT_H + SPACING * 3 + MARGIN_V) * self.zoom_factor)

            card.setFixedSize(card_w, card_h)

            lay = QVBoxLayout(card)
            lay.setContentsMargins(5, 5, 5, 5)
            lay.setSpacing(int(3 * self.zoom_factor))

            # ── Thumbnail (fill width) ───────────────────────────────
            t_box = self.create_thumb_lbl_box(job, for_list=False)
            lay.addWidget(t_box, alignment=Qt.AlignmentFlag.AlignHCenter)

            # ── Info bar: Checkbox + ID + Mode badge + Status badge ──
            info_bar = QWidget()
            info_bar.setFixedHeight(INFO_H)
            ib_lay = QHBoxLayout(info_bar)
            ib_lay.setContentsMargins(0, 0, 0, 0)
            ib_lay.setSpacing(3)

            chk = QCheckBox()
            chk.setChecked(is_selected)
            chk.setFixedSize(14, 14)
            chk.stateChanged.connect(lambda s, j=job: self._on_card_checkbox(j, s))
            chk.setToolTip("Chọn card này")
            ib_lay.addWidget(chk, alignment=Qt.AlignmentFlag.AlignVCenter)

            ib_lay.addWidget(QLabel(f"#{job.id}", styleSheet="font-weight: bold; color: #7c3aed; font-size: 10px;"))
            ib_lay.addWidget(self._make_mode_badge(job.mode))
            ib_lay.addStretch()
            ib_lay.addWidget(self.get_status_badge_lbl(job))
            lay.addWidget(info_bar)

            # ── Account + Ratio + Duration bar ──────────────────────
            meta_bar = QWidget()
            meta_bar.setFixedHeight(16)
            mb_lay = QHBoxLayout(meta_bar)
            mb_lay.setContentsMargins(0, 0, 0, 0)
            mb_lay.setSpacing(3)

            acc = job.account_name.split("@")[0] if job.account_name else "—"
            mb_lay.addWidget(QLabel(f"👤 {acc}", styleSheet="color: #94a3b8; font-size: 9px;"))
            mb_lay.addStretch()

            ratio_txt = getattr(job, "aspect_ratio", "") or ""
            if ratio_txt:
                mb_lay.addWidget(QLabel(ratio_txt, styleSheet=(
                    "font-size: 8px; color: #0369a1; background-color: #e0f2fe; "
                    "border-radius: 2px; padding: 0px 3px; font-weight: bold;")))
            dur_val = getattr(job, "duration", None)
            if dur_val:
                mb_lay.addWidget(QLabel(f"{dur_val}s", styleSheet=(
                    "font-size: 8px; color: #7c3aed; background-color: #ede9fe; "
                    "border-radius: 2px; padding: 0px 3px; font-weight: bold;")))
            lay.addWidget(meta_bar)

            # ── Action buttons (LUÔN HIỂN THỊ) ─────────────────────
            actions_w = self.create_card_actions_row(job)
            actions_w.setFixedHeight(ACTIONS_H)
            lay.addWidget(actions_w)

            # ── Prompt text (bottom, không wordwrap để không push nút) ─
            max_chars = max(25, int(50 * self.zoom_factor))
            prompt_p = job.prompt[:max_chars] + ("…" if len(job.prompt) > max_chars else "")
            p_lbl = QLabel(prompt_p)
            p_lbl.setStyleSheet("font-size: 9px; color: #64748b;")
            p_lbl.setWordWrap(False)
            p_lbl.setFixedHeight(PROMPT_H)
            lay.addWidget(p_lbl)

        return card


    def _make_mode_badge(self, mode: str) -> QLabel:
        label, fg, bg = self._MODE_BADGE.get(mode, (mode[:3].upper(), "#475569", "#f1f5f9"))
        lbl = QLabel(label)
        lbl.setStyleSheet(
            f"font-size: 9px; font-weight: bold; color: {fg}; background-color: {bg}; "
            f"border-radius: 3px; padding: 1px 5px;"
        )
        return lbl

    def _on_card_checkbox(self, job: VideoJob, state: int):
        if state == 2:  # Qt.CheckState.Checked
            self.selected_job_ids.add(job.id)
        else:
            self.selected_job_ids.discard(job.id)
        self._update_bulk_toolbar()

    def _update_bulk_toolbar(self):
        n = len(self.selected_job_ids)
        if hasattr(self, "bulk_toolbar"):
            self.bulk_toolbar.setVisible(n > 0)
            if hasattr(self, "bulk_sel_lbl"):
                self.bulk_sel_lbl.setText(f"{n} item đã chọn")

    def create_thumb_lbl_box(self, job: VideoJob, for_list: bool = False) -> QLabel:
        if for_list:
            w = max(80, int(80 * self.zoom_factor))
            h = max(50, int(55 * self.zoom_factor))
        else:
            # Must match thumb_w/thumb_h in create_gallery_card_pyqt grid section
            w = int(218 * self.zoom_factor)
            h = int(123 * self.zoom_factor)


        lbl = QLabel()
        lbl.setFixedSize(w, h)
        lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lbl.setStyleSheet("border-radius: 6px; background-color: #1e1b4b;")

        pix = None
        img_path = None

        if job.status in ("draft", "pending", "failed"):
            if job.image_url:
                img_path = job.image_url
            elif job.reference_image_urls:
                img_path = job.reference_image_urls[0]
        elif "image" in job.model and job.status == "done" and job.local_path:
            img_path = job.local_path

        if img_path and Path(img_path).exists():
            try:
                p = QPixmap(img_path)
                pix = p.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
            except Exception:
                pass

        if not pix:
            if job.id in self.image_cache:
                pix = self.image_cache[job.id]
            else:
                tpath = THUMB_DIR / f"{job.id}.jpg"
                if tpath.exists():
                    try:
                        p = QPixmap(str(tpath))
                        pix = p.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
                        self.image_cache[job.id] = pix
                    except Exception:
                        pass

        if not pix:
            if job.status == "draft":
                pix = self.get_image_placeholder_pixmap()
            else:
                pix = self.get_placeholder_pixmap()

        # Draw overlays
        temp_pix = QPixmap(pix.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation))
        painter = QPainter(temp_pix)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        f_size = max(6, int(8 * self.zoom_factor))

        # Status overlay badge (top-left)
        if job.status == "draft":
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QColor("rgba(124, 58, 237, 0.85)"))
            bw, bh_ = int(60 * self.zoom_factor), int(16 * self.zoom_factor)
            painter.drawRoundedRect(4, 4, bw, bh_, 3, 3)
            painter.setPen(QColor("#ffffff"))
            painter.setFont(QFont("Segoe UI", f_size, QFont.Weight.Bold))
            painter.drawText(8, 4 + bh_ - 3, "BẢN THẢO")
        elif job.status in ("pending", "submitted", "polling", "scheduled"):
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QColor("rgba(2, 132, 199, 0.85)"))
            bw, bh_ = int(72 * self.zoom_factor), int(16 * self.zoom_factor)
            painter.drawRoundedRect(4, 4, bw, bh_, 3, 3)
            painter.setPen(QColor("#ffffff"))
            painter.setFont(QFont("Segoe UI", f_size, QFont.Weight.Bold))
            painter.drawText(8, 4 + bh_ - 3, "ĐANG CHẠY")

        # Ref image count badge (bottom-right)
        if job.mode == "reference-to-video" and len(job.reference_image_urls) > 0:
            count = len(job.reference_image_urls)
            txt = f"🖼 {count}"
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QColor("rgba(15, 23, 42, 0.75)"))
            bw2, bh2 = int(36 * self.zoom_factor), int(16 * self.zoom_factor)
            painter.drawRoundedRect(w - bw2 - 4, h - bh2 - 4, bw2, bh2, 3, 3)
            painter.setPen(QColor("#ffffff"))
            painter.setFont(QFont("Segoe UI", f_size, QFont.Weight.Bold))
            painter.drawText(w - bw2 - 1, h - 6, txt)

        painter.end()
        lbl.setPixmap(temp_pix)

        # Left-click: open lightbox preview
        def on_press(event):
            if event.button() == Qt.MouseButton.LeftButton:
                dialog = ImagePreviewDialog(self, job, self.refresh_gallery_ui)
                dialog.exec()
        lbl.mousePressEvent = on_press

        return lbl

    def get_status_badge_lbl(self, job: VideoJob) -> QLabel:
        lbl = QLabel()
        base = "font-size: 9px; font-weight: bold; border-radius: 4px; padding: 2px 5px;"
        if job.status == "done":
            lbl.setText("✓ XONG")
            lbl.setStyleSheet(f"{base} color: #15803d; background-color: #f0fdf4; border: 1px solid #bbf7d0;")
        elif job.status == "failed":
            lbl.setText("✗ LỖI")
            lbl.setStyleSheet(f"{base} color: #b91c1c; background-color: #fef2f2; border: 1px solid #fecaca;")
        elif job.status == "draft":
            lbl.setText("THẢO")
            lbl.setStyleSheet(f"{base} color: #475569; background-color: #f1f5f9; border: 1px solid #cbd5e1;")
        else:
            lbl.setText("⏳ CHẠY")
            lbl.setStyleSheet(f"{base} color: #0369a1; background-color: #f0f9ff; border: 1px solid #bae6fd;")
        return lbl

    def create_card_actions_row(self, job: VideoJob) -> QWidget:
        w = QWidget()
        lay = QHBoxLayout(w)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(4)
        w.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

        BTN_SIZE = 30  # enlarged button size

        def _btn(icon: str, tip: str) -> QPushButton:
            b = QPushButton(icon)
            b.setFixedSize(BTN_SIZE, BTN_SIZE)
            b.setObjectName("mini_btn")
            b.setToolTip(tip)
            return b

        def _menu_btn() -> QToolButton:
            btn = QToolButton()
            btn.setText("⋯")
            btn.setFixedSize(BTN_SIZE, BTN_SIZE)
            btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
            btn.setStyleSheet(
                "QToolButton { background-color: #f1f5f9; color: #475569; border: 1px solid #cbd5e1; border-radius: 4px; font-weight: bold; font-size: 11px; }"
                "QToolButton:hover { background-color: #e2e8f0; }"
                "QToolButton::menu-indicator { image: none; }"
            )
            return btn

        menu = QMenu(w)
        menu.setStyleSheet(
            "QMenu { background-color: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 4px; }"
            "QMenu::item { padding: 6px 20px; border-radius: 4px; color: #334155; }"
            "QMenu::item:selected { background-color: #7c3aed; color: white; }"
        )

        if job.status == "draft":
            # Primary: Run
            run_btn = _btn("▶", "Chạy ngay job này")
            run_btn.setStyleSheet("QPushButton { background-color: #059669; color: white; border-radius: 4px; }"
                                  "QPushButton:hover { background-color: #047857; }")
            run_btn.clicked.connect(lambda: self.quick_run_single_job(job))
            lay.addWidget(run_btn)

            # Secondary: Edit prompt
            edit_btn = _btn("✏️", "Sửa prompt")
            edit_btn.clicked.connect(lambda: self.edit_draft_prompt(job))
            lay.addWidget(edit_btn)

            # Dropdown menu items
            if job.mode in ("image-to-video", "reference-to-video", "image-to-image"):
                act_img = menu.addAction("📷 Gán / Đổi ảnh")
                act_img.triggered.connect(lambda: self.choose_image_for_job(job))
            if job.mode == "reference-to-video":
                act_ref = menu.addAction("➕ Thêm ảnh tham chiếu")
                act_ref.triggered.connect(lambda: self.add_ref_image_for_job(job))
            
            act_copy = menu.addAction("📋 Sao chép prompt")
            act_copy.triggered.connect(lambda: self.copy_job_prompt(job))

            act_del = menu.addAction("🗑 Xóa bản thảo")
            act_del.triggered.connect(lambda: self.delete_job_card(job))

            btn_more = _menu_btn()
            btn_more.setMenu(menu)
            lay.addWidget(btn_more)

        elif job.status == "done":
            # Primary: Play
            is_img = "image" in job.model
            p_btn = _btn("👁️" if is_img else "▶", "Xem ảnh lớn" if is_img else "Phát video")
            p_btn.setEnabled(bool(job.local_path))
            p_btn.clicked.connect(lambda: self.play_downloaded_video(job))
            lay.addWidget(p_btn)

            # Secondary: Open folder
            f_btn = _btn("📂", "Mở thư mục")
            f_btn.setEnabled(bool(job.local_path))
            f_btn.clicked.connect(lambda: self.open_video_folder(job))
            lay.addWidget(f_btn)

            # Dropdown menu items
            act_dl = menu.addAction("📥 Lưu bản sao")
            act_dl.triggered.connect(lambda: self.save_video_copy(job))

            act_copy = menu.addAction("📋 Sao chép prompt")
            act_copy.triggered.connect(lambda: self.copy_job_prompt(job))

            act_retry = menu.addAction("🔄 Tạo lại (retry)")
            act_retry.triggered.connect(lambda: self.rerun_job_card(job))

            act_del = menu.addAction("🗑 Xóa card")
            act_del.triggered.connect(lambda: self.delete_job_card(job))

            btn_more = _menu_btn()
            btn_more.setMenu(menu)
            lay.addWidget(btn_more)

        elif job.status == "failed":
            # Primary: Rerun (Retry)
            r_btn = _btn("🔄", "Tạo lại (retry)")
            r_btn.clicked.connect(lambda: self.rerun_job_card(job))
            lay.addWidget(r_btn)

            # Dropdown menu items
            act_copy = menu.addAction("📋 Sao chép prompt")
            act_copy.triggered.connect(lambda: self.copy_job_prompt(job))

            act_del = menu.addAction("🗑 Xóa card")
            act_del.triggered.connect(lambda: self.delete_job_card(job))

            btn_more = _menu_btn()
            btn_more.setMenu(menu)
            lay.addWidget(btn_more)

        else:
            # Running/pending: cancel only
            cancel_btn = _btn("✕", "Hủy tiến trình")
            cancel_btn.setStyleSheet("QPushButton { background-color: #dc2626; color: white; border-radius: 4px; }"
                                     "QPushButton:hover { background-color: #b91c1c; }")
            cancel_btn.clicked.connect(lambda: self.cancel_queued_job(job.id))
            lay.addWidget(cancel_btn)

            # Dropdown menu items
            act_copy = menu.addAction("📋 Sao chép prompt")
            act_copy.triggered.connect(lambda: self.copy_job_prompt(job))

            btn_more = _menu_btn()
            btn_more.setMenu(menu)
            lay.addWidget(btn_more)

        return w


    def edit_draft_prompt(self, job: VideoJob):
        text, ok = QInputDialog.getMultiLineText(self, f"Sửa Prompt — #{job.id}", "Nhập prompt mới:", job.prompt)
        if ok and text.strip():
            job.prompt = text.strip()
            self.save_history_to_disk()
            self.refresh_gallery_ui()

    def copy_job_prompt(self, job: VideoJob):
        QApplication.clipboard().setText(job.prompt)
        self.log_global(f"📋 Đã sao chép prompt của #{job.id} vào Clipboard.")

    # ── Search / Sort handlers ────────────────────────────────────────
    def _on_search_changed(self, text: str):
        self.gallery_search_text = text.strip().lower()
        self.refresh_gallery_ui()

    def _on_sort_changed(self, text: str):
        mapping = {"Mới nhất": "newest", "Cũ nhất": "oldest", "Theo trạng thái": "status"}
        self.gallery_sort_order = mapping.get(text, "newest")
        self.refresh_gallery_ui()

    # ── Bulk selection ────────────────────────────────────────────────
    def select_all_jobs(self):
        """Select all currently visible jobs (after filter/search)."""
        visible = self._get_filtered_sorted_jobs()
        for j in visible:
            self.selected_job_ids.add(j.id)
        self._update_bulk_toolbar()
        self.refresh_gallery_ui()

    def deselect_all_jobs(self):
        self.selected_job_ids.clear()
        self._update_bulk_toolbar()
        self.refresh_gallery_ui()

    def delete_selected_jobs(self):
        ids = list(self.selected_job_ids)
        if not ids:
            return
        ans = QMessageBox.question(
            self, "Xác nhận",
            f"Xóa {len(ids)} job đã chọn và các tệp liên quan?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if ans != QMessageBox.StandardButton.Yes:
            return
        for j in [j for j in self.history if j.id in ids]:
            if j.local_path:
                try: Path(j.local_path).unlink(missing_ok=True)
                except Exception: pass
            tpath = THUMB_DIR / f"{j.id}.jpg"
            try: tpath.unlink(missing_ok=True)
            except Exception: pass
            self.image_cache.pop(j.id, None)
        self.history = [j for j in self.history if j.id not in ids]
        self.selected_job_ids.clear()
        self.save_history_to_disk()
        self._update_bulk_toolbar()
        self.refresh_gallery_ui()

    def run_selected_drafts(self):
        """Move selected draft jobs to pending/queue."""
        ids = self.selected_job_ids
        drafts = [j for j in self.history if j.id in ids and j.status == "draft"]
        if not drafts:
            return QMessageBox.warning(self, "Cảnh báo", "Không có Bản thảo nào được chọn!")
        if not self.acc_mgr.active:
            return QMessageBox.critical(self, "Lỗi", "Chưa có tài khoản nào hoạt động!")
        out_folder = Path(self.b_path_entry.text().strip() or str(OUTPUT_DIR))
        for job in drafts:
            job.status = "pending"
            job.local_path = str(out_folder)
            if job not in self.queue:
                self.queue.append(job)
        self.selected_job_ids.clear()
        self.save_history_to_disk()
        self.refresh_queue_ui()
        self.refresh_gallery_ui()
        self._update_bulk_toolbar()
        self.log_global(f"▶ Đã chuyển {len(drafts)} bản thảo đã chọn vào hàng đợi.")

    def retry_selected_failed(self):
        """Re-queue selected failed jobs."""
        ids = self.selected_job_ids
        failed = [j for j in self.history if j.id in ids and j.status == "failed"]
        if not failed:
            return QMessageBox.warning(self, "Cảnh báo", "Không có job thất bại nào được chọn!")
        if not self.acc_mgr.active:
            return QMessageBox.critical(self, "Lỗi", "Chưa có tài khoản nào hoạt động!")
        out_folder = Path(self.b_path_entry.text().strip() or str(OUTPUT_DIR))
        for job in failed:
            job.status = "pending"
            job.error = None
            job.local_path = str(out_folder)
            job.request_id = None
            job.progress_val = 0.0
            if job not in self.queue:
                self.queue.append(job)
        self.selected_job_ids.clear()
        self.save_history_to_disk()
        self.refresh_queue_ui()
        self.refresh_gallery_ui()
        self._update_bulk_toolbar()
        self.log_global(f"🔄 Đã retry {len(failed)} job thất bại đã chọn.")

    # ── Quick-run single draft ────────────────────────────────────────
    def quick_run_single_job(self, job: VideoJob):
        """Immediately queue a single draft job."""
        if job.status != "draft":
            return
        if not self.acc_mgr.active:
            return QMessageBox.critical(self, "Lỗi", "Chưa có tài khoản nào hoạt động!")
        out_folder = Path(self.b_path_entry.text().strip() or str(OUTPUT_DIR))
        job.status = "pending"
        job.local_path = str(out_folder)
        if job not in self.queue:
            self.queue.append(job)
        self.save_history_to_disk()
        self.refresh_queue_ui()
        self.refresh_gallery_ui()
        self.log_global(f"▶ Đã chuyển job #{job.id} vào hàng đợi.")

    # ── Retry-all failed / Clear-all done ────────────────────────────
    def retry_all_failed(self):
        failed = [j for j in self.history if j.status == "failed"]
        if not failed:
            return QMessageBox.information(self, "Thông báo", "Không có job thất bại nào!")
        if not self.acc_mgr.active:
            return QMessageBox.critical(self, "Lỗi", "Chưa có tài khoản nào hoạt động!")
        out_folder = Path(self.b_path_entry.text().strip() or str(OUTPUT_DIR))
        for job in failed:
            job.status = "pending"
            job.error = None
            job.local_path = str(out_folder)
            job.request_id = None
            job.progress_val = 0.0
            if job not in self.queue:
                self.queue.append(job)
        self.save_history_to_disk()
        self.refresh_queue_ui()
        self.refresh_gallery_ui()
        self.log_global(f"🔄 Đã retry {len(failed)} job thất bại.")

    def clear_all_done(self):
        done_jobs = [j for j in self.history if j.status == "done"]
        if not done_jobs:
            return QMessageBox.information(self, "Thông báo", "Không có job hoàn thành nào!")
        ans = QMessageBox.question(
            self, "Xác nhận",
            f"Xóa {len(done_jobs)} job hoàn thành khỏi danh sách? (Tệp video/ảnh KHÔNG bị xóa)",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if ans == QMessageBox.StandardButton.Yes:
            done_ids = {j.id for j in done_jobs}
            self.history = [j for j in self.history if j.id not in done_ids]
            self.selected_job_ids -= done_ids
            self.save_history_to_disk()
            self._update_bulk_toolbar()
            self.refresh_gallery_ui()
            self.log_global(f"🗑 Đã xóa {len(done_jobs)} job hoàn thành khỏi danh sách.")

    def save_video_copy(self, job: VideoJob):
        if not job.local_path or not Path(job.local_path).exists():
            return
        is_img = "image" in job.model
        title = "Lưu bản sao ảnh" if is_img else "Lưu bản sao video"
        filt = "Image (*.png)" if is_img else "Video (*.mp4)"
        dest, _ = QFileDialog.getSaveFileName(self, title, Path(job.local_path).name, filt)
        if dest:
            try:
                shutil.copy2(job.local_path, dest)
                msg = "Đã lưu bản sao ảnh thành công!" if is_img else "Đã lưu bản sao video thành công!"
                QMessageBox.information(self, "Thành công", msg)
            except Exception as e:
                QMessageBox.critical(self, "Lỗi", f"Không thể lưu bản sao: {e}")

    def play_downloaded_video(self, job: VideoJob):
        if not job.local_path or not Path(job.local_path).exists():
            is_img = "image" in job.model
            msg = "Không tìm thấy file ảnh cục bộ!" if is_img else "Không tìm thấy file video cục bộ!"
            return QMessageBox.critical(self, "Lỗi", msg)
        try:
            os.startfile(Path(job.local_path).resolve())
        except Exception as e:
            is_img = "image" in job.model
            msg = f"Không mở được ảnh: {e}" if is_img else f"Không mở được video: {e}"
            QMessageBox.critical(self, "Lỗi", msg)

    def open_video_folder(self, job: VideoJob):
        if not job.local_path or not Path(job.local_path).exists():
            return
        try:
            subprocess.run(f'explorer /select,"{Path(job.local_path).resolve()}"', creationflags=subprocess.CREATE_NO_WINDOW)
        except Exception:
            pass

    def rerun_job_card(self, job: VideoJob):
        self.b_prompt_text.setText(job.prompt)
        self.update_batch_prompts_count()
        self.log_global(f"🔄 Đã đưa prompt của #{job.id} trở lại bảng điều khiển Batch.")

    def delete_job_card(self, job: VideoJob):
        if QMessageBox.question(self, "Xác nhận", f"Xóa kết quả #{job.id} và tệp video liên quan khỏi Studio?") == QMessageBox.StandardButton.Yes:
            if job.local_path:
                try: Path(job.local_path).unlink(missing_ok=True)
                except Exception: pass
            
            tpath = THUMB_DIR / f"{job.id}.jpg"
            try: tpath.unlink(missing_ok=True)
            except Exception: pass

            if job in self.history: self.history.remove(job)
            self.image_cache.pop(job.id, None)

            self.save_history_to_disk()
            self.refresh_gallery_ui()

    def extract_thumbnail_pyqt(self, job_id, video_path):
        worker = ThumbnailWorker(job_id, video_path)
        worker.done_sig.connect(lambda jid: self.refresh_gallery_ui())
        worker.start()

    def log_global(self, m):
        print(f"[{datetime.now().strftime('%H:%M:%S')}] {m}")

    def start_batch_generation(self):
        # Lấy tất cả drafts
        drafts = [j for j in self.history if j.status == "draft"]

        # Nếu không có drafts nhưng có văn bản ở khung soạn prompts -> Tự động thêm vào drafts trước
        prompts_raw = self.b_prompt_text.toPlainText().strip()
        if not drafts and prompts_raw:
            self.add_prompts_to_draft()
            drafts = [j for j in self.history if j.status == "draft"]

        if not drafts:
            return QMessageBox.warning(self, "Cảnh báo", "Không tìm thấy Bản thảo nào để tạo!")

        if not self.acc_mgr.active:
            return QMessageBox.critical(self, "Lỗi", "Chưa có tài khoản nào hoạt động!")

        out_folder = Path(self.b_path_entry.text().strip() or str(OUTPUT_DIR))

        submitted_count = 0
        for job in drafts:
            job.status = "pending"
            job.local_path = str(out_folder)
            self.queue.append(job)
            submitted_count += 1

        self.save_history_to_disk()
        self.refresh_queue_ui()
        self.refresh_gallery_ui()
        self.log_global(f"🚀 Đã chuyển {submitted_count} bản thảo vào hàng đợi xử lý.")

    # ─────────────────── TAB ACCOUNTS (PyQt6 Grid) ───────────────────
    def setup_accs_panel(self):
        panel_w = QWidget()
        lay = QVBoxLayout(panel_w)
        lay.setContentsMargins(20, 15, 20, 15)

        # Header
        h_title = QLabel("👥  Account Manager (Tài khoản)", styleSheet="font-size: 22px; font-weight: bold;")
        lay.addWidget(h_title)

        # QSplitter chia ngang: Trái (Thêm), Phải (Danh sách)
        split = QSplitter(Qt.Orientation.Horizontal)
        split.setStyleSheet("QSplitter::handle { background-color: #cbd5e1; width: 1px; }")

        # Trái: Add account form & Oauth
        left_box = QFrame()
        left_box.setObjectName("card")
        l_lay = QVBoxLayout(left_box)
        
        # Oauth section
        oauth_f = QFrame()
        oauth_f.setStyleSheet("background-color: #7c3aed; border-radius: 8px; padding: 10px;")
        oa_lay = QVBoxLayout(oauth_f)
        oa_lay.addWidget(QLabel("🔑 ĐĂNG NHẬP GROK / CODEX QUA CLIPROXY", styleSheet="color: white; font-weight: bold; font-size: 13px;"))
        btn_lay = QHBoxLayout()
        oa_btn = QPushButton("🔑  Login Qua Trình Duyệt")
        oa_btn.setObjectName("accent_btn")
        oa_btn.setStyleSheet("background-color: #4c1d95; color: white;")
        btn_lay.addWidget(oa_btn)

        admin_btn = QPushButton("🌐  Mở Web Admin")
        admin_btn.setObjectName("normal_btn")
        admin_btn.setStyleSheet("background-color: #ffffff; color: #7c3aed; font-weight: bold;")
        
        def open_admin_web():
            import webbrowser
            webbrowser.open("http://127.0.0.1:8317/management.html")
            
        admin_btn.clicked.connect(open_admin_web)
        btn_lay.addWidget(admin_btn)
        oa_lay.addLayout(btn_lay)
        
        self.accs_oauth_status = QLabel("Mở trình duyệt sạch tự động dọn cache.", styleSheet="color: #e2d6ff; font-size: 11px;")
        
        def run_oauth_tab():
            items = ["xAI Grok (SuperGrok)", "OpenAI Codex (ChatGPT Plus)", "Google Flow / Veo 3"]
            item, ok = QInputDialog.getItem(self, "Đăng Nhập Tài Khoản", "Chọn loại tài khoản đăng nhập:", items, 0, False)
            if not ok or not item:
                return
                
            login_type = item

            if "Google Flow" in login_type:
                prof_name, ok2 = QInputDialog.getText(self, "Đăng Nhập Google", "Nhập tên cấu hình trình duyệt (Viết liền không dấu):")
                if not ok2 or not prof_name.strip():
                    return
                prof_name = prof_name.strip()
                prof_name = _resolve_google_profile_name(prof_name) or prof_name
                self.accs_oauth_status.setText("🔍 Đang khởi chạy trình duyệt Google...")
                self.accs_oauth_status.setStyleSheet("color: #7c3aed; font-weight: bold;")
                
                self.tab_google_login_worker = GoogleLoginWorker(profile_name=prof_name)
                self.tab_google_login_worker.status_sig.connect(lambda t, c: (self.accs_oauth_status.setText(t), self.accs_oauth_status.setStyleSheet(f"color: {c}; font-weight: bold;")))
                
                def on_google_success(email, token, proj_id):
                    saved_profile = (
                        getattr(self.tab_google_login_worker, "profile_name", "")
                        or _resolve_google_profile_name(email)
                        or prof_name
                    )
                    acc_name = f"Google_{email}"
                    exists = False
                    for a in self.acc_mgr.accounts:
                        if a.name == acc_name:
                            a.api_key = token
                            a.auth_revision = time.time_ns()
                            a.auth_state = 'ready'
                            a.proxy_url = proj_id
                            a.profile_name = saved_profile
                            a.active = True
                            exists = True
                            break
                    if not exists:
                        self.acc_mgr.accounts.append(Account(
                            name=acc_name,
                            proxy_url=proj_id,
                            api_key=token,
                            profile_name=saved_profile,
                            active=True
                        ))
                    self.acc_mgr.save()
                    
                    # Keep the account registry in the same root as its
                    # persistent Chrome profile and storage-state snapshot.
                    _upsert_flow_profile_registry(
                        email, saved_profile, proj_id, mark_login=True
                    )
                    
                    self.acc_mgr.load()
                    self.draw_tab_accounts_list()
                    self.refresh_sidebar_acc_lbl()
                    self.refresh_accounts_label_studio()
                    self.accs_oauth_status.setText(f"✅ Đăng nhập thành công Google: {email}!")
                    self.accs_oauth_status.setStyleSheet("color: #16a34a; font-weight: bold;")
                    
                def on_google_error(err_msg):
                    self.accs_oauth_status.setText(f"❌ Lỗi: {err_msg}")
                    self.accs_oauth_status.setStyleSheet("color: #ef4444; font-weight: bold;")
                    
                self.tab_google_login_worker.success_sig.connect(on_google_success)
                self.tab_google_login_worker.error_sig.connect(on_google_error)
                self.tab_google_login_worker.start()
                return

            if not CLIPROXY_EXE.exists():
                return QMessageBox.critical(self, "Lỗi", f"Không tìm thấy file CLIProxy tại:\n{CLIPROXY_EXE}")

            self.accs_oauth_status.setText("🔍 Đang chuẩn bị cổng kết nối...")

            self.tab_login_worker = LoginWorker(login_type=login_type)
            self.tab_login_worker.status_sig.connect(lambda t, c: (self.accs_oauth_status.setText(t), self.accs_oauth_status.setStyleSheet(f"color: {c}; font-weight: bold;")))
            
            def on_oauth_success(info):
                if "|" in info:
                    login_type, email = info.split("|", 1)
                else:
                    login_type = "xAI Grok"
                    email = info
                acc_prefix = "Codex" if "Codex" in login_type else "Grok"
                acc_name = f"{acc_prefix} - {email}"
                existing = [a.name for a in self.acc_mgr.accounts]
                if acc_name not in existing:
                    self.acc_mgr.add(acc_name, DEFAULT_PROXY_URL, "grok-video-key-001")
                self.acc_mgr.load()
                self.draw_tab_accounts_list()
                self.refresh_sidebar_acc_lbl()
                self.refresh_accounts_label_studio()

            self.tab_login_worker.success_sig.connect(on_oauth_success)
            self.tab_login_worker.start()

        oa_btn.clicked.connect(run_oauth_tab)
        oa_lay.addWidget(oa_btn)

        sync_btn = QPushButton("🔄  Đồng Bộ CLIproxy")
        sync_btn.setObjectName("sync_btn")
        sync_btn.setStyleSheet("background-color: #0d9488; color: white; font-weight: bold;")

        def run_sync_tab():
            added, removed = self.acc_mgr.sync_from_cliproxy()
            self.acc_mgr.load()
            self.draw_tab_accounts_list()
            self.refresh_sidebar_acc_lbl()
            self.refresh_accounts_label_studio()
            QMessageBox.information(
                self, 
                "Đồng Bộ Thành Công", 
                f"Đã đồng bộ xong danh sách tài khoản từ CLIproxy!\n\n"
                f"➕ Thêm mới: {added} tài khoản\n"
                f"🗑️ Đã xóa (hết hạn/đã xóa trên admin): {removed} tài khoản"
            )

        sync_btn.clicked.connect(run_sync_tab)
        oa_lay.addWidget(sync_btn)

        oa_lay.addWidget(self.accs_oauth_status)
        l_lay.addWidget(oauth_f)

        l_lay.addWidget(QLabel("➕ Thêm Thủ Công", styleSheet="font-weight: bold; margin-top: 10px; color: #7c3aed;"))
        
        self.acc_type_combo = QComboBox()
        self.acc_type_combo.addItems(["xAI Grok / OpenAI Codex", "Google Flow / Sandbox (Token)"])
        self.acc_type_combo.setStyleSheet(
            "QComboBox { background: white; border: 1px solid #cbd5e1; border-radius: 4px; padding: 4px; font-size: 11px; color: #1e293b; }"
        )
        l_lay.addWidget(self.acc_type_combo)

        ne = QLineEdit(placeholderText="Tên / Email tài khoản...")
        l_lay.addWidget(ne)
        ue = QLineEdit(placeholderText=f"Proxy URL hoặc GCP Project ID...")
        l_lay.addWidget(ue)
        ke = QLineEdit(placeholderText="API Key hoặc Bearer Token...", echoMode=QLineEdit.EchoMode.Password)
        l_lay.addWidget(ke)

        def add():
            n = ne.text().strip()
            u = ue.text().strip()
            k = ke.text().strip()
            if not n or not k: return QMessageBox.warning(self, "⚠️", "Tên và API Key/Token bắt buộc!")
            
            is_google = self.acc_type_combo.currentIndex() == 1
            if is_google:
                if not n.startswith("Google_"):
                    n = f"Google_{n}"
                if not u:
                    u = DEFAULT_PROJECT_ID
            else:
                if not u:
                    u = DEFAULT_PROXY_URL
                    
            self.acc_mgr.add(n, u, k)
            ne.clear(); ue.clear(); ke.clear()
            self.acc_mgr.load()
            self.draw_tab_accounts_list()
            self.refresh_sidebar_acc_lbl()
            self.refresh_accounts_label_studio()

        add_b = QPushButton("➕  Thêm")
