    def draw_tab_accounts_list(self):
        # Clear
        for i in reversed(range(self.tab_accs_scroll_lay.count())):
            widget = self.tab_accs_scroll_lay.itemAt(i).widget()
            if widget: widget.setParent(None)

        if not self.acc_mgr.accounts:
            lbl = QLabel("Chưa có tài khoản nào.", styleSheet="color: #94a3b8; font-style: italic; text-align: center;")
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.tab_accs_scroll_lay.addWidget(lbl)
            return

        # Add bulk Google refresh button if there are Google accounts
        google_accs = [a for a in self.acc_mgr.accounts if _is_google_flow_account(a)]
        if google_accs:
            bulk_row = QFrame()
            bulk_row.setStyleSheet("background-color: #dbeafe; border-radius: 6px; padding: 6px;")
            bulk_lay = QHBoxLayout(bulk_row)
            bulk_lay.setContentsMargins(10, 4, 10, 4)
            
            bulk_info = QLabel(f"🌐 {len(google_accs)} tài khoản Google", styleSheet="font-weight: bold; color: #1e40af; font-size: 12px;")
            bulk_lay.addWidget(bulk_info, stretch=1)
            
            bulk_refresh = QPushButton("🔍 Kiểm tra tất cả Token")
            bulk_refresh.setStyleSheet("background-color: #2563eb; color: white; font-weight: bold; padding: 6px 12px; border-radius: 4px;")
            
            def do_bulk_refresh():
                g_accs = [
                    a for a in self.acc_mgr.accounts
                    if a.active and _is_google_flow_account(a)
                ]
                if not g_accs:
                    QMessageBox.warning(self, "⚠️", "Không có tài khoản Google nào đang hoạt động!")
                    return
                bulk_refresh.setEnabled(False)
                bulk_refresh.setText("⏳ Đang kiểm tra...")
                self.log_global(f"🔍 Đang kiểm tra hiệu lực token cho {len(g_accs)} tài khoản Google...")
                self._bulk_refresh_worker = GoogleTokenRefreshWorker(g_accs)
                self._bulk_refresh_worker.log_sig.connect(self.log_global)
                self._bulk_refresh_worker.token_updated.connect(self._on_google_token_updated)
                def on_done(valid, expired):
                    try:
                        bulk_refresh.setEnabled(True)
                        bulk_refresh.setText("🔍 Kiểm tra tất cả Token")
                    except RuntimeError:
                        pass
                    
                    try:
                        self.draw_tab_accounts_list()
                        self.refresh_sidebar_acc_lbl()
                    except RuntimeError:
                        pass

                    if expired > 0:
                        QMessageBox.warning(self, "Kiểm tra Token", f"✅ Còn hiệu lực: {valid}\n⚠️ Hết hạn: {expired}\n\nNhấn 🔑 để login lại các tài khoản hết hạn.")
                    else:
                        QMessageBox.information(self, "Kiểm tra Token", f"✅ Tất cả {valid} token đều còn hiệu lực!")
                self._bulk_refresh_worker.finished_all.connect(on_done)
                self._bulk_refresh_worker.start()
            
            bulk_refresh.clicked.connect(do_bulk_refresh)
            bulk_lay.addWidget(bulk_refresh)
            self.tab_accs_scroll_lay.addWidget(bulk_row)

        for idx, acc in enumerate(self.acc_mgr.accounts):
            row = QFrame()
            row.setObjectName("acc_row")
            is_google = _is_google_flow_account(acc)
            bg_color = "#ede9fe" if is_google else "#f1f5f9"
            row.setStyleSheet(f"QFrame#acc_row {{ background-color: {bg_color}; border-radius: 6px; padding: 4px; }}")
            r_lay = QHBoxLayout(row)
            r_lay.setContentsMargins(10, 4, 10, 4)

            # Account type icon
            type_icon = "🌐" if is_google else ("🤖" if "Grok" in acc.name else "💻")
            token_preview = f"{acc.api_key[:20]}..." if len(acc.api_key) > 20 else acc.api_key
            
            credits_str = ""
            if is_google:
                cr_val = getattr(acc, "credits", None)
                cr_txt = f"{cr_val} cr" if cr_val is not None else "--"
                tag_val = getattr(acc, "tag", "Pro")
                credits_str = f"  │  🏷️ Tag: {tag_val}  │  💰 Credits: {cr_txt}"
                
            name_lbl = QLabel(f"{type_icon}  {acc.name}\n🔗  {acc.proxy_url}  │  Done: {acc.jobs_done}{credits_str}\n🔑  Token: {token_preview}", styleSheet="font-size: 11px;")
            r_lay.addWidget(name_lbl, stretch=1)

            # Google-specific buttons
            if is_google:
                tag_combo = QComboBox()
                tag_combo.addItems(["Pro", "Ultra"])
                tag_combo.setCurrentText(getattr(acc, "tag", "Pro"))
                tag_combo.setStyleSheet(
                    "QComboBox { background: white; border: 1px solid #cbd5e1; border-radius: 4px; padding: 2px; font-size: 10px; min-width: 60px; }"
                )
                def make_tag_change(i=idx, combo=tag_combo):
                    def handler():
                        self.acc_mgr.accounts[i].tag = combo.currentText()
                        self.acc_mgr.save()
                        self.draw_tab_accounts_list()
                    return handler
                tag_combo.currentTextChanged.connect(make_tag_change(idx, tag_combo))
                r_lay.addWidget(tag_combo)

                refresh_btn = QPushButton("🔍")
                refresh_btn.setToolTip("Kiểm tra Token & Đồng bộ Credits")
                refresh_btn.setStyleSheet("background-color: #2563eb; color: white; padding: 4px; border-radius: 4px; min-width: 25px;")
                
                def make_refresh(i=idx, a=acc):
                    def handler():
                        profile_name = _google_profile_name_for_account(a)
                        if not profile_name:
                            aliases = _google_profile_aliases(a.name)
                            profile_name = aliases[1] if len(aliases) > 1 else (aliases[0] if aliases else "")
                        self.log_global(f"🔍 Đang kiểm tra token & credits cho {profile_name}...")
                        self._single_refresh = GoogleSingleRefreshWorker(a, profile_name)
                        self._single_refresh.log_sig.connect(self.log_global)
                        self._single_refresh.token_updated.connect(self._on_google_token_updated)
                        self._single_refresh.status_sig.connect(
                            lambda t, c: self.accs_oauth_status.setText(t) if hasattr(self, 'accs_oauth_status') else None
                        )
                        def on_done_single():
                            self.draw_tab_accounts_list()
                            self.refresh_sidebar_acc_lbl()
                        self._single_refresh.finished.connect(on_done_single)
                        self._single_refresh.start()
                    return handler
                
                refresh_btn.clicked.connect(make_refresh(idx, acc))
                r_lay.addWidget(refresh_btn)

                login_btn = QPushButton("🔑")
                login_btn.setToolTip("Login lại (mở trình duyệt)")
                login_btn.setStyleSheet("background-color: #7c3aed; color: white; padding: 4px; border-radius: 4px; min-width: 25px;")
                
                def make_relogin(i=idx, a=acc):
                    def handler():
                        profile_name = _google_profile_name_for_account(a)
                        if not profile_name:
                            aliases = _google_profile_aliases(a.name)
                            profile_name = aliases[1] if len(aliases) > 1 else (aliases[0] if aliases else "")
                        self.accs_oauth_status.setText(f"🔍 Đang mở trình duyệt cho {profile_name}...")
                        self.accs_oauth_status.setStyleSheet("color: #7c3aed; font-weight: bold;")
                        
                        self.tab_google_login_worker = GoogleLoginWorker(profile_name=profile_name)
                        self.tab_google_login_worker.status_sig.connect(
                            lambda t, c: (self.accs_oauth_status.setText(t), self.accs_oauth_status.setStyleSheet(f"color: {c}; font-weight: bold;"))
                        )
                        
                        def on_success(email, token, proj_id):
                            saved_profile = (
                                getattr(self.tab_google_login_worker, "profile_name", "")
                                or _resolve_google_profile_name(email)
                                or profile_name
                            )
                            for acc2 in self.acc_mgr.accounts:
                                if acc2.name == a.name:
                                    acc2.api_key = token
                                    acc2.auth_revision = time.time_ns()
                                    acc2.auth_state = 'ready'
                                    acc2.profile_name = saved_profile
                                    if proj_id:
                                        acc2.proxy_url = proj_id
                                    acc2.active = True
                                    break
                            self.acc_mgr.save()
                            _upsert_flow_profile_registry(
                                email, saved_profile, proj_id, mark_login=True
                            )
                            self.draw_tab_accounts_list()
                            self.refresh_sidebar_acc_lbl()
                            self.accs_oauth_status.setText(f"✅ Đã login lại: {email} (profile: {saved_profile})")
                            self.accs_oauth_status.setStyleSheet("color: #16a34a; font-weight: bold;")
                        
                        def on_error(err):
                            self.accs_oauth_status.setText(f"❌ Lỗi: {err}")
                            self.accs_oauth_status.setStyleSheet("color: #ef4444; font-weight: bold;")
                        
                        self.tab_google_login_worker.success_sig.connect(on_success)
                        self.tab_google_login_worker.error_sig.connect(on_error)
                        self.tab_google_login_worker.start()
                    return handler
                
                login_btn.clicked.connect(make_relogin(idx, acc))
                r_lay.addWidget(login_btn)

            cb = QCheckBox("Bật" if acc.active else "Tắt")
            cb.setChecked(acc.active)
            
            def make_toggle(i=idx, c=cb):
                def handler():
                    self.acc_mgr.toggle(i)
                    c.setText("Bật" if self.acc_mgr.accounts[i].active else "Tắt")
                    self.refresh_sidebar_acc_lbl()
                    self.refresh_accounts_label_studio()
                return handler
            
            cb.stateChanged.connect(make_toggle(idx, cb))
            r_lay.addWidget(cb)

            del_btn = QPushButton("🗑️")
            del_btn.setStyleSheet("background-color: #ef4444; color: white; padding: 4px; border-radius: 4px; min-width: 25px;")
            
            def make_delete(i=idx):
                def handler():
                    if QMessageBox.question(self, "Xác nhận", f"Xóa tài khoản '{self.acc_mgr.accounts[i].name}'?") == QMessageBox.StandardButton.Yes:
                        removed_account = self.acc_mgr.accounts[i]
                        acc_name = removed_account.name
                        self.acc_mgr.remove(i)
                        self.acc_mgr.load()
                        self.draw_tab_accounts_list()
                        self.refresh_sidebar_acc_lbl()
                        self.refresh_accounts_label_studio()
                        
                        # Clean browser profiles/cookies cache
                        try:
                            import shutil
                            profile_name = _google_profile_name_for_account(removed_account)
                            if not profile_name:
                                return
                            
                            shared_dir = _resolve_flow_shared_dir(profile_name)
                            p_dir = shared_dir / "profiles" / profile_name
                            if p_dir.exists():
                                shutil.rmtree(p_dir, ignore_errors=True)
                                
                            c_file = shared_dir / "cookies" / f"{profile_name}.json"
                            if c_file.exists():
                                c_file.unlink(missing_ok=True)
                                
                            bp_dir = Path(__file__).parent / "browser_profiles" / profile_name
                            if bp_dir.exists():
                                shutil.rmtree(bp_dir, ignore_errors=True)
                                
                            self.log_global(f"🧹 Đã dọn dẹp thư mục trình duyệt và cookies của: {profile_name}")
                        except Exception as e:
                            print(f"Error cleaning profile: {e}")
                return handler
            
            del_btn.clicked.connect(make_delete(idx))
            r_lay.addWidget(del_btn)

            self.tab_accs_scroll_lay.addWidget(row)
        self.tab_accs_scroll_lay.addStretch()


    # ─────────────────── TAB HISTORY (PyQt6 Table) ───────────────────
    def setup_hist_panel(self):
        panel_w = QWidget()
        lay = QVBoxLayout(panel_w)
        lay.setContentsMargins(20, 15, 20, 15)

        h_title = QLabel("📊  Job History (Lịch Sử)", styleSheet="font-size: 22px; font-weight: bold;")
        lay.addWidget(h_title)

        # Table
        self.hist_table = QTableWidget()
        self.hist_table.setColumnCount(6)
        self.hist_table.setHorizontalHeaderLabels(["Trạng thái", "Job ID", "Chế độ", "Tài khoản", "Thời gian", "Kết quả / Lỗi"])
        self.hist_table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        self.hist_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
        self.hist_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        self.hist_table.horizontalHeader().setStyleSheet("QHeaderView::section { font-weight: bold; background-color: #f1f5f9; padding: 6px; }")
        self.hist_table.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers)
        self.hist_table.setAlternatingRowColors(True)
        lay.addWidget(self.hist_table)

        # Summary label
        self.hist_summary_lbl = QLabel("")
        self.hist_summary_lbl.setStyleSheet("font-size: 13px; font-weight: bold; color: #7c3aed;")
        lay.addWidget(self.hist_summary_lbl)

        self.refresh_history_table()
        self.stacked_widget.addWidget(panel_w)

    def refresh_history_table(self):
        self.hist_table.setRowCount(0)
        
        ok = sum(1 for j in self.history if j.status == "done")
        fail = sum(1 for j in self.history if j.status == "failed")
        self.hist_summary_lbl.setText(f"📊  Tổng số: {len(self.history)} jobs  │  ✅ Thành công: {ok}  │  ❌ Thất bại: {fail}")

        for i, j in enumerate(self.history[:100]):
            self.hist_table.insertRow(i)
            
            icon = "✅" if j.status == "done" else "❌" if j.status == "failed" else "⏳"
            status_item = QTableWidgetItem(icon)
            status_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
            self.hist_table.setItem(i, 0, status_item)

            id_item = QTableWidgetItem(j.id)
            self.hist_table.setItem(i, 1, id_item)

            mode_item = QTableWidgetItem(j.mode.replace("-", "→", 1))
            self.hist_table.setItem(i, 2, mode_item)

            acc_item = QTableWidgetItem(j.account_name or "–")
            self.hist_table.setItem(i, 3, acc_item)

            time_item = QTableWidgetItem(f"{j.elapsed}s")
            time_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
            self.hist_table.setItem(i, 4, time_item)

            out_text = Path(j.local_path).name if j.local_path else (j.error or "–")
            out_item = QTableWidgetItem(out_text)
            self.hist_table.setItem(i, 5, out_item)

    def load_veo_config(self):
        config_path = GROK_CONFIG_FILE
        if config_path.exists():
            try:
                import json
                data = json.loads(config_path.read_text("utf-8"))
                self.veo_bearer = data.get("bearer_token", "")
                self.veo_project_id = data.get("project_id", "")
                self.veo_flow_profile_name = _resolve_google_profile_name(
                    data.get("flow_profile_name", "")
                )
                self.veo_bridge_port = data.get("bridge_port", 4000)
                self.veo_jitter_min_ms = data.get("jitter_min_ms", 2000)
                self.veo_jitter_max_ms = data.get("jitter_max_ms", 5000)
            except Exception:
                self.veo_bearer = ""
                self.veo_project_id = ""
                self.veo_flow_profile_name = ""
                self.veo_bridge_port = 4000
                self.veo_jitter_min_ms = 2000
                self.veo_jitter_max_ms = 5000
        else:
            self.veo_bearer = ""
            self.veo_project_id = ""
            self.veo_flow_profile_name = ""
            self.veo_bridge_port = 4000
            self.veo_jitter_min_ms = 2000
            self.veo_jitter_max_ms = 5000

        # Load bridge secret from electron path
        secret_path = os.path.join(os.environ.get("APPDATA", ""), "veo3studio", "captcha-bridge.secret")
        if os.path.exists(secret_path):
            try:
                with open(secret_path, "r", encoding="utf-8") as f:
                    self.veo_secret = f.read().strip()
            except Exception:
                self.veo_secret = ""
        else:
            try:
                os.makedirs(os.path.dirname(secret_path), exist_ok=True)
                import uuid
                self.veo_secret = uuid.uuid4().hex
                with open(secret_path, "w", encoding="utf-8") as f:
                    f.write(self.veo_secret)
            except Exception:
                self.veo_secret = ""

    def save_veo_config(self):
        config_path = GROK_CONFIG_FILE
        try:
            import json
            data = {
                "bearer_token": self.veo_bearer,
                "project_id": self.veo_project_id,
                "flow_profile_name": getattr(self, "veo_flow_profile_name", ""),
                "bridge_port": self.veo_bridge_port,
                "jitter_min_ms": getattr(self, "veo_jitter_min_ms", 2000),
                "jitter_max_ms": getattr(self, "veo_jitter_max_ms", 5000)
            }
            config_path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass

        # Save bridge secret back to the electron path if modified
        secret_path = os.path.join(os.environ.get("APPDATA", ""), "veo3studio", "captcha-bridge.secret")
        try:
            os.makedirs(os.path.dirname(secret_path), exist_ok=True)
            with open(secret_path, "w", encoding="utf-8") as f:
                f.write(self.veo_secret)
        except Exception:
            pass

    def next_veo_account(self) -> Optional[Account]:
        """Lấy tài khoản Google Flow tiếp theo trong danh sách hoạt động, hoặc trả về tài khoản ảo chứa cấu hình Settings mặc định."""
        self.acc_mgr.load()
        veo_accs = [
            a for a in self.acc_mgr.active
            if _is_google_flow_account(a) and (a.credits is None or a.credits > 0)
        ]
        if veo_accs:
            if not hasattr(self, "_veo_idx"):
                self._veo_idx = 0
            acc = veo_accs[self._veo_idx % len(veo_accs)]
            self._veo_idx += 1
            acc.jobs_done += 1
            self.acc_mgr.save()
            return acc
        
        # Fallback: Trả về tài khoản ảo dùng token mặc định trong settings
        if getattr(self, "veo_bearer", ""):
            return Account(
                name="Settings (Mặc định)",
                proxy_url=getattr(self, "veo_project_id", ""),
                api_key=getattr(self, "veo_bearer", ""),
                profile_name=getattr(self, "veo_flow_profile_name", ""),
                active=True,
                jobs_done=0
            )
        return None

    def start_captcha_bridge_if_needed(self):
        """Khởi động Captcha Bridge Server cục bộ cho Extension."""
        port_val = getattr(self, "veo_bridge_port", 4000)
        self.captcha_bridge = CaptchaBridge(self.log_global, port=port_val)
        self.captcha_bridge.start()

    def auto_refresh_google_tokens(self):
        """Tự động kiểm tra token cho tất cả tài khoản Google khi mở tool."""
        google_accs = [
            a for a in self.acc_mgr.accounts
            if a.active and _is_google_flow_account(a)
        ]
        if not google_accs:
            self.log_global("ℹ️ Không có tài khoản Google nào để kiểm tra token.")
            return
        
        self.log_global(f"🔍 [Token Check] Đang kiểm tra hiệu lực token cho {len(google_accs)} tài khoản Google...")
        
        self._token_refresh_worker = GoogleTokenRefreshWorker(google_accs)
        self._token_refresh_worker.log_sig.connect(self.log_global)
        self._token_refresh_worker.token_updated.connect(self._on_google_token_updated)
        self._token_refresh_worker.finished_all.connect(self._on_google_refresh_done)
        self._token_refresh_worker.start()

    def _on_google_token_updated(self, acc_name: str, token: str, project_id: str, credits_val: int = -1):
        """Callback khi token được xác nhận còn hiệu lực."""
        # A video worker or Threads can refresh the shared account file at
        # the same time.  Reload before writing this one update so we do not
        # roll a newer profile/token mapping back to an old in-memory copy.
        try:
            self.acc_mgr.load()
        except Exception:
            pass
        resolved_profile = ""
        updated_account = None
        for acc in self.acc_mgr.accounts:
            if acc.name == acc_name:
                from google_flow_auth import token_result_is_current
                if not token_result_is_current(GROK_AUTH_ROOT, _google_profile_name_for_account(acc), token):
                    return
                acc.api_key = token
                acc.auth_state = 'ready'
                acc.auth_revision = time.time_ns()
                if project_id:
                    acc.proxy_url = project_id
                if credits_val >= 0:
                    acc.credits = credits_val
                resolved_profile = _google_profile_name_for_account(acc)
                if resolved_profile:
                    acc.profile_name = resolved_profile
                updated_account = acc
                break
        self.acc_mgr.save()

        if updated_account and resolved_profile:
            emails = _GOOGLE_EMAIL_RE.findall(acc_name)
            account_email = emails[0] if emails else _GOOGLE_ACCOUNT_LABEL_RE.sub("", acc_name).strip()
            _upsert_flow_profile_registry(
                account_email, resolved_profile, project_id, credits=credits_val
            )
        
        # Also update veo3_config.json if this is the first/main Google account
        google_accs = [a for a in self.acc_mgr.accounts if a.active and _is_google_flow_account(a)]
        if google_accs and google_accs[0].name == acc_name:
            self.veo_bearer = token
            if project_id:
                self.veo_project_id = project_id
            if resolved_profile:
                self.veo_flow_profile_name = resolved_profile
            self.save_veo_config()

    def _on_google_refresh_done(self, valid_count: int, expired_count: int):
        """Callback khi tất cả Google accounts đã kiểm tra xong."""
        if expired_count > 0:
            self.log_global(f"⚠️ [Token Check] Hoàn thành: {valid_count} token OK, {expired_count} token hết hạn — cần login lại (nhấn 🔑)")
        else:
            self.log_global(f"✅ [Token Check] Hoàn thành: Tất cả {valid_count} token đều còn hiệu lực!")
        # Reload account table if visible
        if hasattr(self, 'draw_tab_accounts_list'):
            try:
                self.draw_tab_accounts_list()
            except Exception:
                pass

