    # ─────────────────── BATCH PROCESSOR QUEUE LOOP ───────────────────
    def process_queue(self):
        # Kiểm tra giới hạn luồng song song
        if len(self.active_workers) >= self.concurrency_limit:
            return

        # Tìm job pending tiếp theo trong hàng đợi
        pending_jobs = [j for j in self.queue if j.status == "pending"]
        if not pending_jobs:
            return

        for job in pending_jobs:
            is_veo = is_veo_model(job.model)
            if is_veo:
                v_acc = self.next_veo_account()
                if not v_acc:
                    self.log_global(f"❌ Không tìm thấy cấu hình Google Flow cho job {job.id}! Cần thêm tài khoản Google trong tab Accounts hoặc cấu hình token trong Settings.")
                    job.status = "failed"
                    job.error = "Chưa cấu hình Google Flow"
                    self.refresh_queue_ui()
                    continue
                
                job.status = "scheduled"
                job.account_name = v_acc.name
                job.google_profile_name = _google_profile_name_for_account(v_acc)
                self.refresh_queue_ui()
                
                worker = JobWorker(job, None)
                worker.veo_bearer = v_acc.api_key
                worker.veo_project_id = v_acc.proxy_url
                worker.captcha_bridge = getattr(self, "captcha_bridge", None)
                
                worker.progress_sig.connect(self.on_worker_progress)
                worker.status_sig.connect(self.on_worker_status)
                worker.log_sig.connect(self.on_worker_log)
                
                self.active_workers[job.id] = worker
                worker.start()
                
                if len(self.active_workers) >= self.concurrency_limit:
                    break
                continue

            # Filter active accounts based on the job's model prefix
            is_codex = "gpt-image" in job.model
            required_prefix = "Codex" if is_codex else "Grok"
            allowed_accs = [a for a in self.acc_mgr.active if a.name.startswith(required_prefix)]

            if not allowed_accs:
                self.log_global(f"❌ Không tìm thấy tài khoản {required_prefix} hoạt động để chạy job {job.id} ({job.model})!")
                job.status = "failed"
                job.error = f"Chưa bật tài khoản {required_prefix}"
                self.refresh_queue_ui()
                continue

            # Select the next account from allowed ones using round-robin per account type
            if not hasattr(self, "_acc_round_robin_indices"):
                self._acc_round_robin_indices = {}
            idx = self._acc_round_robin_indices.get(required_prefix, 0)
            acc = allowed_accs[idx % len(allowed_accs)]
            self._acc_round_robin_indices[required_prefix] = idx + 1

            # Kiểm tra Cooldown 6s trên cùng 1 account để tránh rate limit xAI (chỉ áp dụng cho tài khoản Grok)
            if required_prefix == "Grok":
                last_time = self.account_last_submit.get(acc.name, 0)
                elapsed = time.time() - last_time
                if elapsed < COOLDOWN_DELAY:
                    # Account này đang cooldown, tiếp tục quét tìm account hoặc bỏ qua tick này
                    continue

            # Lock account & job
            self.account_last_submit[acc.name] = time.time()
            job.status = "scheduled"
            job.account_name = acc.name
            self.refresh_queue_ui()

            # Start worker thread
            client = GrokClient(acc.proxy_url, acc.api_key)
            worker = JobWorker(job, client)
            
            # Kết nối tín hiệu
            worker.progress_sig.connect(self.on_worker_progress)
            worker.status_sig.connect(self.on_worker_status)
            worker.log_sig.connect(self.on_worker_log)

            self.active_workers[job.id] = worker
            worker.start()
            
            # Nếu đã đầy luồng song song thì dừng quét
            if len(self.active_workers) >= self.concurrency_limit:
                break

    def on_worker_progress(self, job_id, pct):
        for j in self.queue:
            if j.id == job_id:
                j.progress_val = pct
                self.refresh_queue_ui()
                break

    def on_worker_log(self, text):
        self.log_global(text)

    def on_worker_status(self, job_id, status, error_path):
        # Tìm job
        job_obj = None
        for j in self.queue:
            if j.id == job_id:
                job_obj = j
                break

        if job_obj:
            self.queue.remove(job_obj)
            self.history.insert(0, job_obj)
            self.save_history_to_disk()

            if status == "done":
                # Trích xuất thumbnail (chỉ cho video, ảnh thì dùng luôn)
                if "image" not in job_obj.model:
                    self.extract_thumbnail_pyqt(job_id, job_obj.local_path)
            
            self.refresh_queue_ui()
            self.refresh_gallery_ui()

        # Dọn dẹp luồng chạy xong
        self.active_workers.pop(job_id, None)
        self.refresh_sidebar_acc_lbl()
        self.refresh_accounts_label_studio()


